window.__HSK_CHAPTER_DATA__['chapter_15'] = [{"meanings_summary": {"en": "to fight on paper; armchair strategy; empty theorizing divorced from reality", "es": "hacer la guerra sobre el papel; teorizar en el vacío; estrategia de sillón"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Discussing troops and war (谈兵) purely upon written paper (纸上) without battle experience is armchair strategy (纸上谈兵).", "composite_memory_hook_es": "Debatir sobre tropas y tácticas (谈兵) únicamente sobre el papel (纸上) sin experiencia real es teorizar en el vacío (纸上谈兵).", "cultural_and_cognitive_roots": "Originates from Sima Qian's 'Records of the Grand Historian' describing Zhao Kuo's disastrous generalship at the Battle of Changping (260 BC).", "tone_sandhi_and_pitch_modulation": "Four tones: 'zhǐ shàng tán bīng' (214-51-35-55). Dip on 'zhǐ', drop sharply on 'shàng', rise on 'tán', and conclude high on 'bīng'."}, "semantic_boundary_contrasts": {"core_nuance": "纸上谈兵 mocks bookish theorists who recite dogma fluently but disastrously botch real-world application.", "contrasts": [{"id": "1", "compared_word": "纸上谈兵 vs. 实战经验", "pinyin": "shízhàn jīngyàn", "analysis": "实战经验 denotes battle-tested pragmatic capability, the exact remedy for 纸上谈兵."}, {"id": "2", "compared_word": "纸上谈兵 vs. 按图索骥", "pinyin": "àn tú suǒ jì", "analysis": "按图索骥 criticizes inflexible rule-following, while 纸上谈兵 highlights empty talk lacking battlefield competence."}, {"id": "3", "compared_word": "纸上谈兵 vs. 身体力行", "pinyin": "shēntǐ-lìxíng", "analysis": "身体力行 is the direct antonym meaning to personally practice and implement ideas in deed."}]}, "traps_and_cognates": {"look_alikes": [{"character": "低", "pinyin": "dī", "meaning_en": "low; beneath", "distinction_note": "Person radical 亻 on left instead of 纟"}, {"character": "卡", "pinyin": "kǎ", "meaning_en": "card; block", "distinction_note": "Upper stroke pointing down combined with 上"}, {"character": "淡", "pinyin": "dàn", "meaning_en": "bland; pale", "distinction_note": "Water radical 氵 on left instead of 讠"}, {"character": "乒", "pinyin": "pīng", "meaning_en": "ping (table tennis)", "distinction_note": "Has only left leg stroke, missing right leg"}], "etymological_cognates": [{"character": "报纸", "pinyin": "bàozhǐ", "gloss_en": "newspaper"}, {"character": "谈话", "pinyin": "tánhuà", "gloss_en": "conversation; talk"}, {"character": "士兵", "pinyin": "shìbīng", "gloss_en": "soldier; rank-and-file"}, {"character": "兵法", "pinyin": "bīngfǎ", "gloss_en": "art of war; military strategy"}]}, "id": "1", "hanzi": "纸上谈兵", "pinyin": "zhǐ shàng tán bīng", "level": "HSK 5", "part_of_speech": "Idiom", "senses": [{"sense_number": "1", "part_of_speech": "Idiom", "register": "Standard", "definition_en": "to discuss military affairs on paper without practical combat experience; refers to engaging in unrealistic idle theorizing", "definition_es": "discutir tácticas militares sobre el papel sin experiencia real; teorizar al margen de la práctica", "example_phrase": "纯属纸上谈兵 (purely armchair theorizing on paper)"}], "example_sentences": [{"id": "#1", "hanzi": "战国时期的赵括只会死记兵书却不懂灵活应变，在长平之战中纸上谈兵，最终导致赵军惨败。", "pinyin": "Zhànguó shíqī de Zhào Kuò zhǐ huì sǐjì bīngshū què bù dǒng línghuó yìngbiàn, zài Chángpíng zhī zhàn zhōng zhǐshàng-tánbīng, zuìzhōng dǎozhì Zhàojūn cǎibài.", "en": "During the Warring States period, Zhao Kuo memorized military texts by rote without flexible adaptation; fighting on paper at Changping, he caused his army's total defeat.", "es": "En los Reinos Combatientes, Zhao Kuo memorizó tratados bélicos sin saber adaptarse; su estrategia sobre el papel en Changping causó una hecatombe."}, {"id": "#2", "hanzi": "搞科学研究决不能停留在纸上谈兵，必须深入实验室和一线现场开展扎扎实实的实践验证。", "pinyin": "Gǎo kēxué yánjiū juébùnéng tíngliú zài zhǐshàng-tánbīng, bìxū shēnrù shíyànshì hé yīxiàn xiànchǎng kāizhǎn zhāzhā-shíshí de shíjiàn yànzhèng.", "en": "Scientific research must never linger on paper theories; researchers must go deep into labs and field sites for rigorous empirical testing.", "es": "La labor científica no puede estancarse en elucubraciones teóricas; exige verificar las hipótesis sobre el terreno y en el laboratorio."}], "collocations": [{"hanzi": "纯属纸上谈兵", "en": "purely armchair theorizing"}, {"hanzi": "切忌纸上谈兵", "en": "strictly avoid fighting on paper"}, {"hanzi": "不是纸上谈兵", "en": "not mere idle paper talk"}, {"hanzi": "纸上谈兵的空论", "en": "empty armchair theorizing"}, {"hanzi": "克服纸上谈兵", "en": "overcome empty armchair talk"}, {"hanzi": "沦为纸上谈兵", "en": "degenerate into paper theorizing"}], "idioms": [{"hanzi": "纸上谈兵", "pinyin": "zhǐ shàng tán bīng", "meaning_en": "armchair strategy; empty theorizing"}, {"hanzi": "按图索骥", "pinyin": "àn tú suǒ jì", "meaning_en": "look for a steed according to a sketch; dogmatic approach"}, {"hanzi": "实事求是", "pinyin": "shí shì qiú shì", "meaning_en": "seek truth from facts; pragmatic and realistic"}, {"hanzi": "坐而论道", "pinyin": "zuò ér lùn dào", "meaning_en": "sit and talk philosophy without taking action"}], "character_decomposition": [{"character": "纸", "pinyin": "zhǐ", "meaning_en": "paper", "meaning_es": "papel", "radical": "纟", "radical_meaning_en": "silk / fiber", "meaning_component": "纟 (plant silk fibers) + 氏 (pressing mallet / clan surface)", "sound_component": "氏 (shì / zhǐ)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Plant and silk fibers 纟 beaten flat into thin writing sheets 氏; represents paper.", "visual_mnemonic_story_en": "Beating fine silk and plant fibers (纟) into smooth flat sheets of writing paper (纸).", "visual_mnemonic_story_es": "Prensando fibras de seda vegetal (纟) hasta obtener hojas lisas de papel para escribir (纸).", "tone_mnemonic_anchor": "214", "cangjie": "VMHVP", "traditional": "紙"}, {"character": "上", "pinyin": "shàng", "meaning_en": "on; upon; above; upper", "meaning_es": "sobre; encima; arriba; superior", "radical": "一", "radical_meaning_en": "one / baseline", "meaning_component": "horizontal baseline 一 with an indicator stroke pointing above", "sound_component": "上 (shàng)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient ideograph with a horizontal baseline 一 and a vertical mark standing above it.", "visual_mnemonic_story_en": "A pointer stroke rising upright above the horizontal horizon line (上).", "visual_mnemonic_story_es": "Un trazo vertical que se yergue por encima de la línea base del horizonte (上).", "tone_mnemonic_anchor": "51", "cangjie": "YMY", "traditional": "上"}, {"character": "谈", "pinyin": "tán", "meaning_en": "talk; converse; discuss; speak", "meaning_es": "hablar; conversar; platicar; discutir", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (spoken words) + 炎 (blazing flame / glowing warmth)", "sound_component": "炎 (yán)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Words 讠 exchanged with glowing, lively enthusiasm like warm burning fires 炎; to discuss.", "visual_mnemonic_story_en": "Words of speech (讠) sparking animated warmth like burning campfire flames (谈).", "visual_mnemonic_story_es": "Palabras orales (讠) que desprenden el entusiasmo cálido del fuego que arde al conversar (谈).", "tone_mnemonic_anchor": "35", "cangjie": "IVFF", "traditional": "談"}, {"character": "兵", "pinyin": "bīng", "meaning_en": "soldier; weapons; military; troops", "meaning_es": "soldado; armas; militar; tropas", "radical": "八", "radical_meaning_en": "eight", "meaning_component": "斤 (sharp bronze axe) + 廾/八 (two hands gripping it)", "sound_component": "兵 (bīng)", "stroke_count": "7", "composition_type": "上下结构", "etymology_and_mnemonic": "Two hands 廾 firmly gripping a battleaxe 斤; represents a soldier or weapon of war.", "visual_mnemonic_story_en": "Two warrior hands raising a sharp battleaxe (斤) ready to defend the realm (兵).", "visual_mnemonic_story_es": "Dos manos firmes que alzan un hacha de combate (斤) dispuestas a defender las armas (兵).", "tone_mnemonic_anchor": "55", "cangjie": "OMC", "traditional": "兵"}], "extended_reading_passages": [{"id": "#1", "hanzi": "战国名将赵奢深谙兵法，其子赵括自幼熟读兵书，谈起用兵之道口若悬河。然而赵奢却预言赵括必败，因为他把战场厮杀视同儿戏。长平之战中赵括盲目出击，惨遭秦军合围，成为后世讽刺“纸上谈兵”的惨痛教训。", "pinyin": "Zhànguó míngjiàng Zhào Shē shēn'ān bīngfǎ, qí zǐ Zhào Kuò zìyòu shúdú bīngshū, tán qǐ yòngbīng zhī dào kǒuruò-xuánhé. Rán'ér Zhào Shē què yùyán Zhào Kuò bì bài, yīnwèi tā bǎ zhànchǎng sīshā shìtóng érxì. Chángpíng zhī zhàn zhōng Zhào Kuò mángmù chūjī, cǎnzāo Qínjūn héwéi, chéngwéi hòushì fěngcì 'zhǐshàng-tánbīng' de cǎntòng jiàoxun.", "en": "General Zhao She was versed in strategy; his son Zhao Kuo recited military tactics effortlessly. Yet Zhao She foretold his son's doom for treating war lightly. Zhao Kuo's blunder at Changping became the tragic symbol of 'fighting on paper.'", "es": "El general Zhao She dominaba la táctica; su hijo Zhao Kuo recitaba tratados con soltura. Pero Zhao She predijo su fracaso por tomar la guerra como un juego. El desastre de Zhao Kuo en Changping se convirtió en trágico escarmiento."}, {"id": "#2", "hanzi": "在现代企业管理与经济决策中，“纸上谈兵”同样是一大忌讳。再完美的商业策划方案，如果脱离了真实的市场需求与一线调研，最终都只能沦为空洞的设想。唯有深入基层倾听用户心声，在实践中检验真理，方能行稳致远。", "pinyin": "Zài xiàndài qǐyè guǎnlǐ yǔ jīngjì juécè zhōng, 'zhǐshàng-tánbīng' tóngyàng shì yī dà jìhuì. Zài wánměi de shāngyè cèhuà fāng'àn, rúguǒ tuōlí le zhēnshí de shìchǎng xūqiú yǔ yīxiàn diàoyán, zuìzhōng dōu zhǐnéng lúnwéi kōngdòng de shèxiǎng. Wéiyǒu shēnrù jīcéng qīngtīng yònghù xīnshēng, zài shíjiàn zhōng jiǎnyàn zhēnlǐ, fāng néng xíngwěn-zhìyuǎn.", "en": "In corporate management, 'fighting on paper' remains a perilous pitfall. No matter how flawless a business proposal appears, divorcing it from market research renders it an empty fantasy. Only testing ideas on the ground yields success.", "es": "En la gestión corporativa, teorizar sobre el papel acarrea graves tropiezos. Por impecable que luzca un plan de negocio, si desoye el mercado real queda en vana quimera; solo el examen directo con los usuarios garantiza el éxito."}]}, {"meanings_summary": {"en": "military affairs; military matters; army defense", "es": "asuntos militares; milicia; arte de la guerra"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Chariots encamped for war (军) combined with administrative governance affairs (事) form military matters (军事).", "composite_memory_hook_es": "Los carros acampados para la batalla (军) unidos a la gestión oficial (事) definen la ciencia militar (军事).", "cultural_and_cognitive_roots": "A cornerstone domain of ancient governance: 'The major affairs of state are ritual sacrifice and military defense' (国之大事，在祀与戎).", "tone_sandhi_and_pitch_modulation": "First tone to fourth tone: 'jūn shì' (55-51). Hold 'jūn' high and firm, then drop decisively on 'shì'."}, "semantic_boundary_contrasts": {"core_nuance": "军事 specifically encompasses strategic, tactical, and organizational affairs of national defense and armed forces.", "contrasts": [{"id": "1", "compared_word": "军事 vs. 政治", "pinyin": "zhèngzhì", "analysis": "政治 governs statecraft, law, and ideology, while 军事 represents armed defense instrumentalities."}, {"id": "2", "compared_word": "军事 vs. 民事", "pinyin": "mínshì", "analysis": "民事 deals with civil laws, domestic contracts, and citizens' rights, contrasted with armed 军事."}, {"id": "3", "compared_word": "军事 vs. 战争", "pinyin": "zhànzhēng", "analysis": "战争 refers to the armed conflict state itself, while 军事 covers the broader scientific institution, logistics, and doctrines."}]}, "traps_and_cognates": {"look_alikes": [{"character": "车", "pinyin": "chē", "meaning_en": "vehicle; car", "distinction_note": "Lacks the top canopy cover 冖"}, {"character": "挥", "pinyin": "huī", "meaning_en": "wave; wield", "distinction_note": "Hand radical 扌 on left of 军"}, {"character": "吏", "pinyin": "lì", "meaning_en": "petty official", "distinction_note": "Lacks the central horizontal bars of 事"}, {"character": "中", "pinyin": "zhōng", "meaning_en": "middle", "distinction_note": "Single vertical stroke through 口 box"}], "etymological_cognates": [{"character": "军队", "pinyin": "jūnduì", "gloss_en": "armed forces; army"}, {"character": "军官", "pinyin": "jūnguān", "gloss_en": "military officer"}, {"character": "事务", "pinyin": "shìwù", "gloss_en": "general affairs; matters"}, {"character": "事情", "pinyin": "shìqing", "gloss_en": "affair; matter; thing"}]}, "id": "2", "hanzi": "军事", "pinyin": "jūn shì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "affairs, activities, equipment, and operations relating to armed forces, warfare, and national defense", "definition_es": "actividades, pertrechos y operaciones relativas a las fuerzas armadas, la guerra y la defensa nacional", "example_phrase": "军事演习 (military exercise)"}], "example_sentences": [{"id": "#1", "hanzi": "战国时期的著名军事家孙武所著的《孙子兵法》，被誉为世界上最古老而深刻的军事理论经典。", "pinyin": "Zhànguó shíqī de zhùmíng jūnshìjiā Sūn Wǔ suǒ zhù de Sūnzǐ Bīngfǎ, bèi yù wéi shìjiè shang zuì gǔlǎo ér shēnkè de jūnshì lǐlùn jīngdiǎn.", "en": "The Art of War, authored by renowned military strategist Sun Wu, is hailed as the world's oldest and most profound military theory classic.", "es": "El arte de la guerra, escrito por el insigne militar Sun Wu, es ensalzado como el tratado de estrategia bélica más antiguo y profundo del orbe."}, {"id": "#2", "hanzi": "两国边境防务代表团就共同关心的军事安全问题举行了坦诚而深入的会谈。", "pinyin": "Liǎng guó biānjìng fángwù dàibiǎotuán jiù gòngtóng guānxīn de jūnshì ānquán wèntí jǔxíng le tǎncéng ér shēnrù de huìtán.", "en": "Border defense delegations from both countries held candid, in-depth talks on shared military and security concerns.", "es": "Delegaciones fronterizas de ambos países mantuvieron un diálogo franco y pormenorizado sobre asuntos de seguridad y defensa militar."}], "collocations": [{"hanzi": "军事行动", "en": "military operation"}, {"hanzi": "军事基地", "en": "military base"}, {"hanzi": "军事演习", "en": "military drill / exercise"}, {"hanzi": "军事力量", "en": "military power / capability"}, {"hanzi": "军事技术", "en": "military technology"}, {"hanzi": "军事专家", "en": "military expert"}], "idioms": [{"hanzi": "兵戎相见", "pinyin": "bīng róng xiāng jiàn", "meaning_en": "meet each other with weapons; go to war"}, {"hanzi": "投笔从戎", "pinyin": "tóu bǐ cóng róng", "meaning_en": "throw aside the pen and join the army"}, {"hanzi": "运筹帷幄", "pinyin": "yùn chóu wéi wò", "meaning_en": "devise strategies within a military tent; masterminding victory"}, {"hanzi": "厉兵秣马", "pinyin": "lì bīng mò mǎ", "meaning_en": "sharpen weapons and feed horses; prepare for combat"}], "character_decomposition": [{"character": "军", "pinyin": "jūn", "meaning_en": "army; military; armed forces", "meaning_es": "ejército; militar; fuerzas armadas", "radical": "冖", "radical_meaning_en": "cover", "meaning_component": "冖 (military tent/encampment cover) + 车 (war chariots)", "sound_component": "军 (jūn)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "War chariots 车 marshaled beneath protective encampment pavilions 冖; signifies an army.", "visual_mnemonic_story_en": "War chariots (车) gathered securely under an army pavilion shelter (冖) ready for battle (军).", "visual_mnemonic_story_es": "Carros de combate (车) guarnecidos bajo el pabellón de campaña (冖) listos para la marcha (军).", "tone_mnemonic_anchor": "55", "cangjie": "BKJ", "traditional": "軍"}, {"character": "事", "pinyin": "shì", "meaning_en": "matter; thing; business; affair", "meaning_es": "asunto; materia; quehacer; labor", "radical": "亅", "radical_meaning_en": "hook", "meaning_component": "hand holding an official tally stylus or scribe's recording tablet", "sound_component": "事 (shì)", "stroke_count": "8", "composition_type": "单一结构", "etymology_and_mnemonic": "An official scribe holding up a record brush or tally board to record court state affairs.", "visual_mnemonic_story_en": "An officer holding up an administrative record stylus (事) to oversee affairs.", "visual_mnemonic_story_es": "Un escriba alzando una tablilla oficial para registrar los asuntos de gobierno (事).", "tone_mnemonic_anchor": "51", "cangjie": "JXLN", "traditional": "事"}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古代军事理论历史悠久、博大精深。《孙子兵法》强调“兵者，国之大事，死生之地，存亡之道，不可不察也”。它主张以谋略胜敌，强调“不战而屈人之兵”的高超境界，成为历代军事家推崇的至高典范。", "pinyin": "Zhōngguó gǔdài jūnshì lǐlùn lìshǐ yōujiǔ, bódà-jīngshēn. Sūnzǐ Bīngfǎ qiángdiào 'Bīng zhě, guó zhī dàshì, sǐshēng zhī dì, cúnwáng zhī dào, bùkě bù chá yě'. Tā zhǔzhāng yǐ móulüè shèng dí, qiángdiào 'bù zhàn ér qū rén zhī bīng' de gāochāo jìngjiè, chéngwéi lìdài jūnshìjiā tuīchóng de zhìgāo diǎnfàn.", "en": "Ancient Chinese military theory has a long and profound history. Sunzi stressed: 'Military affairs are vital to the state—the realm of life and death, the road to survival.' It championed outwitting enemies and subduing them without fighting.", "es": "La doctrina militar clásica china goza de una hondura milenaria. Sun Tzu subrayó: 'La guerra es el asunto primordial del Estado, el terreno de la vida y la muerte.' Abogó por vencer al enemigo mediante estratagemas sin librar combate."}, {"id": "#2", "hanzi": "进入现代信息技术时代，军事科技的迅猛发展正在深刻重塑现代战争形态。无人作战平台、人工智能指挥网络以及太空防御系统，成为各大国军事现代化建设的前沿焦点。强大的综合军事实力，是捍卫国家和平安宁的坚强盾牌。", "pinyin": "Jìnrù xiàndài xìnxī jìshù shídài, jūnshì kējì de xùnměng fāzhǎn zhèngzài shēnkè zhòngsù xiàndài zhànzhēng xíngtài. Wúrén zuòzhàn píngtái, réngōng zhìnéng zhǐhuī wǎngluò yǐjí tàikōng fángyù xìtǒng, chéngwéi gè dàguó jūnshì xiàndàihuà jiànshè de qiányán jiāodiǎn. Qiángdà de zōnghé jūnshì shílì, shì hànwèi guójiā hépíng ānníng de jiānqiáng dùnpái.", "en": "In the information age, rapid advances in military technology reshape modern warfare. Unmanned combat units, AI command networks, and space defense stand at the forefront of military modernization, shielding national sovereignty and peace.", "es": "En la era de la información, el salto tecnológico transforma el arte bélico. Plataformas no tripuladas, redes de mando con IA y defensa aeroespacial lideran la vanguardia militar, protegiendo la paz y la soberanía patria."}]}, {"meanings_summary": {"en": "enemy; foe; opponent; adversary", "es": "enemigo; adversario; rival hostil"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A hostile adversary facing you in combat (敌) who is a human person (人) is an enemy (敌人).", "composite_memory_hook_es": "Un contrincante hostil que empuña las armas (敌) encarnado en persona (人) define al enemigo (敌人).", "cultural_and_cognitive_roots": "Derived from classical interstate wars where adversaries met in battle, extended figuratively to obstacles and vices.", "tone_sandhi_and_pitch_modulation": "Double second tone: 'dí rén' (35-35). Rise cleanly on both syllables with steady cadence."}, "semantic_boundary_contrasts": {"core_nuance": "敌人 carries acute hostility, animosity, or lethal confrontation.", "contrasts": [{"id": "1", "compared_word": "敌人 vs. 朋友", "pinyin": "péngyou", "analysis": "朋友 is the direct antonym meaning a friendly companion or trusted ally."}, {"id": "2", "compared_word": "敌人 vs. 对手", "pinyin": "duìshǒu", "analysis": "对手 refers to sporting or business rivals who compete without wishing each other's physical destruction, unlike 敌人."}, {"id": "3", "compared_word": "敌人 vs. 仇人", "pinyin": "chóurén", "analysis": "仇人 stresses intense personal hatred/vendetta, whereas 敌人 can be a broad military or political adversary."}]}, "traps_and_cognates": {"look_alikes": [{"character": "故", "pinyin": "gù", "meaning_en": "old; cause", "distinction_note": "Old 古 on left instead of 啇"}, {"character": "政", "pinyin": "zhèng", "meaning_en": "politics", "distinction_note": "Correct 正 on left instead of 啇"}, {"character": "入", "pinyin": "rù", "meaning_en": "enter", "distinction_note": "Right stroke overlaps left stroke"}, {"character": "大", "pinyin": "dà", "meaning_en": "big", "distinction_note": "Horizontal bar across 人"}], "etymological_cognates": [{"character": "敌手", "pinyin": "díshǒu", "gloss_en": "match; opponent; rival"}, {"character": "敌对", "pinyin": "díduì", "gloss_en": "hostile; antagonistic"}, {"character": "情敌", "pinyin": "qíngdí", "gloss_en": "romantic rival"}, {"character": "强敌", "pinyin": "qiángdí", "gloss_en": "formidable foe"}]}, "id": "3", "hanzi": "敌人", "pinyin": "dí rén", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a person, hostile group, or opposing army that seeks to harm, defeat, or conquer another", "definition_es": "persona, facción armada o fuerza hostil que busca dañar, vencer o destruir a otra", "example_phrase": "消灭敌人 (wipe out the enemy)"}], "example_sentences": [{"id": "#1", "hanzi": "在古代战争中，优秀的将领必须知己知彼，准确洞察敌人的战略意图与防守弱点。", "pinyin": "Zài gǔdài zhànzhēng zhōng, yōuxiù de jiànglǐng bìxū zhījǐ-zhībǐ, zhǔnquè dòngchá dírén de zhànlüè yìtú yǔ fángshǒu ruòdiǎn.", "en": "In ancient warfare, competent commanders had to know themselves and the enemy, accurately discerning foes' strategic intents and defenses.", "es": "En la guerra clásica, los buenos generales debían conocerse a sí mismos y al adversario, detectando las intenciones y flaquezas del enemigo."}, {"id": "#2", "hanzi": "拖延和懒惰是我们在求学与自我成长道路上必须时刻警惕并战胜的无形敌人。", "pinyin": "Tuōyán hé lǎnduò shì wǒmen zài qiúxué yǔ zìwǒ chéngzhǎng dàolù shang bìxū shíkè jǐngtì bìng zhànshèng de wúxíng dírén.", "en": "Procrastination and indolence are invisible enemies that we must constantly guard against and overcome on our road to self-growth.", "es": "La desidia y la procrastinación constituyen enemigos invisibles a los que debemos combatir con tesón en nuestro desarrollo personal."}], "collocations": [{"hanzi": "消灭敌人", "en": "eliminate / defeat the enemy"}, {"hanzi": "顽强的敌人", "en": "tenacious / stubborn enemy"}, {"hanzi": "共同的敌人", "en": "common enemy"}, {"hanzi": "化敌为友", "en": "turn foes into friends"}, {"hanzi": "敌人的阴谋", "en": "enemy's conspiracy / plot"}, {"hanzi": "面对敌人", "en": "confront the enemy"}], "idioms": [{"hanzi": "知己知彼，百战不殆", "pinyin": "zhī jǐ zhī bǐ, bǎi zhàn bù dài", "meaning_en": "know yourself and know your enemy, and you will never be defeated"}, {"hanzi": "克敌制胜", "pinyin": "kè dí zhì shèng", "meaning_en": "overcome the enemy and secure victory"}, {"hanzi": "同仇敌忾", "pinyin": "tóng chóu dí kài", "meaning_en": "share common hatred against a mortal foe"}, {"hanzi": "化敌为友", "pinyin": "huà dí wéi yǒu", "meaning_en": "turn an enemy into a loyal friend"}], "character_decomposition": [{"character": "敌", "pinyin": "dí", "meaning_en": "enemy; resist; match; equal", "meaning_es": "enemigo; resistir; rivalizar; igualar", "radical": "攵", "radical_meaning_en": "tap / strike", "meaning_component": "啇 (stalk of wheat / opponent across river) + 攵 (striking weapon)", "sound_component": "啇 (dī)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Striking with weapons 攵 against an opposing rival 啇 across the front line; marks an adversary.", "visual_mnemonic_story_en": "Striking with an iron weapon (攵) to repel a hostile opponent attacking the stronghold (敌).", "visual_mnemonic_story_es": "Blandir un arma (攵) para repeler al contendiente hostil que ataca la muralla (敌).", "tone_mnemonic_anchor": "35", "cangjie": "YBOK", "traditional": "敵"}, {"character": "人", "pinyin": "rén", "meaning_en": "person; human", "meaning_es": "persona; humano", "radical": "人", "radical_meaning_en": "person", "meaning_component": "profile pictograph of a human walking", "sound_component": "人 (rén)", "stroke_count": "2", "composition_type": "单一结构", "etymology_and_mnemonic": "Profile of a walking person with arms and legs.", "visual_mnemonic_story_en": "An upright walking human being (人).", "visual_mnemonic_story_es": "Un ser humano que marcha erguido (人).", "tone_mnemonic_anchor": "35", "cangjie": "O", "traditional": "人"}], "extended_reading_passages": [{"id": "#1", "hanzi": "战国末期秦赵长平之战，秦军主帅白起针对赵括缺乏实战经验的弱点，假装败退诱敌深入。骄傲轻敌的赵括误以为敌人溃退，盲目率大军追击，结果主力被秦军切断后路，四十万赵军最终陷入绝境而全军覆没。", "pinyin": "Zhànguó mòqī Qín-Zhào Chángpíng zhī zhàn, Qínjūn zhǔshuài Bái Qǐ zhēnduì Zhào Kuò quēfá shízhàn jīngyàn de ruòdiǎn, jiǎzhuāng bàituì yòudí shēnrù. Jiāo'ào qīngdí de Zhào Kuò wùyǐwéi dírén kuìtuì, mángmù shuài dàjūn zhuījī, jiéguǒ zhǔlì bèi Qínjūn qiēduàn hòulù, sìshí wàn Zhàojūn zuìzhōng xiànrù juéjìng ér quánjūn-fùmò.", "en": "At the Battle of Changping, Qin General Bai Qi feigned retreat to lure the enemy, knowing Zhao Kuo's inexperience. Arrogant Zhao Kuo pursued rashly, believing the enemy routed, only for his 400,000 troops to be encircled and annihilated.", "es": "En la batalla de Changping, el general Bai Qi fingió huir para atraer al inexperto Zhao Kuo. Confiado, Zhao Kuo persiguió al supuesto enemigo en desbandada, viendo a sus 400.000 soldados rodeados y aniquilados sin remedio."}, {"id": "#2", "hanzi": "在人生的漫长征程中，最可怕的敌人往往不是外界的强劲竞争对手，而是潜藏于内心的傲慢、恐惧与懈怠。学会战胜自满、勇于克服懒惰，将内心的软弱转化为前进的动力，我们才能成为自己命运真正的主宰者。", "pinyin": "Zài rénshēng de màncháng zhēngchéng zhōng, zuì kěpà de dírén wǎngwǎng bùshì wàijiè de qiángjìn jìngzhēng duìshǒu, ér shì qiáncáng yú nèixīn de àomàn, kǒngjù yǔ xièdài. Xuéhuì zhànshèng zìmǎn, yǒngyú kèfú lǎnduò, jiāng nèixīn de ruǎnruò huàwéi qiánjìn de dònglì, wǒmen cái néng chéngwéi zìjǐ mìngyùn zhēnzhèng de zhǔzǎizhě.", "en": "On the long journey of life, the most fearsome enemy is often not an external adversary, but the arrogance, fear, and indolence lurking within. Conquering self-satisfaction and converting weakness into momentum makes us true masters of destiny.", "es": "En el camino de la vida, el enemigo más temible no suele ser el adversario externo, sino la soberbia, el temor y la holgazanería interior. Vencer la autocomplacencia y mudar la flaqueza en empuje nos convierte en dueños de nuestro destino."}]}, {"meanings_summary": {"en": "theory; theoretical system; to argue/debate", "es": "teoría; cuerpo teórico; teorizar; discutir razones"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The intrinsic logic of things (理) expounded in systematic discourse (论) forms a theory (理论).", "composite_memory_hook_es": "La lógica interna de las cosas (理) expuesta en discurso ordenado (论) constituye una teoría (理论).", "cultural_and_cognitive_roots": "Blends Neo-Confucian 'Principle' (天理) with classical rhetoric and modern scientific epistemologies.", "tone_sandhi_and_pitch_modulation": "Third tone to fourth tone: 'lǐ lùn' (214-51). Dip deeply on 'lǐ', then drop with academic firmness on 'lùn'."}, "semantic_boundary_contrasts": {"core_nuance": "理论 emphasizes systematic abstract knowledge and conceptual principles explaining reality.", "contrasts": [{"id": "1", "compared_word": "理论 vs. 实践", "pinyin": "shíjiàn", "analysis": "实践 is the direct antonym meaning hands-on practical action and empirical testing."}, {"id": "2", "compared_word": "理论 vs. 经验", "pinyin": "jīngyàn", "analysis": "经验 refers to accumulated perceptual know-how, while 理论 represents systematized conceptual laws."}, {"id": "3", "compared_word": "理论 vs. 空想", "pinyin": "kōngxiǎng", "analysis": "空想 is baseless day-dreaming, whereas genuine 理论 is rooted in empirical validation."}]}, "traps_and_cognates": {"look_alikes": [{"character": "埋", "pinyin": "mái", "meaning_en": "bury; inter", "distinction_note": "Soil radical 土 on left of 里 instead of 王"}, {"character": "轮", "pinyin": "lún", "meaning_en": "wheel; rotate", "distinction_note": "Vehicle radical 车 on left instead of 讠"}, {"character": "伦", "pinyin": "lún", "meaning_en": "ethics; relation", "distinction_note": "Person radical 亻 on left instead of 讠"}, {"character": "沦", "pinyin": "lún", "meaning_en": "sink; degenerate", "distinction_note": "Water radical 氵 on left instead of 讠"}], "etymological_cognates": [{"character": "理解", "pinyin": "lǐjiě", "gloss_en": "understand; comprehend"}, {"character": "道理", "pinyin": "dàolǐ", "gloss_en": "principle; reason"}, {"character": "讨论", "pinyin": "tǎolùn", "gloss_en": "discuss; talk over"}, {"character": "论文", "pinyin": "lùnwén", "gloss_en": "thesis; academic paper"}]}, "id": "4", "hanzi": "理论", "pinyin": "lǐ lùn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a systematic framework of concepts, principles, and laws derived from practice and used to explain phenomena", "definition_es": "conjunto sistemático de leyes, principios y conceptos formulados para explicar fenómenos y guiar la práctica", "example_phrase": "理论与实践相结合 (combine theory with practice)"}], "example_sentences": [{"id": "#1", "hanzi": "科学的理论只有与生产实践紧密结合，才能转化为推动社会生产力发展的强大现实动力。", "pinyin": "Kēxué de lǐlùn zhǐyǒu yǔ shēngchǎn shíjiàn jǐnmì jiéhé, cái néng zhuǎnhuà wéi tuīdòng shèhuì shēngchǎnlì fāzhǎn de qiángdà xiànshí dònglì.", "en": "Scientific theory can only be transformed into a mighty driving force for productive forces when closely integrated with practical production.", "es": "Las teorías científicas solo se convierten en motor del desarrollo cuando se articulan con la práctica transformadora de la producción."}, {"id": "#2", "hanzi": "著名物理学家爱因斯坦提出的相对论理论，深刻彻底地革新了人类关于时间与空间的认知。", "pinyin": "Zhùmíng wùlǐxuéjiā Àiyīnsītǎn tíchū de xiāngduìlùn lǐlùn, shēnkè chèdǐ de géxīn le rénlèi guānyú shíjiān yǔ kōngjiān de rènzhī.", "en": "The theory of relativity formulated by Albert Einstein profoundly and thoroughly revolutionized human understanding of time and space.", "es": "La teoría de la relatividad formulada por Albert Einstein revolucionó de raíz la comprensión humana del tiempo y el espacio."}], "collocations": [{"hanzi": "理论体系", "en": "theoretical framework / system"}, {"hanzi": "理论研究", "en": "theoretical research"}, {"hanzi": "理论与实践", "en": "theory and practice"}, {"hanzi": "基本理论", "en": "fundamental theory"}, {"hanzi": "深化理论", "en": "deepen theory"}, {"hanzi": "理论创新", "en": "theoretical innovation"}], "idioms": [{"hanzi": "言之成理", "pinyin": "yán zhī chéng lǐ", "meaning_en": "spoken with cogent reason and sound logic"}, {"hanzi": "实事求是", "pinyin": "shí shì qiú shì", "meaning_en": "seek truth from practical facts"}, {"hanzi": "据理力争", "pinyin": "jù lǐ lì zhēng", "meaning_en": "argue vigorously on the basis of reason"}, {"hanzi": "通情达理", "pinyin": "tōng qíng dá lǐ", "meaning_en": "fair-minded, reasonable, and sensible"}], "character_decomposition": [{"character": "理", "pinyin": "lǐ", "meaning_en": "reason; logic; order; manage; polish jade", "meaning_es": "razón; lógica; orden; gobernar; pulir jade", "radical": "王", "radical_meaning_en": "jade", "meaning_component": "王/玉 (raw jade stone) + 里 (settlement fields with orderly paths)", "sound_component": "里 (lǐ)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Carving natural veined patterns in raw jade 玉 following structural lines 里; implies intrinsic logic.", "visual_mnemonic_story_en": "Following the natural grain to carve raw jade (玉) into orderly patterns (理).", "visual_mnemonic_story_es": "Seguir las vetas naturales del jade (玉) para pulirlo conforme a una pauta armónica (理).", "tone_mnemonic_anchor": "214", "cangjie": "MGWG", "traditional": "理"}, {"character": "论", "pinyin": "lùn", "meaning_en": "discuss; discourse; debate; theory", "meaning_es": "discutir; disertar; debatir; teoría", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (spoken discourse) + 仑 (bamboo slips bound in logical sequence)", "sound_component": "仑 (lún)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Spoken words 讠 arranged into logical arguments like sequential bound bamboo slips 仑; to theorize.", "visual_mnemonic_story_en": "Words of speech (讠) arranged methodically like bound slips (仑) into an articulate thesis (论).", "visual_mnemonic_story_es": "Palabras (讠) ensambladas metódicamente como tablillas de bambú encuadernadas (仑) para formular una tesis (论).", "tone_mnemonic_anchor": "51", "cangjie": "IVOP", "traditional": "論"}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古代兵书不仅记载了行军布阵的具体战术，更构建了博大精深的军事理论体系。然而先贤再三告诫，高深的军事理论唯有结合瞬息万变的战场实际灵活运用，才能化为克敌制胜的法宝，切不可拘泥于书本死板教条。", "pinyin": "Zhōngguó gǔdài bīngshū bùjǐn jìzǎi le xíngjūn bùzhèn de jùtǐ zhànshù, gèng gòujiàn le bódà-jīngshēn de jūnshì lǐlùn tǐxì. Rán'ér xiānxián zàisān gàojiè, gāoshēn de jūnshì lǐlùn wéiyǒu jiéhé shùnxī-wànbiàn de zhànchǎng shíjì línghuó yùnyòng, cái néng huà wéi kèdí-zhìshèng de fǎbǎo, qiè bùkě jūní yú shūběn sǐbǎn jiàotiáo.", "en": "Ancient military treatises built rich theoretical systems beyond tactical formations. Yet sages cautioned that military theory guarantees victory only when flexibly adapted to fast-changing battlefield conditions, rather than dogmatically followed.", "es": "Los tratados castrenses antiguos forjaron un hondo cuerpo teórico más allá de las formaciones tácticas. No obstante, los maestros advirtieron que la teoría bélica solo triunfa adaptándose a la realidad cambiante del campo de batalla."}, {"id": "#2", "hanzi": "任何重大的科学发现都离不开基础理论的开创性突破。现代量子力学与人工智能算法的飞速发展，无一不是建立在深厚数学物理理论基石之上的。强化基础理论研究，是我们在全球科技竞争中实现原始创新的根本所在。", "pinyin": "Rènhé zhòngdà de kēxué fāxiàn dōu lìbùkāi jīchǔ lǐlùn de kāichuàngxìng tūpò. Xiàndài liàngzǐ lìxué yǔ réngōng zhìnéng suànfǎ de fēisù fāzhǎn, wúyībùshì jiànlì zài shēnhòu shùxué wùlǐ lǐlùn jīshí zhīshàng de. Qiánghuà jīchǔ lǐlùn yánjiū, shì wǒmen zài quánqiú kējì jìngzhēng zhōng shíxiàn yuánshǐ chuàngxīn de gēnběn suǒzài.", "en": "Every breakthrough in science rests upon foundational theoretical advances. Quantum physics and artificial intelligence rely squarely on deep mathematical theories. Strengthening basic theoretical research fuels authentic original innovation.", "es": "Los grandes descubrimientos de la ciencia nacen de avances teóricos de raíz. La física cuántica y la inteligencia artificial se erigen sobre sólidas bases matemáticas; potenciar la investigación teórica es la clave de la innovación."}]}, {"meanings_summary": {"en": "to fight; engage in combat; conduct military operations", "es": "combatir; entrar en combate; librar una batalla; operar militarmente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Actively engaging in deliberate physical action (作) with lethal halberds in war (战) means to conduct combat operations (作战).", "composite_memory_hook_es": "Emprender la acción decidida (作) blandiendo las armas de guerra (战) constituye la acción de combatir (作战).", "cultural_and_cognitive_roots": "Military term emphasizing professional tactical deployment and organized campaign execution, extended metaphorically to crises.", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'zuò zhàn' (51-51). Articulate both syllables with martial, punchy firmness."}, "semantic_boundary_contrasts": {"core_nuance": "作战 designates formal, strategic, and organized military operations by armies or organized units.", "contrasts": [{"id": "1", "compared_word": "作战 vs. 打架", "pinyin": "dǎjià", "analysis": "打架 denotes colloquial physical brawling between individuals, whereas 作战 is organized military warfare."}, {"id": "2", "compared_word": "作战 vs. 停火", "pinyin": "tínghuǒ", "analysis": "停火 is the direct antonym meaning ceasefire or suspension of hostilities."}, {"id": "3", "compared_word": "作战 vs. 演习", "pinyin": "yǎnxí", "analysis": "演习 refers to peacetime practice drills, while 作战 entails authentic enemy combat operations."}]}, "traps_and_cognates": {"look_alikes": [{"character": "昨", "pinyin": "zuó", "meaning_en": "yesterday", "distinction_note": "Sun radical 日 on left instead of 亻"}, {"character": "炸", "pinyin": "zhà", "meaning_en": "explode; deep-fry", "distinction_note": "Fire radical 火 on left instead of 亻"}, {"character": "站", "pinyin": "zhàn", "meaning_en": "stand; station", "distinction_note": "Stand 立 on left instead of 戈 on right"}, {"character": "点", "pinyin": "diǎn", "meaning_en": "dot; point", "distinction_note": "Fire dots 灬 under 占 instead of 戈"}], "etymological_cognates": [{"character": "战斗", "pinyin": "zhàndòu", "gloss_en": "fight; battle; combat"}, {"character": "战场", "pinyin": "zhànchǎng", "gloss_en": "battlefield; war front"}, {"character": "工作", "pinyin": "gōngzuò", "gloss_en": "work; job"}, {"character": "作为", "pinyin": "zuòwéi", "gloss_en": "accomplishment; conduct"}]}, "id": "5", "hanzi": "作战", "pinyin": "zuò zhàn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to conduct military fighting, campaigns, or strategic operations against opposing forces", "definition_es": "entrar en combate armado o desplegar maniobras bélicas y estratégicas contra el enemigo", "example_phrase": "协同作战 (coordinate joint combat operations)"}], "example_sentences": [{"id": "#1", "hanzi": "在复杂多变的高原山地环境中，陆空两军紧密配合，成功完成了联合模拟作战演练。", "pinyin": "Zài fùzá duōbiàn de gāoyuán shāndì huánjìng zhōng, lù-kōng liǎng jūn jǐnmì pèihé, chénggōng wánchéng le liánhé mónǐ zuòzhàn yǎnliàn.", "en": "In complex and variable plateau mountain terrain, army and air forces coordinated closely to successfully execute a joint combat simulation.", "es": "En la quebrada orografía de la meseta, el ejército de tierra y la aviación coordinaron con éxito un ejercicio de combate simulado conjunto."}, {"id": "#2", "hanzi": "经验丰富的特战分队擅长在恶劣天气与黑夜掩护下神速出击，隐蔽开展敌后作战任务。", "pinyin": "Jīngyàn fēngfù de tèzhàn fēnduì shàncháng zài èliè tiānqì yǔ hēiyè yǎnhù xià shénsù chūjī, yǐnbì kāizhǎn díhòu zuòzhàn rènwu.", "en": "Experienced special forces units excel at striking swiftly under foul weather and night cover to conduct covert operations behind enemy lines.", "es": "Las tropas de operaciones especiales dominan el ataque relámpago al amparo de la niebla y la noche para combatir tras las líneas enemigas."}], "collocations": [{"hanzi": "作战方案", "en": "operational plan / battle scheme"}, {"hanzi": "协同作战", "en": "joint / coordinated combat operations"}, {"hanzi": "作战指挥", "en": "combat command and control"}, {"hanzi": "独立作战", "en": "fight independently"}, {"hanzi": "并肩作战", "en": "fight shoulder to shoulder"}, {"hanzi": "作战能力", "en": "combat readiness / fighting capability"}], "idioms": [{"hanzi": "并肩作战", "pinyin": "bìng jiān zuò zhàn", "meaning_en": "fight shoulder to shoulder in solidarity"}, {"hanzi": "各自为战", "pinyin": "gè zì wéi zhàn", "meaning_en": "each fighting on one's own without coordination"}, {"hanzi": "背水一战", "pinyin": "bèi shuǐ yī zhàn", "meaning_en": "fight with one's back to the river; do or die battle"}, {"hanzi": "孤军作战", "pinyin": "gū jūn zuò zhàn", "meaning_en": "fight as an isolated force without reinforcements"}], "character_decomposition": [{"character": "作", "pinyin": "zuò", "meaning_en": "do; make; act; write; work", "meaning_es": "hacer; actuar; elaborar; escribir", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person standing) + 乍 (burst into active motion / collar incision)", "sound_component": "乍 (zhà)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 springing into energetic action 乍 to create or do something; signifies purposeful action.", "visual_mnemonic_story_en": "A person (亻) springing into proactive action to undertake an assignment (作).", "visual_mnemonic_story_es": "Una persona (亻) que se pone en acción decidida para acometer una faena (作).", "tone_mnemonic_anchor": "51", "cangjie": "OHS", "traditional": "作"}, {"character": "战", "pinyin": "zhàn", "meaning_en": "war; battle; fight; combat", "meaning_es": "guerra; batalla; luchar; combatir", "radical": "戈", "radical_meaning_en": "dagger-axe / halberd", "meaning_component": "占 (oracle divination / seizing territory) + 戈 (striking halberd)", "sound_component": "占 (zhàn)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Wielding bronze halberds 戈 in battle to conquer territory designated by divination 占; signifies armed war.", "visual_mnemonic_story_en": "Warriors brandishing sharp halberds (戈) to contest territorial flags in combat (战).", "visual_mnemonic_story_es": "Guerreros empuñando alabardas de bronce (戈) para disputar el estandarte bélico (战).", "tone_mnemonic_anchor": "51", "cangjie": "YRI", "traditional": "戰"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在古代冷兵器战争中，主将的临场作战指挥往往直接决定着数万将士的生死存亡。善于作战的名将，绝不墨守陈规，而是能够根据风向、地势与敌军动向灵活调整阵型，因敌制胜，化被动为主动。", "pinyin": "Zài gǔdài lěngbīngqì zhànzhēng zhōng, zhǔjiàng de línchǎng zuòzhàn zhǐhuī wǎngwǎng zhíjiē juédìng zhe shù wàn jiàngshì de shēngsǐ-cúnwáng. Shànyú zuòzhàn de míngjiàng, juébù mòshǒu-chéngguī, ér shì nénggòu gēnjù fēngxiàng, dìshì yǔ díjūn dòngxiàng línghuó tiáozhěng zhènxíng, yīndí-zhìshèng, huà bèidòng wéi zhǔdòng.", "en": "In ancient hand-to-hand warfare, a general's battlefield combat command directly decided the survival of thousands. Skilled commanders rejected dogmatism, adjusting formations by winds, terrain, and enemy moves to turn disadvantage into victory.", "es": "En la guerra clásica de armas blancas, el mando táctico del general decidía la vida de miles de combatientes. Los grandes estrategas jamás se ataban a fórmulas, amoldando su táctica al terreno y al viento para forjar el triunfo."}, {"id": "#2", "hanzi": "现代信息化战争不仅是前线官兵的英勇作战，更是后方科研、后勤物资保障与电子网络对抗的立体综合较量。只有陆海空天多维兵种实现高度无缝的联合作战，才能在瞬息万变的现代战场上掌握主动权。", "pinyin": "Xiàndài xìnxīhuà zhànzhēng bùjǐn shì qiánxiàn guānbīng de yīngyǒng zuòzhàn, gèng shì hòufāng kēyán, hòuqín wùzī bǎozhàng yǔ diànzǐ wǎngluò duìkàng de lìtǐ zōnghé jiàoliàng. Zhǐyǒu lù-hǎi-kōng-tiān duōwéi bīngzhǒng shíxiàn gāodù wúfèng de liánhé zuòzhàn, cái néng zài shùnxī-wànbiàn de xiàndài zhànchǎng shang zhǎngwò zhǔdòngquán.", "en": "Modern digitalized warfare relies not just on bravery at the frontline, but on multi-domain logistics, cyber defense, and aerospace coordination. Only seamless joint operations across land, sea, air, and space secure battlefield dominance.", "es": "La contienda moderna supera el combate frontal para implicar logística avanzada, ciberdefensa y pugna electrónica. Solo una integración tridimensional entre tierra, mar y aire permite dominar la iniciativa en el combate contemporáneo."}]}, {"meanings_summary": {"en": "defect; shortcoming; fault; flaw; illness; habit", "es": "defecto; fallo; avería; imperfección; mala costumbre; indisposición"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A tiny flaw as minute as hair (毛) that causes systematic disorder (病) is a defect or glitch (毛病).", "composite_memory_hook_es": "Una imperfección diminuta como un pelo (毛) que engendra malestar o avería (病) conforma un defecto (毛病).", "cultural_and_cognitive_roots": "Derived from ancient horse breeding where veterinarians blew animal fur aside to check for hidden sores or skin defects.", "tone_sandhi_and_pitch_modulation": "Second tone to fourth tone: 'máo bìng' (35-51). Lift cleanly on 'máo', followed by a decisive drop on 'bìng'."}, "semantic_boundary_contrasts": {"core_nuance": "毛病 is an everyday colloquial term covering mechanical glitches, bad personal habits, and character flaws.", "contrasts": [{"id": "1", "compared_word": "毛病 vs. 缺点", "pinyin": "quēdiǎn", "analysis": "缺点 is formal and refers to general shortcomings in work/character, while 毛病 spans machine glitches and bad quirks."}, {"id": "2", "compared_word": "毛病 vs. 错误", "pinyin": "cuòwù", "analysis": "错误 refers to an incorrect action or mistaken calculation, whereas 毛病 refers to a habitual flaw or defect."}, {"id": "3", "compared_word": "毛病 vs. 优点", "pinyin": "yōudiǎn", "analysis": "优点 is the direct antonym meaning merit, virtue, or strong point."}]}, "traps_and_cognates": {"look_alikes": [{"character": "手", "pinyin": "shǒu", "meaning_en": "hand", "distinction_note": "Central vertical stroke curves inward, not rightward hook"}, {"character": "痛", "pinyin": "tòng", "meaning_en": "pain", "distinction_note": "Yong 甬 inside 疒 instead of 丙"}, {"character": "痴", "pinyin": "chī", "meaning_en": "foolish", "distinction_note": "Zhi 知 inside 疒 instead of 丙"}, {"character": "疗", "pinyin": "liáo", "meaning_en": "heal; treat", "distinction_note": "Liao 了 inside 疒 instead of 丙"}], "etymological_cognates": [{"character": "缺点", "pinyin": "quēdiǎn", "gloss_en": "shortcoming; defect"}, {"character": "疾病", "pinyin": "jíbìng", "gloss_en": "disease; illness"}, {"character": "皮毛", "pinyin": "pímáo", "gloss_en": "fur and skin; superficial know-how"}, {"character": "毛料", "pinyin": "máoliào", "gloss_en": "woolen material"}]}, "id": "6", "hanzi": "毛病", "pinyin": "máo bìng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a flaw, defect, mechanical malfunction, personal shortcoming, bad habit, or minor illness", "definition_es": "defecto, fallo mecánico, imperfección de carácter, mala costumbre o afección de salud", "example_phrase": "克服自身的毛病 (overcome one's own shortcomings)"}], "example_sentences": [{"id": "#1", "hanzi": "战国名将赵奢深知儿子赵括有着轻敌自负、眼高手低的致命毛病，因而再三告诫他不可轻易领兵。", "pinyin": "Zhànguó míngjiàng Zhào Shē shēnzhī érzi Zhào Kuò yǒu zhe qīngdí zìfù, yǎngāo-shǒudī de zhìmìng máobìng, yīn'ér zàisān gàojiè tā bùkě qīngyì lǐngbīng.", "en": "General Zhao She knew his son Zhao Kuo suffered from the fatal flaw of arrogance and underestimating foes, repeatedly warning him against command.", "es": "El general Zhao She conocía el defecto mortal de su hijo Zhao Kuo de subestimar al adversario, aconsejándole no tomar jamás el mando militar."}, {"id": "#2", "hanzi": "这台二手复印机由于使用年限较长，最近几天频繁出现卡纸的小毛病，需要彻底检修。", "pinyin": "Zhè tái èrshǒu fùyìnjī yóuyú shǐyòng niánxiàn jiàocháng, zuìjìn jǐ tiān pínfán chūxiàn kǎzhǐ de xiǎo máobìng, xūyào chèdǐ jiǎnxiū.", "en": "Due to its long service life, this secondhand photocopier has frequently developed paper jam glitches recently and needs an overhaul.", "es": "Debido a los años de servicio, la fotocopiadora sufre frecuentes averías de atasco de papel, requiriendo una revisión exhaustiva."}], "collocations": [{"hanzi": "出毛病", "en": "break down / go wrong"}, {"hanzi": "改掉毛病", "en": "correct a bad habit / defect"}, {"hanzi": "挑毛病", "en": "find fault / nitpick"}, {"hanzi": "致命毛病", "en": "fatal flaw / critical defect"}, {"hanzi": "老毛病", "en": "old habit / recurring ailment"}, {"hanzi": "机器毛病", "en": "mechanical trouble / glitch"}], "idioms": [{"hanzi": "吹毛求疵", "pinyin": "chuī máo qiú cī", "meaning_en": "blow away hair to find scars; nitpick petty flaws"}, {"hanzi": "自相矛盾", "pinyin": "zì xiāng máo dùn", "meaning_en": "self-contradictory in thought or speech"}, {"hanzi": "防微杜渐", "pinyin": "fáng wēi dù jiàn", "meaning_en": "nip evil in the bud before small flaws grow big"}, {"hanzi": "改过自新", "pinyin": "gǎi guò zì xīn", "meaning_en": "turn over a new leaf by correcting past errors"}], "character_decomposition": [{"character": "毛", "pinyin": "máo", "meaning_en": "hair; fur; feather; flaw; down", "meaning_es": "pelo; vello; pluma; pelusa; mínimo", "radical": "毛", "radical_meaning_en": "fur / hair", "meaning_component": "pictograph of fine curved strands of animal fur or hair", "sound_component": "毛 (máo)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient pictograph depicting thin strands of animal hair blowing in the wind.", "visual_mnemonic_story_en": "Fine strands of animal fur and hair (毛) blowing lightly in the breeze.", "visual_mnemonic_story_es": "Mechones de pelo fino de animal (毛) que ondean suavemente con el viento.", "tone_mnemonic_anchor": "35", "cangjie": "HQU", "traditional": "毛"}, {"character": "病", "pinyin": "bìng", "meaning_en": "illness; disease; fault; defect", "meaning_es": "enfermedad; padecimiento; defecto; tara", "radical": "疒", "radical_meaning_en": "sickness", "meaning_component": "疒 (sickbed / unwell frame) + 丙 (third Heavenly Stem / feverish tail)", "sound_component": "丙 (bǐng)", "stroke_count": "10", "composition_type": "半包围结构", "etymology_and_mnemonic": "A person lying unwell on a sickbed 疒 with body heat and ailment 丙; denotes illness or defect.", "visual_mnemonic_story_en": "Lying restfully on a patient's sickbed (疒) recovering from an ailment (病).", "visual_mnemonic_story_es": "Guardar reposo en el lecho del enfermo (疒) para sanar de una dolencia (病).", "tone_mnemonic_anchor": "51", "cangjie": "KMBW", "traditional": "病"}], "extended_reading_passages": [{"id": "#1", "hanzi": "赵括自幼聪颖好学，谈论兵法时连他的父亲赵奢也难不倒他。但他最大的毛病在于缺乏谦逊之心，自以为天下兵法已尽在胸中。这种目空一切、脱离实际的毛病，最终让他在残酷的长平之战中付出了生命的惨痛代价。", "pinyin": "Zhào Kuò zìyòu cōngyǐng hàoxué, tánlùn bīngfǎ shí lián tā de fùqīn Zhào Shē yě nánbùdǎo tā. Dàn tā zuì dà de máobìng zàiyú quēfá qiānxùn zhī xīn, zì yǐwéi tiānxià bīngfǎ yǐ jìn zài xiōngzhōng. Zhè zhǒng mùkōng-yīqiè, tuōlí shíjì de máobìng, zuìzhōng ràng tā zài cánkù de Chángpíng zhī zhàn zhōng fùchū le shēngmìng de cǎntòng dàijià.", "en": "Zhao Kuo was brilliant from youth, stumping even his father on tactics. Yet his greatest defect was lack of humility, assuming he mastered warfare completely. This arrogant flaw cost him his life and an army at Changping.", "es": "Zhao Kuo fue aventajado desde niño, deslumbrando a su padre al hablar de táctica. Pero su peor defecto fue la arrogancia; su vanidad alejada de la realidad le costó la vida y la derrota de su tropa en Changping."}, {"id": "#2", "hanzi": "在现代精密机械与航空工业中，任何微小的设计毛病都可能演变成灾难性的重大事故。工程技术人员必须具备高度的责任感，耐心地通过反复模拟排查系统中的每一个潜在毛病，精益求精，确保装备万无一失。", "pinyin": "Zài xiàndài jīngmì jīxiè yǔ hángkōng gōngyè zhōng, rènhé wēixiǎo de shèjì máobìng dōu kěnéng yǎnbiàn chéng zāinànxìng de zhòngdà shìgù. Gōngchéng jìshù rényuán bìxū jùbèi gāodù de zérèngǎn, nàixīn de tōngguò fǎnfù mónǐ páichá xìtǒng zhōng de měi yī gè qiánzài máobìng, jīngyìqiújīng, quèbǎo zhuāngbèi wànwúyīshī.", "en": "In precision engineering and aerospace, any tiny design flaw can trigger catastrophic accidents. Technicians must maintain immense accountability, repeatedly simulating stress to eliminate latent glitches and ensure flawless reliability.", "es": "En la ingeniería aeronáutica de precisión, cualquier imperfección de diseño acarrea catástrofes. Los ingenieros deben actuar con rigor exhaustivo, subsanando fallos potenciales para garantizar una fiabilidad intachable."}]}, {"meanings_summary": {"en": "principle; reason; truth; logic; argument", "es": "razón; principio; verdad; lógica; fundamento"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The righteous path of wisdom (道) combined with the natural logic of things (理) forms sound principle (道理).", "composite_memory_hook_es": "El sendero de la rectitud (道) unido al principio lógico intrínseco (理) engendra la razón o fundamento (道理).", "cultural_and_cognitive_roots": "Deeply rooted in classical Chinese philosophy unifying the Cosmic Dao with Neo-Confucian Li (inherent structural principle).", "tone_sandhi_and_pitch_modulation": "Fourth tone to third tone: 'dào lǐ' (51-214). Drop firmly on 'dào', then dip and rebound smoothly on 'lǐ'."}, "semantic_boundary_contrasts": {"core_nuance": "道理 encompasses moral truths, logical justifications, and natural principles underlying phenomena.", "contrasts": [{"id": "1", "compared_word": "道理 vs. 理由", "pinyin": "lǐyóu", "analysis": "理由 refers to a specific pretext, excuse, or justification for an action, whereas 道理 refers to universal principles or sound sense."}, {"id": "2", "compared_word": "道理 vs. 理论", "pinyin": "lǐlùn", "analysis": "理论 designates a formal academic system, while 道理 can be everyday common sense and moral wisdom."}, {"id": "3", "compared_word": "道理 vs. 歪理", "pinyin": "wāilǐ", "analysis": "歪理 is the direct antonym meaning fallacious, twisted, or specious arguments."}]}, "traps_and_cognates": {"look_alikes": [{"character": "导", "pinyin": "dǎo", "meaning_en": "lead; guide", "distinction_note": "Inch 寸 at bottom instead of 首 and 辶"}, {"character": "首", "pinyin": "shǒu", "meaning_en": "head; first", "distinction_note": "Lacks the movement radical 辶"}, {"character": "埋", "pinyin": "mái", "meaning_en": "bury", "distinction_note": "Soil radical 土 on left of 里 instead of 王"}, {"character": "野", "pinyin": "yě", "meaning_en": "wild; field", "distinction_note": "Village 里 on left and予 on right"}], "etymological_cognates": [{"character": "道德", "pinyin": "dàodé", "gloss_en": "morals; ethics"}, {"character": "理想", "pinyin": "lǐxiǎng", "gloss_en": "ideal; dream"}, {"character": "理解", "pinyin": "lǐjiě", "gloss_en": "understand; comprehend"}, {"character": "道义", "pinyin": "dàoyì", "gloss_en": "morality and justice"}]}, "id": "7", "hanzi": "道理", "pinyin": "dào lǐ", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "underlying principles, rationale, or fundamental laws governing nature, morality, or reasoning", "definition_es": "principio rector, fundamento lógico o razón moral que rige las cosas y la conducta", "example_phrase": "讲清道理 (explain the rationale clearly)"}], "example_sentences": [{"id": "#1", "hanzi": "老将军语重心长地向年轻军官解释兵法中“虚实相生、刚柔相济”的深刻道理。", "pinyin": "Lǎo jiāngjūn yǔzhòng-xīncháng de xiàng niánqīng jūnguān jiěshì bīngfǎ zhōng 'xū-shí xiāng shēng, gāng-róu xiāng jì' de shēnkè dàolǐ.", "en": "The veteran general earnestly explained the profound principle of 'interplay between void and substance, strength and yielding' in warfare to young officers.", "es": "El curtido general explicó a los jóvenes oficiales el hondo fundamento de combinar la firmeza y la flexibilidad en el arte bélico."}, {"id": "#2", "hanzi": "这篇通俗易懂的寓言故事，向孩子们生动揭示了“骄兵必败”的朴素处世道理。", "pinyin": "Zhè piān tōngsú-yìdǒng de yùyán gùshì, xiàng háizi men shēngdòng jiēshì le 'jiāobīng-bìbài' de pǔsù chǔshì dàolǐ.", "en": "This easily understood fable vividly revealed the simple life truth to children that 'an arrogant army faces inevitable defeat.'", "es": "Esta fábula amena ilustró a los niños el principio elemental de que la soberbia conduce inevitablemente a la derrota."}], "collocations": [{"hanzi": "讲道理", "en": "reason with someone; be reasonable"}, {"hanzi": "有道理", "en": "makes sense / reasonable"}, {"hanzi": "深刻的道理", "en": "profound principle / deep truth"}, {"hanzi": "明白道理", "en": "understand the reason / principle"}, {"hanzi": "蛮不讲理", "en": "utterly unreasonable"}, {"hanzi": "符合道理", "en": "accord with reason and logic"}], "idioms": [{"hanzi": "通情达理", "pinyin": "tōng qíng dá lǐ", "meaning_en": "fair-minded, reasonable, and sensible"}, {"hanzi": "至理名言", "pinyin": "zhì lǐ míng yán", "meaning_en": "golden maxim; words of profound wisdom"}, {"hanzi": "合情合理", "pinyin": "hé qíng hé lǐ", "meaning_en": "fair, sensible, and completely justified"}, {"hanzi": "理所当然", "pinyin": "lǐ suǒ dāng rán", "meaning_en": "natural and right; taken for granted as logical"}], "character_decomposition": [{"character": "道", "pinyin": "dào", "meaning_en": "way; path; road; principle; Dao", "meaning_es": "camino; sendero; principio; el Tao", "radical": "辶", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (movement on path) + 首 (head of wisdom guiding feet)", "sound_component": "首 (shǒu)", "stroke_count": "12", "composition_type": "半包围结构", "etymology_and_mnemonic": "A person walking on a path 辶 with an enlightened head 首; signifies the moral and cosmic Way.", "visual_mnemonic_story_en": "Walking thoughtfully with an enlightened head (首) along the path of moral truth (道).", "visual_mnemonic_story_es": "Avanzar con la cabeza despejada (首) por el camino de la rectitud y la sabiduría (道).", "tone_mnemonic_anchor": "51", "cangjie": "YHUT", "traditional": "道"}, {"character": "理", "pinyin": "lǐ", "meaning_en": "reason; logic; order; manage", "meaning_es": "razón; lógica; orden; principio", "radical": "王", "radical_meaning_en": "jade", "meaning_component": "王/玉 (raw jade stone) + 里 (settlement paths)", "sound_component": "里 (lǐ)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Carving jade 玉 along its natural veined grain lines 里; signifies intrinsic logic.", "visual_mnemonic_story_en": "Polishing jade (玉) along its natural veins to discover its inner pattern (理).", "visual_mnemonic_story_es": "Tallar el jade (玉) respetando sus vetas para revelar su estructura armónica (理).", "tone_mnemonic_anchor": "214", "cangjie": "MGWG", "traditional": "理"}], "extended_reading_passages": [{"id": "#1", "hanzi": "赵国名将赵奢告诫赵括：“兵，死地也，而括易言之。”这句话蕴含着极深的人生道理。战争关乎千家万户生死存亡，若只懂在纸面上空谈道理，却不知在实践中体察险恶，到头来不仅害了自己，更会误国殃民。", "pinyin": "Zhàoguó míngjiàng Zhào Shē gàojiè Zhào Kuò: 'Bīng, sǐdì yě, ér Kuò yì yán zhī.' Zhè jù huà yùnhán zhe jí shēn de rénshēng dàolǐ. Zhànzhēng guānhū qiānjiā-wànhù shēngsǐ-cúnwáng, ruò zhǐ dǒng zài zhǐmiàn shang kōngtán dàolǐ, què bùzhī zài shíjiàn zhōng tǐchá xiǎn'è, dàotóulái bùjǐn hài le zìjǐ, gèng huì wùguó-yāngmín.", "en": "General Zhao She cautioned Zhao Kuo: 'War is mortal ground, yet you speak of it lightly.' War touches millions of lives; empty talk on paper without understanding real perils harms oneself and devastates the nation.", "es": "Zhao She advirtió a su hijo: 'La guerra es terreno de muerte y hablas de ella con ligereza.' Debatir razones en abstracto sin calibrar la crudeza práctica no solo destruye al individuo, sino que arruina a la patria."}, {"id": "#2", "hanzi": "人与人交往最重要的准则是讲道理与讲信义。遇到矛盾分歧时，彼此心平气和地摆事实、讲道理，尊重对方的合理诉求，往往能化干戈为玉帛。通情达理的沟通方式，是维系社会和谐人际关系的润滑剂。", "pinyin": "Rén yǔ rén jiāowǎng zuì zhòngyào de zhǔnzé shì jiǎng dàolǐ yǔ jiǎng xìnyì. Yùdào máodùn fēnqí shí, bǐcǐ xīnpíng-qìhé de bǎi shìshí, jiǎng dàolǐ, zūnzhòng duìfāng de hélǐ sùqiú, wǎngwǎng néng huà gāngē wéi yùbó. Tōngqíng-dálǐ de gōutōng fāngshì, shì wéixì shèhuì héxié rénjì guānxi de rùnhuájì.", "en": "The most vital principle in social dealings is reasoning with good faith. When disputes arise, presenting facts calmly and reasoning with mutual respect turns hostility into harmony, serving as the lubricant of relationships.", "es": "En el trato humano, la regla de oro consiste en actuar con razón y probidad. Exponer los hechos con serenidad y atender razones legítimas desarma discordias, actuando como el mejor bálsamo de convivencia."}]}, {"meanings_summary": {"en": "sooner or later; eventually; in time", "es": "tarde o temprano; a la larga; con el tiempo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Whether late (迟) or early (早), the outcome will inevitably occur sooner or later (迟早).", "composite_memory_hook_es": "Sea tarde (迟) o sea temprano (早), el desenlace ocurrirá inexorablemente (迟早).", "cultural_and_cognitive_roots": "Expresses traditional conviction in karmic inevitability and the natural maturation of time.", "tone_sandhi_and_pitch_modulation": "Second tone to third tone: 'chí zǎo' (35-214). Lift smoothly on 'chí', then dip deeply and rise on 'zǎo'."}, "semantic_boundary_contrasts": {"core_nuance": "迟早 conveys certainty that a future event is inevitable, with timing as the only variable.", "contrasts": [{"id": "1", "compared_word": "迟早 vs. 早晚", "pinyin": "zǎowǎn", "analysis": "早晚 is a colloquial synonym for sooner or later, while 迟早 is common across both written prose and spoken registers."}, {"id": "2", "compared_word": "迟早 vs. 最终", "pinyin": "zuìzhōng", "analysis": "最终 denotes the final concluding stage in a process, whereas 迟早 affirms the inexorability of an occurrence."}, {"id": "3", "compared_word": "迟早 vs. 决不", "pinyin": "juébù", "analysis": "决不 is the direct antonym asserting that an event will never take place under any circumstance."}]}, "traps_and_cognates": {"look_alikes": [{"character": "尺", "pinyin": "chǐ", "meaning_en": "ruler; foot", "distinction_note": "Lacks the movement radical 辶"}, {"character": "送", "pinyin": "sòng", "meaning_en": "send; deliver", "distinction_note": "Pass 关 variant under 辶 instead of 尺"}, {"character": "草", "pinyin": "cǎo", "meaning_en": "grass", "distinction_note": "Grass radical 艹 on top of 早"}, {"character": "旱", "pinyin": "hàn", "meaning_en": "drought", "distinction_note": "Shield 干 under 日 instead of 十"}], "etymological_cognates": [{"character": "迟到", "pinyin": "chídào", "gloss_en": "arrive late; be tardy"}, {"character": "推迟", "pinyin": "tuīchí", "gloss_en": "postpone; delay"}, {"character": "早晨", "pinyin": "zǎochén", "gloss_en": "early morning"}, {"character": "及早", "pinyin": "jízǎo", "gloss_en": "as early as possible"}]}, "id": "8", "hanzi": "迟早", "pinyin": "chí zǎo", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "inevitably occurring at some future moment, regardless of whether it happens sooner or later", "definition_es": "que ocurrirá de modo inexorable en algún instante venidero, antes o después", "example_phrase": "迟早要发生 (sooner or later bound to happen)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括如果不改掉狂妄自大、纸上谈兵的毛病，带兵打仗迟早要给赵国招致惨重的灾难。", "pinyin": "Zhào Kuò rúguǒ bù gǎidiào kuángwàng-zìdà, zhǐshàng-tánbīng de máobìng, dài bīng dǎzhàng chízǎo yào gěi Zhàoguó zhāozhì cǎnzhòng de zāinàn.", "en": "If Zhao Kuo failed to correct his arrogance and armchair habit, leading troops into combat would sooner or later bring disaster upon the State of Zhao.", "es": "Si Zhao Kuo no corregía su fatuidad y diletantismo teórico, mandar tropas al combate traería tarde o temprano una hecatombe al reino de Zhao."}, {"id": "#2", "hanzi": "只要坚持不懈地朝着既定目标努力拼搏，汗水与付出迟早会换来丰硕的收获。", "pinyin": "Zhǐyào jiānchí-bùxiè de cháozhe jìdìng mùbiāo nǔlì pīnbó, hànshuǐ yǔ fùchū chízǎo huì huàn lái fēngshuò de shōuhuò.", "en": "As long as one perseveres tirelessly toward the set goal, sweat and dedication will sooner or later yield fruitful rewards.", "es": "Con tal de perseverar infatigablemente hacia la meta fijada, el sudor y el tesón cosecharán tarde o temprano frutos ubérrimos."}], "collocations": [{"hanzi": "迟早会", "en": "sooner or later will ..."}, {"hanzi": "迟早要来", "en": "inevitably bound to arrive"}, {"hanzi": "迟早明白", "en": "understand eventually"}, {"hanzi": "迟早成功", "en": "succeed sooner or later"}, {"hanzi": "迟早水落石出", "en": "truth will out sooner or later"}, {"hanzi": "迟早露出马脚", "en": "eventually betray oneself"}], "idioms": [{"hanzi": "水落石出", "pinyin": "shuǐ luò shí chū", "meaning_en": "as water recedes stones appear; truth comes to light eventually"}, {"hanzi": "天网恢恢", "pinyin": "tiān wǎng huī huī", "meaning_en": "the net of heaven is vast; evil will inevitably be punished"}, {"hanzi": "苦尽甘来", "pinyin": "kǔ jìn gān lái", "meaning_en": "bitterness ends and sweetness begins; joy comes after sorrow"}, {"hanzi": "功到自然成", "pinyin": "gōng dào zì rán chéng", "meaning_en": "when effort is ripe, success comes naturally"}], "character_decomposition": [{"character": "迟", "pinyin": "chí", "meaning_en": "late; delayed; slow; tardy", "meaning_es": "tarde; lento; demorado; retrasado", "radical": "辶", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (motion along road) + 尺 (foot rule / short step)", "sound_component": "尺 (chǐ)", "stroke_count": "7", "composition_type": "半包围结构", "etymology_and_mnemonic": "Walking 辶 taking only small measured foot-lengths 尺 along the way; to advance slowly and arrive late.", "visual_mnemonic_story_en": "Advancing along a road (辶) inch by inch (尺), arriving slow and late (迟).", "visual_mnemonic_story_es": "Caminar por el sendero (辶) paso a paso medido a palmos (尺), demorando la marcha (迟).", "tone_mnemonic_anchor": "35", "cangjie": "YSO", "traditional": "遲"}, {"character": "早", "pinyin": "zǎo", "meaning_en": "early; morning; beforehand", "meaning_es": "temprano; mañana; con antelación", "radical": "日", "radical_meaning_en": "sun", "meaning_component": "日 (sun) + 十 (first morning light / armor horizon)", "sound_component": "早 (zǎo)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "The sun 日 peeking just above the horizon 十 at early dawn; marks early time.", "visual_mnemonic_story_en": "The shining morning sun (日) rising above the crossline horizon at dawn (早).", "visual_mnemonic_story_es": "El disco solar (日) despuntando sobre el horizonte en el alba temprana (早).", "tone_mnemonic_anchor": "214", "cangjie": "AJ", "traditional": "早"}], "extended_reading_passages": [{"id": "#1", "hanzi": "当年赵奢听闻赵括谈论军事时，不仅未露喜色，反而忧心忡忡。他对妻子说：“兵是生死之地，赵括却视若易事。赵国若不用他还罢了，若真让他做大将，破赵军者迟早必是赵括！”历史的演进不幸言中了他的预言。", "pinyin": "Dāngnián Zhào Shē tīngwén Zhào Kuò tánlùn jūnshì shí, bùjǐn wèi lù xǐsè, fǎn'ér yōuxīn-chōngchōng. Tā duì qīzǐ shuō: 'Bīng shì sǐdì yě, ér Kuò shì ruò yì shì. Zhàoguó ruò bù yòng tā hái bà le, ruò zhēn ràng tā zuò dàjiàng, pò Zhàojūn zhě chízǎo bì shì Zhào Kuò!' Lìshǐ de yǎnjìn bùxìng yánzhòng le tā de yùyán.", "en": "When Zhao She heard his son talk of war, he frowned: 'War is mortal ground, yet Kuo treats it lightly. If Zhao appoints him general, the one who destroys our army will sooner or later be Kuo!' History tragically fulfilled his prophecy.", "es": "Al oír a su hijo hablar de táctica, Zhao She sentenció apesadumbrado: 'La guerra es mortífera y él la toma a la ligera. Si el rey lo nombra general, ¡tarde o temprano será quien hunda a Zhao!' La historia confirmó el presagio."}, {"id": "#2", "hanzi": "自然界的万物生长皆有其内在的节律。春天埋入泥土的种子，只要经历风雨的洗礼与阳光的哺育，迟早会破土成苗、开花结果。在人生的求索道路上，耐得住寂寞与沉淀的人，迟早会迎来属于自己的高光时刻。", "pinyin": "Zìránjiè de wànwù shēngzhǎng jiē yǒu qí nèizài de jiélǜ. Chūntiān máirù nítǔ de zhǒngzi, zhǐyào jīnglì fēngyǔ de xǐlǐ yǔ yángguāng de bǔyù, chízǎo huì pòtǔ chéng miáo, kāihuā-jiéguǒ. Zài rénshēng de qiúsuǒ dàolù shang, nàidézhù jìmò yǔ chéndiàn de rén, chízǎo huì yínglái shǔyú zìjǐ de gāoguāng shíkè.", "en": "All living things grow according to nature's rhythms. Seeds buried in spring, nurtured by rain and sun, will sooner or later sprout and bear fruit. Those who endure quiet dedication will eventually embrace their finest hours.", "es": "Todo en la naturaleza responde a ritmos armónicos. La semilla que resiste la intemperie primaveral tarde o temprano florece y da fruto; quien persevera en el callado afán alcanza tarde o temprano la plenitud soñada."}]}, {"meanings_summary": {"en": "army; armed forces; troops", "es": "ejército; fuerzas armadas; tropas"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Chariot encampments (军) assembled into disciplined tactical ranks (队) form an army (军队).", "composite_memory_hook_es": "El cuerpo expedicionario (军) alineado en unidades operativas (队) conforma el ejército (军队).", "cultural_and_cognitive_roots": "Captures the transition from ancient noble chariot formations to mass infantry corps organized in strict echelons.", "tone_sandhi_and_pitch_modulation": "First tone to fourth tone: 'jūn duì' (55-51). High steady pitch on 'jūn', descending decisively on 'duì'."}, "semantic_boundary_contrasts": {"core_nuance": "军队 specifically denotes the formal, institutionalized military forces of a sovereign nation.", "contrasts": [{"id": "1", "compared_word": "军队 vs. 部队", "pinyin": "bùduì", "analysis": "部队 refers to specific operational divisions or field units, while 军队 encompasses the whole military establishment."}, {"id": "2", "compared_word": "军队 vs. 士兵", "pinyin": "shìbīng", "analysis": "士兵 refers to individual enlisted fighters, whereas 军队 is the institutional collective armed body."}, {"id": "3", "compared_word": "军队 vs. 警察", "pinyin": "jǐngchá", "analysis": "警察 handles domestic civic policing and public order, while 军队 defends against foreign external threats."}]}, "traps_and_cognates": {"look_alikes": [{"character": "车", "pinyin": "chē", "meaning_en": "vehicle", "distinction_note": "Lacks the upper cover radical 冖"}, {"character": "晕", "pinyin": "yūn", "meaning_en": "dizzy; faint", "distinction_note": "Sun 日 on top of 车 instead of 冖"}, {"character": "防", "pinyin": "fáng", "meaning_en": "defend", "distinction_note": "Square 方 on right of 阝 instead of 人"}, {"character": "阳", "pinyin": "yáng", "meaning_en": "sun; positive", "distinction_note": "Sun 日 on right of 阝 instead of 人"}], "etymological_cognates": [{"character": "队员", "pinyin": "duìyuán", "gloss_en": "team member"}, {"character": "排队", "pinyin": "páiduì", "gloss_en": "line up; queue"}, {"character": "军费", "pinyin": "jūnfèi", "gloss_en": "military expenditure"}, {"character": "军纪", "pinyin": "jūnjì", "gloss_en": "military discipline"}]}, "id": "9", "hanzi": "军队", "pinyin": "jūn duì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the organized armed forces of a nation trained and equipped for warfare and national defense", "definition_es": "cuerpo militar organizado y equipado de un Estado para la defensa y operaciones bélicas", "example_phrase": "强大的军队 (a powerful army)"}], "example_sentences": [{"id": "#1", "hanzi": "一支纪律严明、作风优良的军队，是捍卫国家领土主权与维护人民和平生活的坚固长城。", "pinyin": "Yī zhī jìlǜ-yánmíng, zuòfēng-yōuliáng de jūnduì, shì hànwèi guójiā lǐngtǔ zhǔquán yǔ wéihù rénmín hépíng shēnghuó de jiāngù chángchéng.", "en": "A strictly disciplined and well-trained army serves as an impregnable Great Wall defending national sovereignty and peaceful life.", "es": "Un ejército de rigurosa disciplina constituye la muralla inexpugnable que salvaguarda la soberanía nacional y la paz del pueblo."}, {"id": "#2", "hanzi": "长平之战中，秦国军队在名将白起的统一指挥下，巧妙分割包围了赵国主力部队。", "pinyin": "Chángpíng zhī zhàn zhōng, Qínguó jūnduì zài míngjiàng Bái Qǐ de tǒngyī zhǐhuī xià, qiǎomiào fēngē-bāowéi le Zhàoguó zhǔlì bùduì.", "en": "At the Battle of Changping, the Qin army under General Bai Qi's unified command cleverly partitioned and encircled Zhao's main forces.", "es": "En la batalla de Changping, el ejército de Qin bajo el mando de Bai Qi dividió y rodeó con destreza el grueso de las tropas de Zhao."}], "collocations": [{"hanzi": "国家军队", "en": "national army / armed forces"}, {"hanzi": "军队建设", "en": "army building / military buildup"}, {"hanzi": "正规军队", "en": "regular army"}, {"hanzi": "指挥军队", "en": "command the army"}, {"hanzi": "军队现代化", "en": "military modernization"}, {"hanzi": "庞大的军队", "en": "vast / formidable army"}], "idioms": [{"hanzi": "千军万马", "pinyin": "qiān jūn wàn mǎ", "meaning_en": "thousands of troops and tens of thousands of horses; mighty army"}, {"hanzi": "纪律严明", "pinyin": "jì lǜ yán míng", "meaning_en": "strictly disciplined and orderly"}, {"hanzi": "兵贵神速", "pinyin": "bīng guì shén sù", "meaning_en": "speed is precious in warfare; lightning strike"}, {"hanzi": "养兵千日，用兵一时", "pinyin": "yǎng bīng qiān rì, yòng bīng yī shí", "meaning_en": "train troops for a thousand days to use them for an hour"}], "character_decomposition": [{"character": "军", "pinyin": "jūn", "meaning_en": "military; army; armed forces", "meaning_es": "ejército; militar; fuerzas armadas", "radical": "冖", "radical_meaning_en": "cover", "meaning_component": "冖 (military tent cover) + 车 (war chariots)", "sound_component": "军 (jūn)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "War chariots 车 assembled beneath encampment canopies 冖; signifies organized troops.", "visual_mnemonic_story_en": "War chariots (车) gathered under camp covers (冖) ready for combat (军).", "visual_mnemonic_story_es": "Carros de guerra (车) agrupados bajo el toldo militar (冖) listos para la marcha (军).", "tone_mnemonic_anchor": "55", "cangjie": "BKJ", "traditional": "軍"}, {"character": "队", "pinyin": "duì", "meaning_en": "team; squad; queue; unit", "meaning_es": "equipo; fila; brigada; escuadrón", "radical": "阝", "radical_meaning_en": "mound / hill", "meaning_component": "阝 (earthen ridge/embankment) + 人 (soldiers falling in line)", "sound_component": "队 (duì)", "stroke_count": "4", "composition_type": "左右结构", "etymology_and_mnemonic": "Soldiers lining up along an earthen defensive embankment 阝 into an orderly squad; to form a queue.", "visual_mnemonic_story_en": "Soldiers falling into an orderly defensive line along an earthen ridge (阝) to form a squad (队).", "visual_mnemonic_story_es": "Soldados alineados en rigurosa hilera junto al terraplén (阝) formando una unidad (队).", "tone_mnemonic_anchor": "51", "cangjie": "NLO", "traditional": "隊"}], "extended_reading_passages": [{"id": "#1", "hanzi": "战国末期，赵国军队向以骁勇善战著称，胡服骑射更使赵军骑兵名震诸侯。然而长平之战中，赵王临阵撤换沉着稳健的老将廉颇，改派赵括统领全军，最终致使数十万精锐军队被秦军围困全歼，赵国国力从此一蹶不振。", "pinyin": "Zhànguó mòqī, Zhàoguó jūnduì xiàng yǐ xiāoyǒng-shànzhàn zhùchēng, húfú-qíshè gèng shǐ Zhàojūn qíbīng míng zhèn zhūhóu. Rán'ér Chángpíng zhī zhàn zhōng, Zhàowáng línzhèn chèhuàn chénzhuó-wěnjiàn de lǎojiàng Lián Pō, gǎi pài Zhào Kuò tǒnglǐng quán jūn, zuìzhōng zhìshǐ shùshí wàn jīngruì jūnduì bèi Qínjūn wéikùn quánjiān, Zhàoguó guólì cóngcǐ yījué-bùzhèn.", "en": "In the late Warring States, the Zhao army was celebrated for fierce cavalry tactics. Yet at Changping, King Zhao replaced cautious General Lian Po with Zhao Kuo; hundreds of thousands of elite troops were encircled, crippling the state forever.", "es": "En los Reinos Combatientes, el ejército de Zhao gozaba de fama por su formidable caballería. Mas en Changping, el rey relevó al cauto Lian Po por Zhao Kuo, lo que llevó al aniquilamiento de su tropa de élite y al declive del reino."}, {"id": "#2", "hanzi": "一支现代化的强大军队，不仅必须装备最尖端的科学武器装备，更需要具备高度严明的军纪与无私奉献的战斗精神。在抗击自然灾害与保卫人民生命财产的急难险重关头，军队始终是人民最可信赖的中流砥柱。", "pinyin": "Yī zhī xiàndàihuà de qiángdà jūnduì, bùjǐn bìxū zhuāngbèi zuì jiānduān de kēxué wǔqì zhuāngbèi, gèng xūyào jùbèi gāodù yánmíng de jūnjì yǔ wúsī-fèngxiàn de zhàndòu jīngshén. Zài kàngjī zìrán zāihài yǔ bǎowèi rénmín shēngmìng cáichǎn de jínàn-xiǎnzhòng guāntóu, jūnduì shǐzhōng shì rénmín zuì kě xìnlài de zhōngliú-dǐzhù.", "en": "A powerful modern army requires cutting-edge armaments alongside strict discipline and self-sacrificing spirit. During natural disasters and national perils, the armed forces remain the most trustworthy pillar protecting the people.", "es": "Un ejército moderno no solo exige armamento de punta, sino férrea disciplina y abnegación. Ante catástrofes naturales y graves crisis nacionales, las fuerzas armadas constituyen el baluarte más leal y firme de la ciudadanía."}]}, {"meanings_summary": {"en": "to send; dispatch; assign; faction; school of thought", "es": "enviar; mandar; destinar; asignar; facción; escuela"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Water branching outward into separate channels (氵+𠂢) represents dispatching people outward on missions (派).", "composite_memory_hook_es": "El río que bifurca sus ramales hacia rumbos diversos (氵+𠂢) encarna la acción de enviar o comisionar (派).", "cultural_and_cognitive_roots": "Originates from hydrology meaning tributary branches of a main river, extended to philosophical schools (流派) and executive deputation.", "tone_sandhi_and_pitch_modulation": "Fourth tone: 'pài' (51). Crisp, decisive downward inflection."}, "semantic_boundary_contrasts": {"core_nuance": "派 as a verb highlights authoritative or organizational dispatch of personnel on designated tasks.", "contrasts": [{"id": "1", "compared_word": "派 vs. 送", "pinyin": "sòng", "analysis": "送 implies delivering an object or escorting someone off, while 派 means assigning someone on an official mission."}, {"id": "2", "compared_word": "派 vs. 遣", "pinyin": "qiǎn", "analysis": "遣 is formal literary (often paired as 派遣), while 派 is ubiquitous in both spoken and written Chinese."}, {"id": "3", "compared_word": "派 vs. 留", "pinyin": "liú", "analysis": "留 is the direct antonym meaning to detain, keep in place, or retain."}]}, "traps_and_cognates": {"look_alikes": [{"character": "旅", "pinyin": "lǚ", "meaning_en": "travel; brigade", "distinction_note": "Square 方 on left instead of 氵"}, {"character": "波", "pinyin": "bō", "meaning_en": "wave; ripple", "distinction_note": "Skin 皮 on right instead of 𠂢"}, {"character": "泳", "pinyin": "yǒng", "meaning_en": "swim", "distinction_note": "Eternal 永 on right instead of 𠂢"}, {"character": "河", "pinyin": "hé", "meaning_en": "river", "distinction_note": "Can 可 on right instead of 𠂢"}], "etymological_cognates": [{"character": "派遣", "pinyin": "pàiqiǎn", "gloss_en": "dispatch; depute"}, {"character": "流派", "pinyin": "liúpài", "gloss_en": "school of thought; sect"}, {"character": "学派", "pinyin": "xuépài", "gloss_en": "academic school"}, {"character": "委派", "pinyin": "wěipài", "gloss_en": "appoint; assign"}]}, "id": "10", "hanzi": "派", "pinyin": "pài", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to dispatch, assign, or depute persons to perform a task, mission, or military duty", "definition_es": "enviar, comisionar o despachar a alguien para cumplir un cometido, misión o faena", "example_phrase": "派代表出席 (dispatch representatives to attend)"}], "example_sentences": [{"id": "#1", "hanzi": "赵王轻信了秦国散布的离间谣言，执意罢免廉颇，改派毫无实战经验的赵括统领大军前线作战。", "pinyin": "Zhàowáng qīngxìn le Qínguó sànbù de líjiàn yáoyán, zhíyì bàmǐan Lián Pō, gǎi pài háowú shízhàn jīngyàn de Zhào Kuò tǒnglǐng dàjūn qiánxiàn zuòzhàn.", "en": "Gullible to rumors spread by Qin, King Zhao insisted on dismissing Lian Po and sent inexperienced Zhao Kuo to command the front lines.", "es": "Creyendo los falsos rumores de Qin, el rey de Zhao cesó a Lian Po y mandó al frente al inexperto Zhao Kuo al mando de las tropas."}, {"id": "#2", "hanzi": "得知地震灾区急需医疗救援后，省人民医院立即派出了第一批资深外科专家医疗队连夜奔赴前线。", "pinyin": "Dézhī dìzhèn zāiqū jíxū yīliáo jiùyuán hòu, shěng rénmín yīyuàn lìjí pài chū le dì-yī pī zīshēn wàikē zhuānjiā yīliáoduì liányè bēnfù qiánxiàn.", "en": "Learning that the earthquake disaster area urgently needed medical aid, the hospital immediately dispatched its first team of surgeons overnight.", "es": "Al conocerse la emergencia en la zona sísmica, el hospital provincial envió de inmediato un primer equipo de cirujanos esa misma noche."}], "collocations": [{"hanzi": "派出代表", "en": "dispatch representatives"}, {"hanzi": "派人前往", "en": "send someone over"}, {"hanzi": "派遣专家", "en": "depute / dispatch experts"}, {"hanzi": "分配任务", "en": "assign tasks / duties"}, {"hanzi": "一派胡言", "en": "complete nonsense / pack of lies (classifier)"}, {"hanzi": "各流各派", "en": "various factions and schools"}], "idioms": [{"hanzi": "名门正派", "pinyin": "míng mén zhèng pài", "meaning_en": "reputable and orthodox school or lineage"}, {"hanzi": "一派胡言", "pinyin": "yī pài hú yán", "meaning_en": "sheer nonsense; absurd drivel"}, {"hanzi": "自成一派", "pinyin": "zì chéng yī pài", "meaning_en": "form a unique school of one's own"}, {"hanzi": "差强人意", "pinyin": "chā qiáng rén yì", "meaning_en": "barely satisfactory; passable"}], "character_decomposition": [{"character": "派", "pinyin": "pài", "meaning_en": "send; dispatch; branch of water; faction", "meaning_es": "enviar; mandar; ramal fluvial; facción", "radical": "氵", "radical_meaning_en": "water", "meaning_component": "氵 (water flow) + 𠂢 (river branching into tributary streams)", "sound_component": "𠂢 (pài)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Water 氵 branching off into several diverging river tributaries 𠂢; signifies sending out streams or people.", "visual_mnemonic_story_en": "A river stream (氵) branching out in diverging channels to carry boats to distant ports (派).", "visual_mnemonic_story_es": "El curso del río (氵) ramificándose en brazos de agua para enviar barcas a diversos rumbos (派).", "tone_mnemonic_anchor": "51", "cangjie": "EHHV", "traditional": "派"}], "extended_reading_passages": [{"id": "#1", "hanzi": "长平之战前夕，秦相范雎用重金派间谍潜入赵国，四处散布“秦军最惧怕赵括”的谣言。缺乏政治远见的赵王果然中计，不顾群臣强烈反对，执意派赵括代替廉颇出征，这一昏庸决策最终铸成了无法挽回的亡国悲剧。", "pinyin": "Chángpíng zhī zhàn qiánxī, Qínxiàng Fàn Jū yòng zhòngjīn pài jiàndié qiánrù Zhàoguó, sìchù sànbù 'Qínjūn zuì jùpà Zhào Kuò' de yáoyán. Quēfá zhèngzhì yuǎnjiàn de Zhàowáng guǒrán zhòngjì, bùgù qúnchén qiángliè fǎnduì, zhíyì pài Zhào Kuò dàitì Lián Pō chūzhēng, zhè yī hūnyōng juécè zuìzhōng zhùchéng le wúfǎ-wǎnhuí de wángguó bēijù.", "en": "On the eve of Changping, Qin's minister bribed spies to enter Zhao and spread rumors that 'Qin feared only Zhao Kuo.' Blindly duped, King Zhao insisted on dispatching Zhao Kuo to replace Lian Po, sealing a tragic catastrophe.", "es": "Antes de Changping, el primer ministro de Qin sobornó espías para difundir que Qin solo temía a Zhao Kuo. El crédulo monarca de Zhao cayó en la trampa y envió a Zhao Kuo al relevo, consumando una tragedia irreparable."}, {"id": "#2", "hanzi": "在现代企业战略管理中，合理选拔与准确派任核心业务骨干，是项目克难制胜的首要关键。管理者必须知人善任，绝不能任人唯亲或盲目指派，唯有派最合适、最有实战能力的人奔赴攻坚战场，才能确保团队战无不胜。", "pinyin": "Zài xiàndài qǐyè zhànlüè guǎnlǐ zhōng, hélǐ xuǎnbá yǔ zhǔnquè pàirèn héxīn yèwù gǔgàn, shì xiàngmù kènán-zhìshèng de shǒuyào guānjiàn. Guǎnlǐzhě bìxū zhīrén-shànrèn, juébùnéng rènrén-wéiqīn huò mángmù zhǐpài, wéiyǒu pài zuì héshì, zuì yǒu shízhàn nénglì de rén bēnfù gōngjiān zhànchǎng, cái néng quèbǎo tuánduì zhànwúbùshèng.", "en": "In modern corporate strategy, selecting and dispatching key professionals is essential for project triumph. Managers must appoint candidates based on tested ability rather than favoritism, sending capable people to lead tasks to victory.", "es": "En la gestión empresarial moderna, comisionar con acierto a los perfiles idóneos resulta determinante. Los directivos deben asignar cometidos por mérito y solvencia probada; enviar a los más aptos garantiza el éxito de los proyectos."}]}, {"meanings_summary": {"en": "weak; feeble; inferior; vulnerable; young", "es": "débil; vulnerable; frágil; inferior"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Two pliable bows wound together (弱) lack the taut power of battle bows, embodying weakness (弱).", "composite_memory_hook_es": "Dos arquillos flexibles gemelos (弱) carecen de la tensión férrea de combate, encarnando la debilidad (弱).", "cultural_and_cognitive_roots": "Derived from classical archery where youth practiced with light pliant bows before mastering rigid military warbows.", "tone_sandhi_and_pitch_modulation": "Fourth tone: 'ruò' (51). Crisp and sharp downward inflection."}, "semantic_boundary_contrasts": {"core_nuance": "弱 signifies deficient strength, low resistance, or military disadvantage.", "contrasts": [{"id": "1", "compared_word": "弱 vs. 强", "pinyin": "qiáng", "analysis": "强 is the direct antonym meaning strong, powerful, and robust."}, {"id": "2", "compared_word": "弱 vs. 软", "pinyin": "ruǎn", "analysis": "软 refers to physical softness in texture (cushion/cotton), while 弱 emphasizes lack of strength or capability."}, {"id": "3", "compared_word": "弱 vs. 小", "pinyin": "xiǎo", "analysis": "小 denotes compact spatial size, while 弱 indicates deficient power or stamina."}]}, "traps_and_cognates": {"look_alikes": [{"character": "弓", "pinyin": "gōng", "meaning_en": "archery bow", "distinction_note": "Single bow frame without feathers or duplicate"}, {"character": "引", "pinyin": "yǐn", "meaning_en": "draw; lead", "distinction_note": "Single vertical stroke on right of 弓"}, {"character": "张", "pinyin": "zhāng", "meaning_en": "stretch; open", "distinction_note": "Long 长 on right of 弓"}, {"character": "强", "pinyin": "qiáng", "meaning_en": "strong", "distinction_note": "Insect 虫 inside right component"}], "etymological_cognates": [{"character": "弱点", "pinyin": "ruòdiǎn", "gloss_en": "weakness; vulnerable spot"}, {"character": "微弱", "pinyin": "wēiruò", "gloss_en": "faint; feeble (signal/light)"}, {"character": "减弱", "pinyin": "jiǎnruò", "gloss_en": "weaken; abate"}, {"character": "脆弱", "pinyin": "cuìruò", "gloss_en": "fragile; brittle"}]}, "id": "11", "hanzi": "弱", "pinyin": "ruò", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "lacking physical strength, military power, firmness, or capability; inferior in strength", "definition_es": "que carece de fuerza física, poderío militar o solidez; vulnerable; inferior", "example_phrase": "力量薄弱 (power is weak and frail)"}], "example_sentences": [{"id": "#1", "hanzi": "在群雄逐鹿的战国时期，诸侯各国弱肉强食，弱小的邦国随时面临被强邻吞并的危险。", "pinyin": "Zài qúnxióng-zhúlù de Zhànguó shíqī, zhūhóu gèguó ruòròu-qiángshí, ruòxiǎo de bāngguó suíshí miànlín bèi qiánglín tūnbìng de wēixiǎn.", "en": "During the Warring States period, states lived by the law of the jungle; small, weak principalities faced peril of annexation by strong neighbors.", "es": "En los Reinos Combatientes imperaba la ley de la selva; los principados débiles afrontaban en todo momento la amenaza de ser anexionados."}, {"id": "#2", "hanzi": "虽然他在长跑耐力方面相对较弱，但凭借极佳的爆发力在短跑项目中斩获了冠军。", "pinyin": "Suīrán tā zài chángpǎo nàilì fāngmiàn xiāngduì jiào ruò, dàn píngjiè jí jiā de bàofālì zài duǎnpǎo xiàngmù zhōng zhǎnhuò le guànjūn.", "en": "Although he was relatively weak in long-distance endurance, his explosive sprinting speed secured him the championship.", "es": "Aunque su resistencia en fondo era algo débil, su gran potencia de arrancada le permitió coronarse campeón en velocidad."}], "collocations": [{"hanzi": "软弱无力", "en": "weak and powerless"}, {"hanzi": "弱点缺陷", "en": "weak points and shortcomings"}, {"hanzi": "以弱胜强", "en": "defeat the strong with the weak"}, {"hanzi": "敌强我弱", "en": "the enemy is strong while we are weak"}, {"hanzi": "身体虚弱", "en": "physically frail and weak"}, {"hanzi": "弱小群体", "en": "vulnerable / weak groups"}], "idioms": [{"hanzi": "弱肉强食", "pinyin": "ruò ròu qiáng shí", "meaning_en": "the weak are meat for the strong; law of the jungle"}, {"hanzi": "以弱胜强", "pinyin": "yǐ ruò shèng qiáng", "meaning_en": "defeat a stronger opponent through superior strategy"}, {"hanzi": "扶弱济困", "pinyin": "fú ruò jì kùn", "meaning_en": "support the weak and relieve the distressed"}, {"hanzi": "微不足道", "pinyin": "wēi bù zú dào", "meaning_en": "insignificant and negligible; too frail to mention"}], "character_decomposition": [{"character": "弱", "pinyin": "ruò", "meaning_en": "weak; frail; young; inferior", "meaning_es": "débil; frágil; joven; inferior", "radical": "弓", "radical_meaning_en": "bow", "meaning_component": "two limp wooden bows wound with feathers / sinews", "sound_component": "弱 (ruò)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Two small, pliable bows decorated with soft feathers; represents pliable frailty and weakness.", "visual_mnemonic_story_en": "Two small, flexible archery bows (弓) lacking sufficient tension to launch heavy arrows (弱).", "visual_mnemonic_story_es": "Dos arcos ligeros (弓) con escasa tensión en la cuerda para disparar dardos pesados (弱).", "tone_mnemonic_anchor": "51", "cangjie": "NINIM", "traditional": "弱"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在战国军事角逐中，“示敌以弱”是克敌制胜的重要谋略。长平前线秦军主帅白起故意命令前锋部队假装兵力薄弱、败下阵去，让赵括误以为秦军不堪一击，从而轻率放弃坚固防线出击，落入了秦军的致命圈套。", "pinyin": "Zài Zhànguó jūnshì juézhú zhōng, 'shì dí yǐ ruò' shì kèdí-zhìshèng de zhòngyào móulüè. Chángpíng qiánxiàn Qínjūn zhǔshuài Bái Qǐ gùyì mìnglìng qiánfēng bùduì jiǎzhuāng bīnglì bóruò, bài xià zhèn qù, ràng Zhào Kuò wùyǐwéi Qínjūn bùkān-yījī, cóng'ér qīngshuài fàngqì jiāngù fángxiàn chūjī, luòrù le Qínjūn de zhìmìng quāntào.", "en": "In Warring States warfare, 'feigning weakness' was a crucial stratagem. At Changping, Qin General Bai Qi ordered vanguards to fake defeat and weakness, deceiving Zhao Kuo into abandoning fortified positions to fall into an ambush.", "es": "En la guerra de los Reinos Combatientes, aparentar flaqueza era una astuta estratagema. En Changping, Bai Qi ordenó a la vanguardia fingir debilidad; Zhao Kuo creyó desmoronado al enemigo y abandonó sus baluartes cayendo en la trampa."}, {"id": "#2", "hanzi": "唯物辩证法告诉我们，强与弱并不是绝对固定不变的，在一定条件下双方可以相互转化。处于弱势的一方只要善于扬长避短，集中优势力量攻其不备，同样能够打破平衡、以弱胜强，在逆境中开辟出崭新的胜利天地。", "pinyin": "Wéiwù-biànzhèngfǎ gàosu wǒmen, qiáng yǔ ruò bìng bùshì juéduì gùdìng-bùbiàn de, zài yīdìng tiáojiàn xià shuāngfāng kěyǐ xiānghù zhuǎnhuà. Chǔyú ruòshì de yīfāng zhǐyào shànyú yángcháng-bìduǎn, jízhōng yōushì lìliang gōng qí bù bèi, tóngyàng nénggòu dǎpò pínghéng, yǐ ruò shèng qiáng, zài nìjìng zhōng kāipì chū zhǎnxīn de shènglì tiāndì.", "en": "Dialectics teaches that strength and weakness are not immutable; under given conditions, they transform into each other. Disadvantaged forces concentrating strength on vulnerabilities can overturn balances and conquer stronger rivals.", "es": "La dialéctica enseña que la fuerza y la debilidad no son estáticas; bajo ciertas condiciones mutan recíprocamente. Quien parte de desventaja pero concentra fuerzas en las fallas ajenas puede vencer al fuerte y triunfar."}]}, {"meanings_summary": {"en": "situation; circumstance; terrain; state of affairs", "es": "situación; coyuntura; panorama; relieve orográfico"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The concrete visible form of reality (形) combined with its dynamic momentum (势) creates the strategic situation (形势).", "composite_memory_hook_es": "El contorno visible de las cosas (形) sumado a su impulso dinámico (势) define la situación estratégica (形势).", "cultural_and_cognitive_roots": "Sunzi's 'Art of War' dedicated chapters to 'Form' (形, static defense) and 'Momentum' (势, dynamic attack), synthesizing into macro situation.", "tone_sandhi_and_pitch_modulation": "Second tone to fourth tone: 'xíng shì' (35-51). Lift cleanly on 'xíng', descending firmly on 'shì'."}, "semantic_boundary_contrasts": {"core_nuance": "形势 points to macro-level developments, strategic military layouts, or collective political landscapes.", "contrasts": [{"id": "1", "compared_word": "形势 vs. 情况", "pinyin": "qíngkuàng", "analysis": "情况 is concrete and covers specific details/status of an individual or incident, while 形势 denotes broader strategic tides."}, {"id": "2", "compared_word": "形势 vs. 局势", "pinyin": "júshì", "analysis": "局势 highlights critical, volatile political or military chess games, whereas 形势 includes economic, social, or geographic trends."}, {"id": "3", "compared_word": "形势 vs. 环境", "pinyin": "huánjìng", "analysis": "环境 emphasizes surrounding physical or cultural conditions, while 形势 describes dynamic trends over time."}]}, "traps_and_cognates": {"look_alikes": [{"character": "行", "pinyin": "xíng", "meaning_en": "walk; line", "distinction_note": "Step 彳 on left instead of 幵 and 彡"}, {"character": "刑", "pinyin": "xíng", "meaning_en": "punishment", "distinction_note": "Knife radical 刂 on right instead of 彡"}, {"character": "热", "pinyin": "rè", "meaning_en": "hot; heat", "distinction_note": "Fire dots 灬 under 执 instead of 力"}, {"character": "挚", "pinyin": "zhì", "meaning_en": "sincere", "distinction_note": "Hand 手 under 执 instead of 力"}], "etymological_cognates": [{"character": "态势", "pinyin": "tàishì", "gloss_en": "posture; situational trend"}, {"character": "局势", "pinyin": "júshì", "gloss_en": "situation; political landscape"}, {"character": "形象", "pinyin": "xíngxiàng", "gloss_en": "image; figure"}, {"character": "形成", "pinyin": "xíngchéng", "gloss_en": "form; take shape"}]}, "id": "12", "hanzi": "形势", "pinyin": "xíng shì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the evolving state of affairs, overall situation, strategic landscape, or military terrain", "definition_es": "estado o panorama general de los acontecimientos, coyuntura estratégica o relieve geográfico", "example_phrase": "看清当前形势 (discern the current situation clearly)"}], "example_sentences": [{"id": "#1", "hanzi": "老将廉颇根据长平前线秦强赵弱的严峻形势，果断采取坚壁清野、坚守营垒的稳健策略。", "pinyin": "Lǎojiàng Lián Pō gēnjù Chángpíng qiánxiàn Qín qiáng Zhào ruò de yánjùn xíngshì, guǒduàn cǎiqǔ jiānbì-qīngyě, jiānshǒu yínglěi de wěnjiàn cèlüè.", "en": "General Lian Po, assessing the grim situation where Qin was strong and Zhao weak at Changping, decisively adopted a strategy of fortification and defense.", "es": "El curtido Lian Po, calibrando la delicada situación en Changping donde Qin aventajaba a Zhao, optó con prudencia por fortificar sus líneas."}, {"id": "#2", "hanzi": "面对瞬息万变的全球经济形势，企业必须具备高度敏锐的战略洞察力，及时调整业务布局。", "pinyin": "Miànduì shùnxī-wànbiàn de quánqiú jīngjì xíngshì, qǐyè bìxū jùbèi gāodù mǐnruì de zhànlüè dòngchálì, jíshí tiáozhěng yèwù bùjú.", "en": "Confronting the fast-changing global economic situation, enterprises must possess keen strategic foresight to adapt operations promptly.", "es": "Ante la volátil coyuntura económica mundial, las corporaciones requieren perspicacia estratégica para reajustar a tiempo sus operaciones."}], "collocations": [{"hanzi": "当前形势", "en": "current situation / present state of affairs"}, {"hanzi": "形势严峻", "en": "the situation is grave / grim"}, {"hanzi": "形势大好", "en": "the situation is splendid / favorable"}, {"hanzi": "分析形势", "en": "analyze the situation / landscape"}, {"hanzi": "客观形势", "en": "objective situation"}, {"hanzi": "军事形势", "en": "military situation / tactical landscape"}], "idioms": [{"hanzi": "审时度势", "pinyin": "shěn shí duó shì", "meaning_en": "judge the hour and size up the situation"}, {"hanzi": "势如破竹", "pinyin": "shì rú pò zhú", "meaning_en": "sweeping forward with irresistible momentum"}, {"hanzi": "顺势而为", "pinyin": "shùn shì ér wéi", "meaning_en": "act in accordance with the prevailing trend"}, {"hanzi": "形势逼人", "pinyin": "xíng shì bī rén", "meaning_en": "the situation is pressing and brook no delay"}], "character_decomposition": [{"character": "形", "pinyin": "xíng", "meaning_en": "shape; form; appearance; body", "meaning_es": "forma; contorno; aspecto; figura", "radical": "彡", "radical_meaning_en": "hair / ornament", "meaning_component": "开/井 (framework / balance) + 彡 (delicate brushwork/ornament)", "sound_component": "开 (kāi / xíng)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Outer physical contours carved or drawn with brush strokes 彡; denotes physical form.", "visual_mnemonic_story_en": "Traced lines (彡) defining the clean external silhouette and form of an object (形).", "visual_mnemonic_story_es": "Pinceladas estilizadas (彡) que delinean el contorno y la forma exterior de una figura (形).", "tone_mnemonic_anchor": "35", "cangjie": "MTTH", "traditional": "形"}, {"character": "势", "pinyin": "shì", "meaning_en": "power; momentum; tendency; posture", "meaning_es": "fuerza; impulso; tendencia; postura", "radical": "力", "radical_meaning_en": "strength / power", "meaning_component": "执 (holding authority / grasping seeds) + 力 (physical strength)", "sound_component": "埶 (shì)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Exerting dynamic strength 力 from an elevated authoritative position 执; signifies momentum and power.", "visual_mnemonic_story_en": "Channeling strength (力) from high ground to unleash irresistible momentum (势).", "visual_mnemonic_story_es": "Canalizar la fuerza muscular (力) desde un promontorio para desatar un empuje imparable (势).", "tone_mnemonic_anchor": "51", "cangjie": "GIS", "traditional": "勢"}], "extended_reading_passages": [{"id": "#1", "hanzi": "长平对峙初期，老将廉颇准确研判了战场形势。秦军远道而来利在速战，而赵军粮道畅通利在持久防守。廉颇依据形势修筑坚固壁垒坚守不战，秦军久攻不下疲惫不堪，双方形势本已朝着有利于赵国的方向发展。", "pinyin": "Chángpíng duìzhì chūqī, lǎojiàng Lián Pō zhǔnquè yánpàn le zhànchǎng xíngshì. Qínjūn yuǎndào-érlái lì zài sùzhàn, ér Zhàojūn liángdào chàngtōng lì zài chíjiǔ fángshǒu. Lián Pō yījù xíngshì xiūzhù jiāngù bìlěi jiānshǒu-bùzhàn, Qínjūn jiǔgōng-bùxià píbèi-bùkān, shuāngfāng xíngshì běn yǐ cháozhe yǒulìyú Zhàoguó de fāngxiàng fāzhǎn.", "en": "Early at Changping, General Lian Po accurately sized up the situation. Qin needed a swift fight, while Zhao benefited from protracted defense. Lian Po built sturdy bastions; Qin grew weary, and the strategic landscape swung in Zhao's favor.", "es": "Al inicio de Changping, el general Lian Po calibró con lucidez el panorama bélico. A Qin le convenía una victoria relámpago, mientras que a Zhao le favorecía la guerra de desgaste. Los baluartes de Lian Po inclinaban la coyuntura a favor de Zhao."}, {"id": "#2", "hanzi": "在复杂多变的市场竞争中，卓越的领导者必须善于审时度势。不仅要深入分析行业当下的客观形势，更要前瞻性预判未来的科技与消费趋势。根据形势变化及时优化战略布局，企业方能在激流险滩中稳操胜券。", "pinyin": "Zài fùzá-duōbiàn de shìchǎng jìngzhēng zhōng, zhuóyuè de lǐngdǎozhě bìxū shànyú shěnshí-duóshì. Bùjǐn yào shēnrù fēnxī hángyè dāngxià de kèguān xíngshì, gèng yào qiánzhānxìng yùpàn wèilái de kējì yǔ xiāofèi qūshì. Gēnjù xíngshì biànhuà jíshí yōuhuà zhànlüè bùjú, qǐyè fāng néng zài jīliú-xiǎntān zhōng wěncāo-shèngquàn.", "en": "Amid complex market competition, outstanding leaders must size up situations astutely. Beyond analyzing current sector dynamics, they anticipate tech and consumer trends, optimizing strategies to steer firms safely to victory.", "es": "En la competencia mercantil, los líderes preclaros deben juzgar la coyuntura con agudeza. No basta examinar el panorama presente; es preciso prever tendencias y adaptar la estrategia para navegar con éxito en aguas turbulentas."}]}, {"meanings_summary": {"en": "command; order; decree; to command; to order", "es": "orden; mandato; comando; ordenar; decretar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "An imperative spoken mandate (命) delivered as a formal decree (令) constitutes an authoritative order (命令).", "composite_memory_hook_es": "El mandato soberano (命) promulgado como ordenanza regia (令) conforma una orden de obligado acatamiento (命令).", "cultural_and_cognitive_roots": "Military discipline principle ('军令如山') where failure to execute a superior's lawful command carried summary court-martial.", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'mìng lìng' (51-51). Articulate both syllables with firm, authoritative downward snap."}, "semantic_boundary_contrasts": {"core_nuance": "命令 indicates an authoritative, non-negotiable instruction that subordinates must execute without question.", "contrasts": [{"id": "1", "compared_word": "命令 vs. 请求", "pinyin": "qǐngqiú", "analysis": "请求 is a polite request asking for assistance, while 命令 is an unbendable directive from above."}, {"id": "2", "compared_word": "命令 vs. 建议", "pinyin": "jiànyì", "analysis": "建议 offers advice for voluntary consideration, whereas 命令 carries binding administrative compulsion."}, {"id": "3", "compared_word": "命令 vs. 指示", "pinyin": "zhǐshì", "analysis": "指示 gives guiding parameters or policy orientation, while 命令 demands exact tactical execution."}]}, "traps_and_cognates": {"look_alikes": [{"character": "伞", "pinyin": "sǎn", "meaning_en": "umbrella", "distinction_note": "Contains multiple crossbars under 人"}, {"character": "今", "pinyin": "jīn", "meaning_en": "now; present", "distinction_note": "Lacks the bottom dot/hook of 令"}, {"character": "冷", "pinyin": "lěng", "meaning_en": "cold", "distinction_note": "Ice radical 冫 on left of 令"}, {"character": "伶", "pinyin": "líng", "meaning_en": "clever; actor", "distinction_note": "Person radical 亻 on left of 令"}], "etymological_cognates": [{"character": "命运", "pinyin": "mìngyùn", "gloss_en": "destiny; fate"}, {"character": "指令", "pinyin": "zhǐlìng", "gloss_en": "instruction; computer command"}, {"character": "寿命", "pinyin": "shòumìng", "gloss_en": "lifespan; longevity"}, {"character": "司令", "pinyin": "sīlìng", "gloss_en": "commander; commanding officer"}]}, "id": "13", "hanzi": "命令", "pinyin": "mìng lìng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an authoritative directive, instruction, or decree issued by a superior that must be executed", "definition_es": "directriz, disposición imperativa o mandato expedido por una autoridad para su obligado cumplimiento", "example_phrase": "服从命令 (obey commands)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括一到长平前线接替廉颇，就立即鲁莽地下达了全军出击、主动进攻秦军的作战命令。", "pinyin": "Zhào Kuò yī dào Chángpíng qiánxiàn jiētì Lián Pō, jiù lìjí lǔmǎng de xiàdá le quán jūn chūjī, zhǔdòng jìngōng Qínjūn de zuòzhàn mìnglìng.", "en": "As soon as Zhao Kuo reached the Changping front replacing Lian Po, he rashly issued a combat order commanding the entire army to attack Qin.", "es": "Nada más llegar a Changping para relevar a Lian Po, Zhao Kuo impartió la temeraria orden de lanzar a todo el ejército al ataque contra Qin."}, {"id": "#2", "hanzi": "消防救援指挥中心接到火警报警后，迅速下达出警命令，三辆消防车在五分钟内火速赶赴现场。", "pinyin": "Xiāofáng jiùyuán zhǐhuī zhōngxīn jiē dào huǒjǐng bàojǐng hòu, xùnsù xiàdá chūjǐng mìnglìng, sān liàng xiāofángchē zài wǔ fēnzhōng nèi huǒsù gǎnfù xiànchǎng.", "en": "Upon receiving the fire alarm, the rescue command center rapidly issued dispatch orders, and three fire engines dashed to the scene within five minutes.", "es": "Al recibir la alarma de incendio, el centro de coordinación emitió la orden de salida y tres camiones de bomberos acudieron al lugar en cinco minutos."}], "collocations": [{"hanzi": "下达命令", "en": "issue an order / command"}, {"hanzi": "服从命令", "en": "obey orders"}, {"hanzi": "执行命令", "en": "execute orders"}, {"hanzi": "紧急命令", "en": "urgent order"}, {"hanzi": "军人以服从命令为天职", "en": "soldiers regard obedience to orders as sacred duty"}, {"hanzi": "撤销命令", "en": "revoke an order"}], "idioms": [{"hanzi": "令行禁止", "pinyin": "lìng xíng jìn zhǐ", "meaning_en": "orders executed promptly and prohibitions strictly observed"}, {"hanzi": "军令如山", "pinyin": "jūn lìng rú shān", "meaning_en": "military orders are firm as mountains; non-negotiable"}, {"hanzi": "唯命是从", "pinyin": "wéi mìng shì cóng", "meaning_en": "obey every command submissively"}, {"hanzi": "发号施令", "pinyin": "fā hào shī lìng", "meaning_en": "bark out orders and order people around"}], "character_decomposition": [{"character": "命", "pinyin": "mìng", "meaning_en": "life; fate; command; decree", "meaning_es": "vida; destino; mandato; ordenar", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (authoritative spoken decree) + 令 (command proclamation)", "sound_component": "令 (lìng)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "A mouth 口 delivering an imperative decree 令; signifies an order or destined mandate.", "visual_mnemonic_story_en": "A sovereign's mouth (口) pronouncing a binding decree that defines people's mission (命).", "visual_mnemonic_story_es": "La boca (口) de un soberano proclamando un decreto sagrado que sella un destino (命).", "tone_mnemonic_anchor": "51", "cangjie": "ROMB", "traditional": "命"}, {"character": "令", "pinyin": "lìng", "meaning_en": "order; command; season; cause", "meaning_es": "orden; mandato; estación; mandar", "radical": "人", "radical_meaning_en": "person", "meaning_component": "亼 (leader gathering people) + 卩 (kneeling figure obeying)", "sound_component": "令 (lìng)", "stroke_count": "5", "composition_type": "上下结构", "etymology_and_mnemonic": "Gathered subjects 亼 kneeling 卩 to receive a formal mandate.", "visual_mnemonic_story_en": "Gathering people under a roof shelter (人) to deliver an official decree (令).", "visual_mnemonic_story_es": "Congregar vasallos bajo el alero real (人) para proclamar una ordenanza (令).", "tone_mnemonic_anchor": "51", "cangjie": "OII", "traditional": "令"}], "extended_reading_passages": [{"id": "#1", "hanzi": "赵括接掌赵军兵权后，第一道命令便是废除老将廉颇原先制定的坚守防御策略。他不顾副将们的苦苦劝谏，强行下达全线反攻的严厉命令。正是这一道脱离战场实际的昏庸命令，将数十万赵国将士推向了万劫不复的深渊。", "pinyin": "Zhào Kuò jiēzhǎng Zhàojūn bīngquán hòu, dì-yī dào mìnglìng biàn shì fèichú lǎojiàng Lián Pō yuánxiān zhìdìng de jiānshǒu fángyù cèlüè. Tā bùgù fùjiàng men de kǔkǔ quànjiàn, qiángxíng xiàdá quánxiàn fǎngōng de yánlì mìnglìng. Zhèngshì zhè yī dào tuōlí zhànchǎng shíjì de hūnyōng mìnglìng, jiāng shùshí wàn Zhàoguó jiàngshì tuī xiàng le wànjié-bùfù de shēnyuān.", "en": "Taking military command, Zhao Kuo's very first order repealed Lian Po's defensive policy. Disregarding deputies' entreaties, he forced an order for full-scale offensive. This reckless command pushed hundreds of thousands of troops into the abyss.", "es": "Al asumir el mando, la primera orden de Zhao Kuo fue abolir la prudente defensa de Lian Po. Desoyendo los ruegos de sus lugartenientes, impartió una estricta orden de contraataque general, precipitando al abismo a sus soldados."}, {"id": "#2", "hanzi": "在现代突发公共安全事件的应急救援处置中，科学高效的统一命令体系是争分夺秒挽救生命的制度保障。指挥部下达的每一道疏散转移命令，都必须依托精确的实时数据与现场研判，做到指令清晰、雷厉风行，确保救援有序推进。", "pinyin": "Zài xiàndài tūfā gōnggòng ānquán shìjiàn de yìngjí jiùyuán chǔzhì zhōng, kēxué gāoxiào de tǒngyī mìnglìng tǐxì shì zhēngfēn-duómiǎo wǎnjiù shēngmìng de zhìdù bǎozhàng. Zhǐhuībù xiàdá de měi yī dào shūsàn zhuǎnyí mìnglìng, dōu bìxū yītuō jīngquè de shíshí shùjù yǔ xiànchǎng yánpàn, zuòdào zhǐlìng qīngxī, léilì-fēngxíng, quèbǎo jiùyuán yǒuxù tuījìn.", "en": "In modern public emergency responses, a unified command system safeguards swift lifesaving operations. Every evacuation order issued by headquarters relies on real-time data, ensuring clear instructions executed with decisive speed.", "es": "En la gestión de emergencias civiles, una cadena unificada de mando resulta vital para salvar vidas a contrarreloj. Cada orden de evacuación debe fundamentarse en datos en tiempo real, garantizando directrices claras y un auxilio coordinado."}]}, {"meanings_summary": {"en": "to guard; defend; keep watch; observe; abide by", "es": "defender; vigilar; guardar; custodiar; acatar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Stationing a firm hand (寸) under the home roof (宀) means to guard and defend (守).", "composite_memory_hook_es": "Apostar una mano firme (寸) bajo el tejado del hogar (宀) define la acción de custodiar (守).", "cultural_and_cognitive_roots": "Derived from classical territorial defence where magistrates were appointed to guard cities ('太守') and abide by rites.", "tone_sandhi_and_pitch_modulation": "Third tone: 'shǒu' (214). Dip deeply into the lower register and rebound with clarity."}, "semantic_boundary_contrasts": {"core_nuance": "守 emphasizes holding ground defensively, guarding securely, or adhering to rules and vows.", "contrasts": [{"id": "1", "compared_word": "守 vs. 攻", "pinyin": "gōng", "analysis": "攻 is the direct antonym meaning to attack or launch an offensive."}, {"id": "2", "compared_word": "守 vs. 逃", "pinyin": "táo", "analysis": "逃 means fleeing or abandoning ground, opposite to firmly holding 守."}, {"id": "3", "compared_word": "守 vs. 护", "pinyin": "hù", "analysis": "护 stresses providing protective shielding to weaker parties, while 守 focuses on vigilantly defending borders or positions."}]}, "traps_and_cognates": {"look_alikes": [{"character": "寸", "pinyin": "cùn", "meaning_en": "inch; measurement", "distinction_note": "Lacks the roof radical 宀"}, {"character": "安", "pinyin": "ān", "meaning_en": "safe; peaceful", "distinction_note": "Woman radical 女 under 宀 instead of 寸"}, {"character": "定", "pinyin": "dìng", "meaning_en": "fix; settle", "distinction_note": "Foot 正 under 宀 instead of 寸"}, {"character": "宇", "pinyin": "yǔ", "meaning_en": "space; universe", "distinction_note": "Yu 于 under 宀 instead of 寸"}], "etymological_cognates": [{"character": "防守", "pinyin": "fángshǒu", "gloss_en": "defend; guard"}, {"character": "遵守", "pinyin": "zūnshǒu", "gloss_en": "comply with; observe"}, {"character": "保守", "pinyin": "bǎoshǒu", "gloss_en": "conservative; keep secret"}, {"character": "守护", "pinyin": "shǒuhù", "gloss_en": "guard and protect"}]}, "id": "14", "hanzi": "守", "pinyin": "shǒu", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to defend against attack; guard a position; keep watch; abide by rules or promises", "definition_es": "defender una posición del asalto enemigo; vigilar; custodiar; acatar normas o promesas", "example_phrase": "坚守阵地 (firmly hold and defend a position)"}], "example_sentences": [{"id": "#1", "hanzi": "老将廉颇深谙秦军远来求战的心态，严令赵国将士坚守堡垒阵地，绝不轻易出击。", "pinyin": "Lǎojiàng Lián Pō shēn'ān Qínjūn yuǎn lái qiú zhàn de xīntài, yánlìng Zhàoguó jiàngshì jiānshǒu bǎolěi zhèndì, juébù qīngyì chūjī.", "en": "General Lian Po understood Qin's urgency to force a quick decision, strictly ordering Zhao soldiers to defend bastions and refrain from sorties.", "es": "El general Lian Po conocía la prisa de Qin por librar combate y ordenó a sus tropas defender los bastiones sin salir a campo abierto."}, {"id": "#2", "hanzi": "在现代社会契约精神中，恪守信誉、严守规则是每一个公民和企业应当践行的基本准则。", "pinyin": "Zài xiàndài shèhuì qìyuē jīngshén zhōng, kèshǒu xìnyù, yánshǒu guīzé shì měi yī gè gōngmín hé qǐyè yīngdāng jiànxíng de jīběn zhǔnzé.", "en": "In modern civic contract culture, abiding by credit and observing rules are fundamental principles that every citizen and enterprise must practice.", "es": "En el espíritu cívico contemporáneo, custodiar la palabra empeñada y acatar las normas son deberes inexcusables de ciudadanos y empresas."}], "collocations": [{"hanzi": "坚守岗位", "en": "stick firmly to one's post"}, {"hanzi": "守信用", "en": "keep one's word / promise"}, {"hanzi": "守候在旁", "en": "stand watch / wait attentively beside"}, {"hanzi": "防守坚固", "en": "stoutly defended"}, {"hanzi": "守规矩", "en": "abide by rules and etiquette"}, {"hanzi": "看守大门", "en": "guard the main entrance"}], "idioms": [{"hanzi": "坚守不移", "pinyin": "jiān shǒu bù yí", "meaning_en": "adhere unswervingly and hold fast"}, {"hanzi": "墨守成规", "pinyin": "mò shǒu chéng guī", "meaning_en": "stick to conventions dogmatically; hidebound"}, {"hanzi": "守株待兔", "pinyin": "shǒu zhū dài tù", "meaning_en": "stand by a tree waiting for a hare; wait passively for windfalls"}, {"hanzi": "守望相助", "pinyin": "shǒu wàng xiāng zhù", "meaning_en": "keep watch and help each other in neighborhood solidarity"}], "character_decomposition": [{"character": "守", "pinyin": "shǒu", "meaning_en": "guard; defend; keep; watch over", "meaning_es": "defender; vigilar; guardar; custodiar", "radical": "宀", "radical_meaning_en": "roof", "meaning_component": "宀 (household roof) + 寸 (ruling hand / law measurement)", "sound_component": "守 (shǒu)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "A hand 寸 holding protective authority inside a house 宀; signifies guarding one's home and borders.", "visual_mnemonic_story_en": "Guarding a domestic homestead (宀) with a vigilant, dutiful hand (寸) against intruders (守).", "visual_mnemonic_story_es": "Custodiar el hogar techado (宀) con mano atenta y vigilante (寸) para defenderlo (守).", "tone_mnemonic_anchor": "214", "cangjie": "JDI", "traditional": "守"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在冷兵器战争中，“攻”与“守”是两种截然相反的战略形态。廉颇在长平前线依托地形筑垒坚守，令秦军数十万精锐进退两难。若赵王能坚持“以守待变”的策略，待秦军粮尽自退，战国历史的格局或许将被彻底改写。", "pinyin": "Zài lěngbīngqì zhànzhēng zhōng, 'gōng' yǔ 'shǒu' shì liǎng zhǒng jiérán-xiāngfǎn de zhànlüè xíngtài. Lián Pō zài Chángpíng qiánxiàn yītuō dìxíng zhùlěi jiānshǒu, lìng Qínjūn shùshí wàn jīngruì jìntuì-liǎngnán. Ruò Zhàowáng néng jiānchí 'yǐ shǒu dài biàn' de cèlüè, dài Qínjūn liáng jìn zì tuì, Zhànguó lìshǐ de géjú huòxǔ jiāng bèi chèdǐ gǎixiě.", "en": "In ancient warfare, attack and defense represented polar strategies. Lian Po's defense behind fortifications put Qin troops in a dilemma. Had King Zhao maintained this strategy until Qin's food ran out, history might have changed completely.", "es": "En la guerra clásica, ataque y defensa eran polos opuestos. La defensa numantina de Lian Po desconcertó a las tropas de Qin. Si el rey de Zhao hubiera mantenido la defensa hasta agotar el grano enemigo, la historia habría cambiado."}, {"id": "#2", "hanzi": "“守”不仅是一种军事防御战术，更是一种坚守初心的道德操守。无论是在学术研究中耐得住冷板凳、严守学术底线，还是在日常生活中恪守契约与诚信，“守得云开见月明”的定力与坚韧，是成就卓越人生的基石。", "pinyin": "'Shǒu' bùjǐn shì yī zhǒng jūnshì fángyù zhànshù, gèng shì yī zhǒng jiānshǒu chūxīn de dàodé cāoshǒu. Wúlùn shì zài xuéshù yánjiū zhōng nàidézhù lěngbǎndèng, yánshǒu xuéshù dǐxiàn, háishì zài rìcháng shēnghuó zhōng kèshǒu qìyuē yǔ chéngxìn, 'shǒu dé yún kāi jiàn yuè míng' de dìnglì yǔ jiānrèn, shì chéngjiù zhuóyuè rénshēng de jīshí.", "en": "'Guarding' is not merely tactical defense, but moral integrity. Whether enduring quiet toil to uphold academic ethics or keeping agreements in life, steadfast tenacity until clouds clear paves the path to an accomplished life.", "es": "Defender una posición no es solo maniobra bélica, sino firmeza moral. Ya sea guardando el rigor ético en la ciencia o acatando acuerdos en la vida diaria, perseverar hasta que aclare el cielo es la base de una vida noble."}]}, {"meanings_summary": {"en": "battlefield position; front; stronghold; territory", "es": "posición en el frente; trinchera; baluarte; posición de combate"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Chariots drawn up in battle ranks (阵) anchored to fortified terrain (地) establish a military position (阵地).", "composite_memory_hook_es": "Carros desplegados en formación táctica (阵) anclados sobre el terreno defensivo (地) forjan la posición de combate (阵地).", "cultural_and_cognitive_roots": "Originates in classical chariot warfare where holding the prepared tactical position (阵) determined survival against cavalry charges.", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'zhèn dì' (51-51). Articulate both syllables with martial, decisive force."}, "semantic_boundary_contrasts": {"core_nuance": "阵地 strictly refers to a fortified battlefield stronghold or tactical line held by an army, or metaphorical sphere.", "contrasts": [{"id": "1", "compared_word": "阵地 vs. 战场", "pinyin": "zhànchǎng", "analysis": "战场 is the broad operational war theater, while 阵地 is a specific fortified tactical hill or line."}, {"id": "2", "compared_word": "阵地 vs. 营地", "pinyin": "yíngdì", "analysis": "营地 refers to an encampment for soldiers' bivouac/sleep, whereas 阵地 is deployed for combat."}, {"id": "3", "compared_word": "阵地 vs. 领土", "pinyin": "lǐngtǔ", "analysis": "领土 is sovereign legal national territory, unlike a localized military 阵地."}]}, "traps_and_cognates": {"look_alikes": [{"character": "陈", "pinyin": "chén", "meaning_en": "old; display", "distinction_note": "East 东 on right of 阝 instead of 车"}, {"character": "连", "pinyin": "lián", "meaning_en": "connect", "distinction_note": "Movement 辶 on left of 车 instead of 阝"}, {"character": "池", "pinyin": "chí", "meaning_en": "pool; pond", "distinction_note": "Water 氵 on left of 也 instead of 土"}, {"character": "他", "pinyin": "tā", "meaning_en": "he; him", "distinction_note": "Person 亻 on left of 也 instead of 土"}], "etymological_cognates": [{"character": "阵线", "pinyin": "zhènxiàn", "gloss_en": "battlefront; battle line"}, {"character": "阵容", "pinyin": "zhènróng", "gloss_en": "lineup; battle array"}, {"character": "阵雨", "pinyin": "zhènyǔ", "gloss_en": "shower; squall"}, {"character": "地点", "pinyin": "dìdiǎn", "gloss_en": "location; place"}]}, "id": "15", "hanzi": "阵地", "pinyin": "zhèn dì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a designated terrain or fortified area occupied by military troops for defense or attack; figurative sphere of activity", "definition_es": "terreno fortificado o sector ocupado por tropas militares para el combate; reducto o baluarte figurado", "example_phrase": "坚守阵地 (firmly hold one's battlefield position)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括接替廉颇后轻率放弃了坚固险要的防御阵地，冒然出击，结果使数十万大军落入秦军包围圈。", "pinyin": "Zhào Kuò jiētì Lián Pō hòu qīngshuài fàngqì le jiāngù xiǎnyào de fángyù zhèndì, màorán chūjī, jiéguǒ shǐ shùshí wàn dàjūn luòrù Qínjūn bāowéiquān.", "en": "Replacing Lian Po, Zhao Kuo rashly abandoned fortified strategic positions to attack recklessly, causing his army to fall into Qin's encirclement.", "es": "Al relevar a Lian Po, Zhao Kuo abandonó con temeridad las sólidas posiciones defensivas, haciendo que su ejército cayera en la trampa enemiga."}, {"id": "#2", "hanzi": "互联网新媒体已经成为当代思想文化传播与公众舆论引导的重要阵地。", "pinyin": "Hùliánwǎng xīn méitǐ yǐjīng chéngwéi dāngdài sīxiǎng wénhuà chuánbō yǔ gōngzhòng yúlùn yǐndǎo de zhòngyào zhèndì.", "en": "New digital internet media have become vital battlegrounds for modern cultural communication and public opinion guidance.", "es": "Los nuevos medios digitales se han convertido en un baluarte crucial para la difusión cultural y la orientación de la opinión pública."}], "collocations": [{"hanzi": "坚守阵地", "en": "firmly hold the position"}, {"hanzi": "占领阵地", "en": "occupy / seize the position"}, {"hanzi": "防御阵地", "en": "defensive position"}, {"hanzi": "前沿阵地", "en": "frontline position / forward post"}, {"hanzi": "阵地战", "en": "position warfare / trench combat"}, {"hanzi": "思想阵地", "en": "ideological frontline / cultural sphere"}], "idioms": [{"hanzi": "严阵以待", "pinyin": "yán zhèn yǐ dài", "meaning_en": "stand in battle array waiting for the enemy in combat readiness"}, {"hanzi": "固若金汤", "pinyin": "gù ruò jīn tāng", "meaning_en": "strongly fortified like metal ramparts and boiling moats"}, {"hanzi": "步步为营", "pinyin": "bù bù wéi yíng", "meaning_en": "make a stand at every step; advance cautiously"}, {"hanzi": "临阵脱逃", "pinyin": "lín zhèn tuō táo", "meaning_en": "flee from the battlefield on the eve of battle"}], "character_decomposition": [{"character": "阵", "pinyin": "zhèn", "meaning_en": "battle array; battle formation; position; gust", "meaning_es": "formación de batalla; posición; racha; despliegue", "radical": "阝", "radical_meaning_en": "mound / hill", "meaning_component": "阝 (earthen embankment) + 车 (war chariots deployed along it)", "sound_component": "阵 (zhèn)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "War chariots 车 deployed along an earthen defensive mound 阝 in tactical battle formation.", "visual_mnemonic_story_en": "Armored chariots (车) positioned in ranks along a defensive earthen ridge (阝) for battle (阵).", "visual_mnemonic_story_es": "Carros de combate (车) apostados a lo largo del terraplén (阝) en rigurosa formación defensiva (阵).", "tone_mnemonic_anchor": "51", "cangjie": "NLKQ", "traditional": "陣"}, {"character": "地", "pinyin": "dì", "meaning_en": "earth; ground; land; soil; place", "meaning_es": "tierra; suelo; terreno; lugar", "radical": "土", "radical_meaning_en": "earth / soil", "meaning_component": "土 (soil / earth mound) + 也 (alluvial basin / serpent)", "sound_component": "也 (yě / dì)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Fertile soil 土 stretching across the terrestrial basin 也; represents land or territory.", "visual_mnemonic_story_en": "Mounds of fertile soil (土) forming vast terrestrial terrain (地).", "visual_mnemonic_story_es": "Montículos de tierra fértil (土) que conforman el suelo y el territorio (地).", "tone_mnemonic_anchor": "51", "cangjie": "GPD", "traditional": "地"}], "extended_reading_passages": [{"id": "#1", "hanzi": "长平之战中，廉颇苦心经营了三年之久的丹河防御阵地，是阻挡秦国大军东进的坚固铁壁。阵地依托险峻关隘修筑堡垒，储粮充足。赵括上任后自作主张全线弃守阵地，最终导致数十万主力在野战中被秦军围歼。", "pinyin": "Chángpíng zhī zhàn zhōng, Lián Pō kǔxīn jīngyíng le sān nián zhī jiǔ de Dānhé fángyù zhèndì, shì zǔdǎng Qínguó dàjūn dōng jìn de jiāngù tiěbì. Zhèndì yītuō xiǎnjùn guān'ài xiūzhù bǎolěi, chǔliáng chōngzú. Zhào Kuò shàngrèn hòu zìzuò-zhǔzhāng quánxiàn qìshǒu zhèndì, zuìzhōng dǎozhì shùshí wàn zhǔlì zài yězhàn zhōng bèi Qínjūn wéijiān.", "en": "At Changping, Lian Po's Danhe fortified position held for three years as an iron wall blocking Qin. The position anchored on mountain passes with abundant food. Zhao Kuo rashly abandoned it, leading his troops to slaughter in open combat.", "es": "En Changping, la posición fortificada del río Dan sostenida por Lian Po durante tres años frenó el avance de Qin. Bien abastecida en los pasos de montaña, Zhao Kuo la abandonó con temeridad, llevando a sus tropas al cerco en campo abierto."}, {"id": "#2", "hanzi": "在当今全球文化多元激荡的时代，优秀传统文化是守护民族精神根基的重要阵地。面对纷繁复杂的外部思潮，我们必须守好自己的思想文化阵地，传承中华优秀传统美德，坚定文化自信，为民族复兴提供深厚滋养。", "pinyin": "Zài dāngjīn quánqiú wénhuà duōyuán jīdàng de shídài, yōuxiù chuántǒng wénhuà shì shǒuhù mínzú jīngshén gēnjī de zhòngyào zhèndì. Miànduì fēnfán-fùzá de wàibù sīcháo, wǒmen bìxū shǒu hǎo zìjǐ de sīxiǎng wénhuà zhèndì, chuánchéng Zhōnghuá yōuxiù chuántǒng měidé, jiāndìng wénhuà zìxìn, wèi mínzú fùxīng tígōng shēnhòu zīyǎng.", "en": "Amid global cultural exchanges, traditional heritage serves as a vital stronghold safeguarding national spirit. Confronting diverse currents, we must defend our cultural ground, passing down classic virtues with steadfast confidence.", "es": "En la era de la globalización cultural, la tradición clásica es un baluarte que resguarda el alma patria. Ante influencias foráneas, debemos custodiar nuestras posiciones culturales, preservando virtudes ancestrales con orgullo."}]}, {"meanings_summary": {"en": "absolute; definitely; unconditionally; completely", "es": "absoluto; categórico; definitivamente; incondicional"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Severed from all comparisons (绝) and having no parallel counterpart (对) defines the absolute (绝对).", "composite_memory_hook_es": "Sin término de comparación (绝) ni pariente que lo iguale (对) se erige lo absoluto (绝对).", "cultural_and_cognitive_roots": "Philosophical concept originating in Buddhist and Daoist epistemology denoting unconditioned ultimate reality transcending dualities.", "tone_sandhi_and_pitch_modulation": "Second tone to fourth tone: 'jué duì' (35-51). Lift cleanly on 'jué', then drop decisively on 'duì'."}, "semantic_boundary_contrasts": {"core_nuance": "绝对 marks unconditional certainty without caveats or comparative relativity.", "contrasts": [{"id": "1", "compared_word": "绝对 vs. 相对", "pinyin": "xiāngduì", "analysis": "相对 is the direct antonym meaning relative, conditional, or comparative."}, {"id": "2", "compared_word": "绝对 vs. 肯定", "pinyin": "kěndìng", "analysis": "肯定 expresses personal psychological certainty, while 绝对 emphasizes categorical unconditionality."}, {"id": "3", "compared_word": "绝对 vs. 大概", "pinyin": "dàgài", "analysis": "大概 denotes approximate probability, completely opposite to non-negotiable 绝对."}]}, "traps_and_cognates": {"look_alikes": [{"character": "断", "pinyin": "duàn", "meaning_en": "break; sever", "distinction_note": "Axe 斤 on right instead of 色"}, {"character": "纪", "pinyin": "jì", "meaning_en": "discipline; age", "distinction_note": "Ji 己 on right of 纟 instead of 色"}, {"character": "时", "pinyin": "shí", "meaning_en": "time", "distinction_note": "Sun 日 on left of 寸 instead of 又"}, {"character": "封", "pinyin": "fēng", "meaning_en": "seal", "distinction_note": "Gui 圭 on left of 寸 instead of 又"}], "etymological_cognates": [{"character": "决绝", "pinyin": "juéjué", "gloss_en": "resolute; breaking ties cleanly"}, {"character": "绝望", "pinyin": "juéwàng", "gloss_en": "despair; hopeless"}, {"character": "对比", "pinyin": "duìbǐ", "gloss_en": "compare; contrast"}, {"character": "对方", "pinyin": "duìfāng", "gloss_en": "the other party; counterpart"}]}, "id": "16", "hanzi": "绝对", "pinyin": "jué duì", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "unconditional, unrestricted, and without exception; completely and definitely", "definition_es": "incondicional, sin excepción ni limitación; de modo categórico y definitivo", "example_phrase": "绝对服从 (obey absolutely and unconditionally)"}], "example_sentences": [{"id": "#1", "hanzi": "在纪律森严的军队中，部下必须绝对服从上级指挥官下达的作战命令，不得擅自违抗。", "pinyin": "Zài jìlǜ sēnyán de jūnduì zhōng, bùxià bìxū juéduì fúcóng shàngjí zhǐhuīguān xiàdá de zuòzhàn mìnglìng, bùdé shànzì wéikàng.", "en": "In a strictly disciplined army, subordinates must absolutely obey combat orders issued by commanding officers without defiance.", "es": "En un ejército de férrea disciplina, los subordinados deben acatar de forma absoluta las órdenes tácticas impartidas sin vacilar."}, {"id": "#2", "hanzi": "这套精密航空发动机控制系统的安全性能经过了反复检验，具备极高的绝对可靠性。", "pinyin": "Zhè tào jīngmì hángkōng fādòngjī kòngzhì xìtǒng de ānquán xìngnéng jīngguò le fǎnfù jiǎnyàn, jùbèi jí gāo de juéduì kěkàoxìng.", "en": "The safety performance of this precision aero-engine control system was verified repeatedly, possessing exceptionally high absolute reliability.", "es": "El rendimiento de este sistema de control para turbinas aeronáuticas ha sido probado reiteradamente, gozando de una fiabilidad absoluta."}], "collocations": [{"hanzi": "绝对保证", "en": "absolute guarantee"}, {"hanzi": "绝对安全", "en": "absolutely safe / secure"}, {"hanzi": "绝对服从", "en": "absolute obedience"}, {"hanzi": "绝对优势", "en": "absolute advantage"}, {"hanzi": "绝对真理", "en": "absolute truth"}, {"hanzi": "绝不可能", "en": "absolutely impossible"}], "idioms": [{"hanzi": "斩钉截铁", "pinyin": "zhǎn dīng jié tiě", "meaning_en": "resolute and decisive; cutting nails and severing iron"}, {"hanzi": "万无一失", "pinyin": "wàn wú yī shī", "meaning_en": "absolutely sure without a single mistake"}, {"hanzi": "毋庸置疑", "pinyin": "wú yōng zhì yí", "meaning_en": "beyond doubt; unquestionable"}, {"hanzi": "一诺千金", "pinyin": "yī nuò qiān jīn", "meaning_en": "a promise worth a thousand pieces of gold; solemn vow"}], "character_decomposition": [{"character": "绝", "pinyin": "jué", "meaning_en": "cut off; sever; absolute; unique; supreme", "meaning_es": "cortar; romper; absoluto; único; extremo", "radical": "纟", "radical_meaning_en": "silk / thread", "meaning_component": "纟 (silken thread) + 色/刀 (cutting blade severing threads completely)", "sound_component": "绝 (jué)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "A sharp knife cleanly severing silk threads 纟 without remaining connection; denotes absolute finality.", "visual_mnemonic_story_en": "Severing silk cords (纟) completely in one decisive cut so nothing remains connected (绝).", "visual_mnemonic_story_es": "Cortar cordones de seda (纟) de un tajo limpio de modo tajante y definitivo (绝).", "tone_mnemonic_anchor": "35", "cangjie": "VMNAU", "traditional": "絕"}, {"character": "对", "pinyin": "duì", "meaning_en": "correct; opposite; pair; towards", "meaning_es": "correcto; par; frente a; hacia", "radical": "寸", "radical_meaning_en": "inch / hand", "meaning_component": "又 (hand) + 寸 (ruling hand / matching pair)", "sound_component": "对 (duì)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Two hands holding ceremonial paired vessels facing each other; marks comparison or counterpart.", "visual_mnemonic_story_en": "Hands presenting matching paired ceremonial objects face to face (对).", "visual_mnemonic_story_es": "Manos que ofrecen dos vasijas emparejadas cara a cara (对).", "tone_mnemonic_anchor": "51", "cangjie": "EII", "traditional": "對"}], "extended_reading_passages": [{"id": "#1", "hanzi": "兵法强调“兵无常势，水无常形”。战场上从来没有绝对万全的必胜公式，任何战术都必须根据敌情动态灵活变通。赵括却把书本兵法奉为不可更改的绝对真理，僵化教条，最终在变幻莫测的决战中自取灭亡。", "pinyin": "Bīngfǎ qiángdiào 'bīng wú chángshì, shuǐ wú chángxíng'. Zhànchǎng shang cónglái méiyǒu juéduì wànquán de bìshèng gōngshì, rènhé zhànshù dōu bìxū gēnjù díqíng dòngtài línghuó biàntōng. Zhào Kuò què bǎ shūběn bīngfǎ fèng wéi bùkě gēnggǎi de juéduì zhēnlǐ, jiānghuà jiàotiáo, zuìzhōng zài biànhuàn-mòcè de juézhàn zhōng zìqǔ-mièwáng.", "en": "Strategy stresses that 'military posture has no constant form, like water.' Battlefields harbor no absolute victory formulas. Zhao Kuo treated written texts as immutable absolute truth, destroying himself through dogmatism.", "es": "El arte militar afirma que la guerra no tiene pautas fijas, como el fluir del agua. No existen fórmulas absolutas de victoria. Zhao Kuo tomó los libros como dogmas inmutables y halló su propia perdición."}, {"id": "#2", "hanzi": "在现代科学哲学体系中，人类对客观世界的认知是一个不断深化的过程，并没有绝对静止的终极真理。任何伟大的科学定律都是在一定边界条件下的相对真理，勇于质疑既有理论，正是推动科学不断迈向新高度的核心动力。", "pinyin": "Zài xiàndài kēxué zhéxué tǐxì zhōng, rénlèi duì kèguān shìjiè de rènzhī shì yī gè bùduàn shēnhuà de guòchéng, bìng méiyǒu juéduì jìngzhǐ de zhōngjí zhēnlǐ. Rènhé wěidà de kēxué dìnglǜ dōu shì zài yīdìng biānjiè tiáojiàn xià de xiāngduì zhēnlǐ, yǒngyú zhìyí jìyǒu lǐlùn, zhèngshì tuīdòng kēxué bùduàn mài xiàng xīn gāodù de héxīn dònglì.", "en": "In modern scientific philosophy, human knowledge deepens continually without absolute terminal truths. Great laws are relative truths under boundary conditions; daring to challenge prevailing frameworks propels science forward.", "es": "En la filosofía científica contemporánea, el conocimiento es un proceso en constante profundización sin dogmas absolutos. Las leyes físicas rigen bajo condiciones acotadas; cuestionarlas es el motor del avance científico."}]}, {"meanings_summary": {"en": "proactive; taking the initiative; active; of one's own accord", "es": "activo; proactivo; tomar la iniciativa; por propia voluntad"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Acting as one's own master (主) to initiate purposeful motion (动) means being proactive (主动).", "composite_memory_hook_es": "Obrar como dueño de los propios actos (主) para emprender el movimiento (动) define la proactividad (主动).", "cultural_and_cognitive_roots": "A core strategic concept in Sunzi's Art of War: 'He who arrives first at the battlefield and awaits the enemy is at ease' (致人而不致于人).", "tone_sandhi_and_pitch_modulation": "Third tone to fourth tone: 'zhǔ dòng' (214-51). Dip low on 'zhǔ', then drop decisively on 'dòng'."}, "semantic_boundary_contrasts": {"core_nuance": "主动 emphasizes seizing the initiative, acting by internal drive, and controlling circumstances.", "contrasts": [{"id": "1", "compared_word": "主动 vs. 被动", "pinyin": "bèidòng", "analysis": "被动 is the direct antonym meaning passive, reactive, or driven against one's will."}, {"id": "2", "compared_word": "主动 vs. 积极", "pinyin": "jījí", "analysis": "积极 stresses enthusiastic and optimistic attitude, while 主动 emphasizes taking self-directed initiative."}, {"id": "3", "compared_word": "主动 vs. 盲动", "pinyin": "mángdòng", "analysis": "盲动 means rash, blind action without planning, contrasting with calculated 主动."}]}, "traps_and_cognates": {"look_alikes": [{"character": "玉", "pinyin": "yù", "meaning_en": "jade", "distinction_note": "Dot inside lower right instead of top flame dot"}, {"character": "王", "pinyin": "wáng", "meaning_en": "king", "distinction_note": "Lacks the upper flame dot 丶 of 主"}, {"character": "功", "pinyin": "gōng", "meaning_en": "merit", "distinction_note": "Work 工 on left instead of 云"}, {"character": "幼", "pinyin": "yòu", "meaning_en": "young", "distinction_note": "Yao 幺 on left instead of 云"}], "etymological_cognates": [{"character": "主人", "pinyin": "zhǔrén", "gloss_en": "master; host"}, {"character": "主张", "pinyin": "zhǔzhāng", "gloss_en": "advocate; proposition"}, {"character": "动作", "pinyin": "dòngzuò", "gloss_en": "movement; action"}, {"character": "自动", "pinyin": "zìdòng", "gloss_en": "automatic; voluntary"}]}, "id": "17", "hanzi": "主动", "pinyin": "zhǔ dòng", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "acting of one's own volition and taking the initiative rather than being driven by external force", "definition_es": "que actúa por propia iniciativa e impulso sin aguardar órdenes o presiones externas", "example_phrase": "掌握主动权 (seize the initiative)"}], "example_sentences": [{"id": "#1", "hanzi": "善于指挥的军事统帅总能通过巧妙布阵调动敌人，牢牢掌握战场作战的主动权。", "pinyin": "Shànyú zhǐhuī de jūnshì tǒngshuài zǒng néng tōngguò qiǎomiào bùzhèn diàodòng dírén, láoláo zhǎngwò zhànchǎng zuòzhàn de zhǔdòngquán.", "en": "Skillful military commanders always manipulate enemy forces through clever arrays, firmly seizing the combat initiative on the battlefield.", "es": "Los comandantes diestros logran mover al enemigo mediante hábiles maniobras, reteniendo con firmeza la iniciativa del combate."}, {"id": "#2", "hanzi": "在大学自主学习过程中，学生应当主动查阅文献并积极向导师请教学术疑惑。", "pinyin": "Zài dàxué zìzhǔ xuéxí guòchéng zhōng, xuéshēng yīngdāng zhǔdòng cháyuè wénxiàn bìng jījí xiàng dǎoshī qǐngjiào xuéshù yíhuò.", "en": "During independent university study, students should proactively consult literature and actively seek counsel from advisors on academic puzzles.", "es": "En el estudio universitario autónomo, los alumnos deben consultar bibliografía por iniciativa propia y plantear dudas a sus tutores."}], "collocations": [{"hanzi": "掌握主动权", "en": "seize / hold the initiative"}, {"hanzi": "主动配合", "en": "proactively cooperate"}, {"hanzi": "争取主动", "en": "strive for the initiative"}, {"hanzi": "主动沟通", "en": "proactively communicate"}, {"hanzi": "主动出击", "en": "take the initiative to attack"}, {"hanzi": "变被动为主动", "en": "turn passive into proactive"}], "idioms": [{"hanzi": "先发制人", "pinyin": "xiān fā zhì rén", "meaning_en": "take the initiative and strike first to gain the upper hand"}, {"hanzi": "反客为主", "pinyin": "fǎn kè wéi zhǔ", "meaning_en": "turn from guest into host; seize leadership and initiative"}, {"hanzi": "积极主动", "pinyin": "jī jí zhǔ dòng", "meaning_en": "enthusiastic and proactive"}, {"hanzi": "抢占先机", "pinyin": "qiǎng zhàn xiān jī", "meaning_en": "seize the preemptive opportunity"}], "character_decomposition": [{"character": "主", "pinyin": "zhǔ", "meaning_en": "master; host; owner; primary; main", "meaning_es": "dueño; amo; anfitrión; principal", "radical": "丶", "radical_meaning_en": "dot", "meaning_component": "flame burning at the top of an oil lamp stand 王", "sound_component": "主 (zhǔ)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "A flame dot 丶 glowing atop an ancestral lamp stand 王; signifies the central master of the household.", "visual_mnemonic_story_en": "A radiant flame (丶) shining atop an oil lamp stand presiding as the master of the hall (主).", "visual_mnemonic_story_es": "La llama radiante (丶) que arde sobre la lámpara ceremonial presidiendo como dueña de casa (主).", "tone_mnemonic_anchor": "214", "cangjie": "YG", "traditional": "主"}, {"character": "动", "pinyin": "dòng", "meaning_en": "move; act; motion; stir", "meaning_es": "mover; actuar; movimiento; impulso", "radical": "力", "radical_meaning_en": "strength / power", "meaning_component": "云 (clouds rolling across sky) + 力 (physical strength)", "sound_component": "云 (yún)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Using muscular strength 力 to drive physical movement like surging clouds 云; signifies action.", "visual_mnemonic_story_en": "Applying strength (力) to initiate dynamic action like billowing clouds (动).", "visual_mnemonic_story_es": "Aplicar la fuerza (力) para mover las cosas con la soltura de las nubes (动).", "tone_mnemonic_anchor": "51", "cangjie": "MIS", "traditional": "動"}], "extended_reading_passages": [{"id": "#1", "hanzi": "《孙子兵法》有云：“善战者，致人而不致于人。”高明的将领善于调动敌人，而不是被敌人牵着鼻子走。长平之战中，赵括自恃勇武盲目主动出击，反而丧失了战局的主动权，被狡猾的秦军分割包围在狭长山谷之中。", "pinyin": "Sūnzǐ Bīngfǎ yǒu yún: 'Shàn zhàn zhě, zhì rén ér bù zhì yú rén.' Gāomíng de jiànglǐng shànyú diàodòng dírén, ér bùshì bèi dírén qiānzhe bízi zǒu. Chángpíng zhī zhàn zhōng, Zhào Kuò zìshì yǒngwǔ mángmù zhǔdòng chūjī, fǎn'ér sàngshī le zhànjú de zhǔdòngquán, bèi jiǎohuá de Qínjūn fēngē-bāowéi zài xiácháng shāngǔ zhīzhōng.", "en": "The Art of War states: 'The skilled warrior moves the enemy rather than being moved.' In Changping, Zhao Kuo's rash initiative surrendered genuine initiative, allowing the Qin army to lure and encircle him in a narrow gorge.", "es": "Sun Tzu afirmó: 'El diestro en la guerra hace que el enemigo acuda a él, no va donde el enemigo quiere.' En Changping, la imprudente iniciativa de Zhao Kuo le hizo perder el control, siendo cercado en una angosta garganta."}, {"id": "#2", "hanzi": "在当今充满机遇与挑战的职场竞争中，具备主动作为的意识往往是脱颖而出的关键。与其坐等任务下达，不如主动思考问题、主动寻找解决突破口。积极主动的人总能在平凡的岗位上创造出非凡的业绩。", "pinyin": "Zài dāngjīn chōngmǎn jīyù yǔ tiǎozhàn de zhíchǎng jìngzhēng zhōng, jùbèi zhǔdòng zuòwéi de yìshí wǎngwǎng shì tuōyǐng-érchū de guānjiàn. Yǔqí zuò děng rènwu xiàdá, bùrú zhǔdòng sīkǎo wèntí, zhǔdòng xúnzhǎo jiějué tūpòkǒu. Jījí-zhǔdòng de rén zǒng néng zài píngfán de gǎngwèi shang chuàngzào chū fēifán de yèjì.", "en": "In today's career competition, a proactive mindset is the key to standing out. Rather than sitting waiting for orders, proactively seeking solutions empowers individuals to achieve extraordinary feats in any role.", "es": "En la carrera profesional, la proactividad distingue a los sobresalientes. En vez de aguardar órdenes pasivamente, buscar soluciones por iniciativa propia permite forjar logros extraordinarios en cualquier puesto."}]}, {"meanings_summary": {"en": "to challenge; defy; challenge (noun)", "es": "desafiar; retar; reto; desafío"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Prodding an adversary with hands (挑) to enter armed combat (战) constitutes a challenge (挑战).", "composite_memory_hook_es": "Provocar al contrincante (挑) para batirse en combate armado (战) conforma un desafío (挑战).", "cultural_and_cognitive_roots": "Originates from ancient chivalric dueling where heralds cast down gauntlets before battle lines ('叫战').", "tone_sandhi_and_pitch_modulation": "Third tone to fourth tone: 'tiǎo zhàn' (214-51). Dip low on 'tiǎo', dropping sharply on 'zhàn'."}, "semantic_boundary_contrasts": {"core_nuance": "挑战 involves initiating combat or confronting daunting obstacles requiring grit and skill.", "contrasts": [{"id": "1", "compared_word": "挑战 vs. 迎战", "pinyin": "yíngzhàn", "analysis": "挑战 is issuing the challenge, while 迎战 is accepting and facing the challenge incoming."}, {"id": "2", "compared_word": "挑战 vs. 挑衅", "pinyin": "tiǎoxìn", "analysis": "挑衅 carries malicious, bullying provocation, whereas 挑战 is often noble, athletic, or ambitious."}, {"id": "3", "compared_word": "挑战 vs. 退缩", "pinyin": "tuìsuō", "analysis": "退缩 is the direct antonym meaning to cower back from difficulties."}]}, "traps_and_cognates": {"look_alikes": [{"character": "桃", "pinyin": "táo", "meaning_en": "peach", "distinction_note": "Wood radical 木 on left instead of 扌"}, {"character": "跳", "pinyin": "tiào", "meaning_en": "jump", "distinction_note": "Foot radical 足 on left instead of 扌"}, {"character": "站", "pinyin": "zhàn", "meaning_en": "stand; station", "distinction_note": "Stand 立 on left instead of 戈 on right"}, {"character": "贴", "pinyin": "tiē", "meaning_en": "stick; paste", "distinction_note": "Shell 贝 on left of 占"}], "etymological_cognates": [{"character": "挑衅", "pinyin": "tiǎoxìn", "gloss_en": "provoke; incite defiance"}, {"character": "挑选", "pinyin": "tiāoxuǎn", "gloss_en": "choose; pick (first tone tiāo)"}, {"character": "战胜", "pinyin": "zhànshèng", "gloss_en": "vanquish; overcome"}, {"character": "应战", "pinyin": "yìngzhàn", "gloss_en": "accept a battle challenge"}]}, "id": "18", "hanzi": "挑战", "pinyin": "tiǎo zhàn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to invite an opponent to a contest, fight, or duel; to confront difficult trials or obstacles", "definition_es": "desafiar o retar a un oponente al combate o competición; afrontar dificultades exigentes", "example_phrase": "迎接严峻挑战 (face grim challenges)"}], "example_sentences": [{"id": "#1", "hanzi": "秦军为了诱使赵括脱离坚固阵地，多次派出小股先锋部队到赵军营垒前叫阵挑战、大声辱骂。", "pinyin": "Qínjūn wèile yòushǐ Zhào Kuò tuōlí jiāngù zhèndì, duō cì pài chū xiǎo gǔ xiānfēng bùduì dào Zhàojūn yínglěi qián jiàozhèn tiǎozhàn, dàshēng rǔmà.", "en": "To lure Zhao Kuo away from fortified positions, Qin repeatedly sent vanguard units to challenge and taunt before Zhao camps.", "es": "Para tentar a Zhao Kuo a abandonar sus baluartes, Qin envió destacamentos a proferir retos e insultos ante el campamento enemigo."}, {"id": "#2", "hanzi": "青年科研工作者应当敢于挑战学术权威，勇于在未知的科技无人区探索创新路径。", "pinyin": "Qīngnián kēyán gōngzuòzhě yīngdāng gǎnyú tiǎozhàn xuéshù quánwēi, yǒngyú zài wèizhī de kējì wúrénqū tànsuǒ chuàngxīn lùjìng.", "en": "Young researchers should dare to challenge academic dogmas and boldly explore innovative paths in uncharted scientific frontiers.", "es": "Los jóvenes científicos deben atreverse a desafiar dogmas consagrados y explorar sendas inéditas en la vanguardia del saber."}], "collocations": [{"hanzi": "迎接挑战", "en": "meet / embrace challenges"}, {"hanzi": "面临挑战", "en": "face / confront challenges"}, {"hanzi": "发起挑战", "en": "launch a challenge"}, {"hanzi": "巨大的挑战", "en": "formidable / massive challenge"}, {"hanzi": "挑战极限", "en": "challenge the limits"}, {"hanzi": "挑战权威", "en": "challenge authority"}], "idioms": [{"hanzi": "明知山有虎，偏向虎山行", "pinyin": "míng zhī shān yǒu hǔ, piān xiàng hǔ shān xíng", "meaning_en": "go forward deliberately into danger despite knowing hazards"}, {"hanzi": "乘风破浪", "pinyin": "chéng fēng pò làng", "meaning_en": "brave the wind and waves; forge ahead through adversity"}, {"hanzi": "挺身而出", "pinyin": "tǐng shēn ér chū", "meaning_en": "step forward bravely to meet the challenge"}, {"hanzi": "越战越勇", "pinyin": "yuè zhàn yuè yǒng", "meaning_en": "grow braver and more resolute with each battle"}], "character_decomposition": [{"character": "挑", "pinyin": "tiǎo", "meaning_en": "provoke; incite; prick; lift up", "meaning_es": "provocar; incitar; alzar con la punta; azuzar", "radical": "扌", "radical_meaning_en": "hand", "meaning_component": "扌 (hand action) + 兆 (signs / portents / crackles)", "sound_component": "兆 (zhào / tiāo)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Using a hand 扌 or spear tip to prick and stir up 兆 reactions; signifies inciting combat.", "visual_mnemonic_story_en": "Using a weapon tip with hands (扌) to prod and provoke an opponent into a duel (挑).", "visual_mnemonic_story_es": "Usar la punta de la lanza con las manos (扌) para azuzar al contrincante al duelo (挑).", "tone_mnemonic_anchor": "214", "cangjie": "QLMO", "traditional": "挑"}, {"character": "战", "pinyin": "zhàn", "meaning_en": "war; battle; combat; fight", "meaning_es": "guerra; batalla; combate; luchar", "radical": "戈", "radical_meaning_en": "dagger-axe / halberd", "meaning_component": "占 (territory claimed by divination) + 戈 (striking halberd)", "sound_component": "占 (zhàn)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Wielding bronze halberds 戈 in battle to contest territory 占; signifies combat.", "visual_mnemonic_story_en": "Wielding battle weapons (戈) to contest war prizes in combat (战).", "visual_mnemonic_story_es": "Empuñar las armas de bronce (戈) en el fragor de la contienda armada (战).", "tone_mnemonic_anchor": "51", "cangjie": "YRI", "traditional": "戰"}], "extended_reading_passages": [{"id": "#1", "hanzi": "长平前线，秦军将领深知赵括年少气盛、急于求成的性格弱点，每日派出小队骑兵到赵军壁垒前叫骂挑战。廉颇在位时对挑衅置之不理，而赵括一上任便按捺不住怒火，不顾地形险峻仓促应战，正中秦军诡计。", "pinyin": "Chángpíng qiánxiàn, Qínjūn jiànglǐng shēnzhī Zhào Kuò niánshào-qìshèng, jíyú-qiúchéng de xìnggé ruòdiǎn, měirì pài chū xiǎoduì qíbīng dào Zhàojūn bìlěi qián jiàomà tiǎozhàn. Lián Pō zàiwèi shí duì tiǎoxìn zhìzhī-bùlǐ, ér Zhào Kuò yī shàngrèn biàn ànnà-bùzhù nùhuǒ, bùgù dìxíng xiǎnjùn cāngcù yìngzhàn, zhèngzhòng Qínjūn guǐjì.", "en": "At Changping, Qin commanders knew Zhao Kuo's youthful impatience and sent daily riders to taunt and challenge him. Lian Po ignored them, but Zhao Kuo could not contain his fury, rushing into battle and falling into the ambush.", "es": "En Changping, los mandos de Qin sabían de la impetuosa soberbia de Zhao Kuo y enviaron jinetes a insultarlo a las puertas. Lian Po los ignoraba; Zhao Kuo, enfurecido, salió a combatir cayendo en la celada."}, {"id": "#2", "hanzi": "人生就是一场不断战胜未知与迎接挑战的壮丽旅程。无论前方的道路多么坎坷漫长，敢于直面挑战、把艰难险阻视作磨砺意志的宝贵财富，我们才能在一次次风浪考验中强健筋骨，最终实现人生的崇高飞跃。", "pinyin": "Rénshēng jiùshì yī chǎng bùduàn zhànshèng wèizhī yǔ yíngjiē tiǎozhàn de zhuànglì lǚchéng. Wúlùn qiánfāng de dàolù duōme kǎnkě màncháng, gǎnyú zhímiàn tiǎozhàn, bǎ jiānnán-xiǎnzǔ shìzuò mólì yìzhì de bǎoguì cáifù, wǒmen cái néng zài yī cì cì fēnglàng kǎoyàn zhōng qiángjiàn jīngǔ, zuìzhōng shíxiàn rénshēng de chónggāo fēiyuè.", "en": "Life is a journey of overcoming the unknown and embracing challenges. No matter how rugged the road ahead, facing trials bravely and treating adversity as a forge of will fortifies us to achieve sublime leaps of character.", "es": "La vida es una travesía de retos y descubrimientos. Por áspero que sea el camino, encarar los desafíos y asumir los obstáculos como templanza del alma nos fortalece para consumar grandes hazañas personales."}]}, {"meanings_summary": {"en": "to curse; scold; abuse verbally; call names", "es": "maldecir; insultar; reñir; increpar; reprender"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Two shouting mouths (吅) roaring like an agitated stallion (马) signifies abusive scolding (骂).", "composite_memory_hook_es": "Dos bocas vociferantes (吅) rugiendo con la furia de un potro (马) encarnan la acción de insultar o reñir (骂).", "cultural_and_cognitive_roots": "Common psychological warfare tactic in ancient Chinese battles ('骂阵') used to irritate hotheaded commanders into blunders.", "tone_sandhi_and_pitch_modulation": "Fourth tone: 'mà' (51). Sharp, short, and emphatic downward inflection."}, "semantic_boundary_contrasts": {"core_nuance": "骂 focuses on angry, abusive, or disciplinary vocal chastisement.", "contrasts": [{"id": "1", "compared_word": "骂 vs. 批评", "pinyin": "pīpíng", "analysis": "批评 is rational objective critique of errors, while 骂 carries angry verbal scolding or profanity."}, {"id": "2", "compared_word": "骂 vs. 夸", "pinyin": "kuā", "analysis": "夸 is the direct antonym meaning to praise, flatter, or compliment."}, {"id": "3", "compared_word": "骂 vs. 劝", "pinyin": "quàn", "analysis": "劝 means gentle, patient persuasion, whereas 骂 is harsh and aggressive reprimand."}]}, "traps_and_cognates": {"look_alikes": [{"character": "马", "pinyin": "mǎ", "meaning_en": "horse", "distinction_note": "Lacks the two mouth radical 吅 on top"}, {"character": "驾", "pinyin": "jià", "meaning_en": "drive; harness", "distinction_note": "Add 加 on top of 马 instead of 吅"}, {"character": "骂 (traditional 罵)", "pinyin": "mà", "meaning_en": "curse", "distinction_note": "Simplified has 吅 over 马 instead of 网/罒"}, {"character": "哭", "pinyin": "kū", "meaning_en": "cry; weep", "distinction_note": "Dog 犬 under 吅 instead of 马"}], "etymological_cognates": [{"character": "斥责", "pinyin": "chìzé", "gloss_en": "reprimand; denounce"}, {"character": "谩骂", "pinyin": "mànmà", "gloss_en": "hurl abuses; vilify"}, {"character": "辱骂", "pinyin": "rǔmà", "gloss_en": "insult and curse"}, {"character": "责备", "pinyin": "zébèi", "gloss_en": "blame; reprove"}]}, "id": "19", "hanzi": "骂", "pinyin": "mà", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to utter abusive words, scold angrily, curse, or reprimand someone harshly", "definition_es": "proferir insultos, improperios o reprender ásperamente a alguien con enfado", "example_phrase": "大声斥骂 (scold and reprimand loudly)"}], "example_sentences": [{"id": "#1", "hanzi": "秦军将士遵照白起的密令，在赵军营垒前日夜大声叫骂，讽刺赵括不过是个不敢出战的胆小鬼。", "pinyin": "Qínjūn jiàngshì zūnjào Bái Qǐ de mìlìng, zài Zhàojūn yínglěi qián rìyè dàshēng jiàomà, fěngcì Zhào Kuò bùguò shì gè bù gǎn chūzhàn de dǎnxiǎoguǐ.", "en": "Following Bai Qi's secret order, Qin soldiers shouted curses day and night outside Zhao's camp, taunting Zhao Kuo as a coward who feared battle.", "es": "Cumpliendo órdenes de Bai Qi, los soldados de Qin insultaban noche y día ante el campamento, tildando a Zhao Kuo de cobarde asustadizo."}, {"id": "#2", "hanzi": "母亲并没有厉声责骂犯错的孩子，而是温和地拉着他的手，耐心地讲明做人应当诚实的道理。", "pinyin": "Mǔqīn bìng méiyǒu lìshēng zémà fàncuò de háizi, ér shì wēnhé de lā zhe tā de shǒu, nàixīn de jiǎngmíng zuòrén yīngdāng chéngshí de dàolǐ.", "en": "The mother did not harshly scold her errant child; instead, taking his hand gently, she patiently explained the principle of honesty.", "es": "La madre no reprendió con aspereza al hijo que erró; tomándole la mano con ternura, le explicó con paciencia el deber de la honradez."}], "collocations": [{"hanzi": "责骂批评", "en": "scold and criticize"}, {"hanzi": "大声叫骂", "en": "shout curses loudly"}, {"hanzi": "挨骂受气", "en": "get scolded and suffer abuse"}, {"hanzi": "骂人粗话", "en": "curse at people / profanities"}, {"hanzi": "破口大骂", "en": "burst into abusive curses"}, {"hanzi": "痛骂一顿", "en": "give someone a fierce dressing-down"}], "idioms": [{"hanzi": "破口大骂", "pinyin": "pò kǒu dà mà", "meaning_en": "burst out into violent verbal abuse and cursing"}, {"hanzi": "嬉笑怒骂", "pinyin": "xī xiào nù mà", "meaning_en": "ridiculing, joking, and scolding freely in literary prose"}, {"hanzi": "恶语伤人", "pinyin": "è yǔ shāng rén", "meaning_en": "hurting people with cruel and venomous words"}, {"hanzi": "忍气吞声", "pinyin": "rěn qì tūn shēng", "meaning_en": "swallow one's anger and endure insult without reply"}], "character_decomposition": [{"character": "骂", "pinyin": "mà", "meaning_en": "scold; curse; abuse verbally", "meaning_es": "reñir; maldecir; insultar; increpar", "radical": "马", "radical_meaning_en": "horse", "meaning_component": "吅 (two mouths shouting loudly) + 马 (horse galloping / phonetic)", "sound_component": "马 (mǎ)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Two open mouths 吅 clamoring noisily over a horse 马; signifies shouting verbal abuse and scolding.", "visual_mnemonic_story_en": "Two mouths (吅) shouting noisy angry words over a rearing horse (马) in abusive fury (骂).", "visual_mnemonic_story_es": "Dos bocas que vociferan (吅) improperios sobre un corcel enfurecido (马) al increpar (骂).", "tone_mnemonic_anchor": "51", "cangjie": "RRNS", "traditional": "罵"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在长平之战的营垒前，秦军深谙攻心之道。他们派出精悍骑兵在阵前大声叫骂，讽刺赵军将领怯懦无能。老将廉颇心如磐石、置若罔闻，而年轻自负的赵括却经受不住敌军的嘲弄与辱骂，怒火攻心，终于铸成大错。", "pinyin": "Zài Chángpíng zhī zhàn de yínglěi qián, Qínjūn shēn'ān gōngxīn zhī dào. Tāmen pài chū jīnghàn qíbīng zài zhènqián dàshēng jiàomà, fěngcì Zhàojūn jiànglǐng qiènuò-wúnéng. Lián Pō xīnrúpánshí, zhìruòwǎngwén, ér niánqīng zìfù de Zhào Kuò què jīngshòu bù zhù díjūn de cháonòng yǔ rǔmà, nùhuǒ-gōngxīn, zhōngyú zhùchéng dàcuò.", "en": "Outside Changping camps, Qin practiced psychological warfare. Horsemen shouted abuses at the gates taunting Zhao generals. Lian Po remained deaf like rock, but vain Zhao Kuo could not endure curses, rushing out in blinding fury.", "es": "Ante las trincheras de Changping, Qin libró guerra psicológica. Jinetes vociferaban insultos denigrando al mando enemigo. Lian Po se mantuvo impávido como una roca, mas el vanidoso Zhao Kuo no toleró la mofa y cayó en la trampa."}, {"id": "#2", "hanzi": "“良言一句三冬暖，恶语伤人六月寒。”在日常人际交往与家庭教育中，粗暴的责骂往往只会激化矛盾、刺伤自尊，而无法真正解决问题。学会克制怒气、心平气和地沟通，是衡量一个人修养与情商的重要标尺。", "pinyin": "'Liángyán yījù sāndōng nuǎn, èyǔ shāngrén liùyuè hán.' Zài rìcháng rénjì jiāowǎng yǔ jiātíng jiàoyù zhōng, cūbào de zémà wǎngwǎng zhǐ huì jīhuà máodùn, cìshāng zìzūn, ér wúfǎ zhēnzhèng jiějué wèntí. Xuéhuì kèzhì nùqì, xīnpíng-qìhé de gōutōng, shì héngliáng yī gè rén xiūyǎng yǔ qíngshāng de zhòngyào biāochǐ.", "en": "'A kind word warms three winter months; cruel words chill in June.' In daily relationships and education, harsh curses only aggravate friction and hurt dignity. Controlling anger and speaking calmly reflects high character and empathy.", "es": "'Una palabra afable calienta tres inviernos; la ofensa hiela en pleno estío.' En el hogar y la vida social, los improperios solo agravan heridas; refrenar la ira y dialogar con mesura es la prueba del temple humano."}]}, {"meanings_summary": {"en": "coward; craven person; chicken", "es": "cobarde; gallina; pusilánime; miedica"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A person whose courage (胆) is minutely tiny (小) and acts like a skittish phantom (鬼) is a coward (胆小鬼).", "composite_memory_hook_es": "Aquel cuyo coraje (胆) es diminuto (小) y huye como una sombra asustadiza (鬼) es un cobarde (胆小鬼).", "cultural_and_cognitive_roots": "Traditional Chinese medicine associates the gallbladder (胆) with decisiveness and bravery; '胆小' indicates faint-heartedness.", "tone_sandhi_and_pitch_modulation": "Third tone sandhi chain: 'dǎn xiǎo guǐ' -> pronounced 'dán xiáo guǐ' (35-35-214). The first two syllables shift to second tone."}, "semantic_boundary_contrasts": {"core_nuance": "胆小鬼 is an informal colloquial noun mocking someone who shrinks from fright or lacks fortitude.", "contrasts": [{"id": "1", "compared_word": "胆小鬼 vs. 勇士", "pinyin": "yǒngshì", "analysis": "勇士 is the direct antonym meaning a brave, fearless warrior."}, {"id": "2", "compared_word": "胆小鬼 vs. 英雄", "pinyin": "yīngxióng", "analysis": "英雄 is an admired heroic champion, opposite to craven 胆小鬼."}, {"id": "3", "compared_word": "胆小鬼 vs. 懦夫", "pinyin": "nuòfū", "analysis": "懦夫 is formal literary for coward, whereas 胆小鬼 is the common spoken idiom."}]}, "traps_and_cognates": {"look_alikes": [{"character": "但", "pinyin": "dàn", "meaning_en": "but; however", "distinction_note": "Person radical 亻 on left instead of 月"}, {"character": "少", "pinyin": "shǎo", "meaning_en": "few; little", "distinction_note": "Has downward right-slanting stroke across bottom"}, {"character": "魁", "pinyin": "kuí", "meaning_en": "chief; head", "distinction_note": "Dipper 斗 on right of 鬼"}, {"character": "魂", "pinyin": "hún", "meaning_en": "soul; spirit", "distinction_note": "Cloud 云 on left of 鬼"}], "etymological_cognates": [{"character": "大胆", "pinyin": "dàdǎn", "gloss_en": "bold; audacious"}, {"character": "胆量", "pinyin": "dǎnliàng", "gloss_en": "courage; guts"}, {"character": "醉鬼", "pinyin": "zuìguǐ", "gloss_en": "drunkard"}, {"character": "机灵鬼", "pinyin": "jīlingguǐ", "gloss_en": "clever little rascal"}]}, "id": "20", "hanzi": "胆小鬼", "pinyin": "dǎn xiǎo guǐ", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a person who utterly lacks courage, is easily frightened, or shrinks from difficulty or danger", "definition_es": "persona timorata que carece de valor, se asusta fácilmente o huye ante el peligro", "example_phrase": "骂他是胆小鬼 (call him a coward)"}], "example_sentences": [{"id": "#1", "hanzi": "秦军为了激怒赵括出战，故意派人在营垒前大声嘲笑他是只敢缩在堡垒里的胆小鬼。", "pinyin": "Qínjūn wèile jìnù Zhào Kuò chūzhàn, gùyì pài rén zài yínglěi qián dàshēng cháoxiào tā shì zhǐ gǎn suō zài bǎolěi lǐ de dǎnxiǎoguǐ.", "en": "To provoke Zhao Kuo into combat, Qin deliberately sent men to laugh outside his camp, taunting him as a coward hiding in bastions.", "es": "Para provocar la furia de Zhao Kuo, Qin envió emisarios a mofarse de él llamándole cobarde refugiado tras las murallas."}, {"id": "#2", "hanzi": "面对突如其来的危急关头，真正的勇士绝不做临阵脱逃的胆小鬼，而是挺身而出勇挑重担。", "pinyin": "Miànduì tūrúqílái de wēijí guāntóu, zhēnzhèng de yǒngshì jué bù zuò línzhèn-tuōtáo de dǎnxiǎoguǐ, ér shì tǐngshēn'érchū yǒng tiāo zhòngdàn.", "en": "Facing sudden peril, true warriors never act as cowards fleeing from battle; instead, they step forward bravely to shoulder burdens.", "es": "Ante la adversidad repentina, el verdadero valiente rehúsa ser un cobarde que deserte; da un paso al frente asumiendo el deber."}], "collocations": [{"hanzi": "做胆小鬼", "en": "be / act like a coward"}, {"hanzi": "不是胆小鬼", "en": "not a coward"}, {"hanzi": "嘲笑胆小鬼", "en": "mock someone as a coward"}, {"hanzi": "胆小鬼行为", "en": "cowardly behavior"}, {"hanzi": "被称为胆小鬼", "en": "be called a coward"}, {"hanzi": "胆小怕事", "en": "timid and cowardly afraid of trouble"}], "idioms": [{"hanzi": "胆小如鼠", "pinyin": "dǎn xiǎo rú shǔ", "meaning_en": "as timid as a mouse; gutless"}, {"hanzi": "贪生怕死", "pinyin": "tān shēng pà sǐ", "meaning_en": "craving life and fearing death; cowardly"}, {"hanzi": "胆大包天", "pinyin": "dǎn dà bāo tiān", "meaning_en": "audacious enough to cover the sky; bold and daring (antonym)"}, {"hanzi": "视死如归", "pinyin": "shì sǐ rú guī", "meaning_en": "look upon death as going home; fearless hero"}], "character_decomposition": [{"character": "胆", "pinyin": "dǎn", "meaning_en": "gallbladder; courage; guts; bravery", "meaning_es": "vesícula biliar; valor; agallas; coraje", "radical": "月", "radical_meaning_en": "flesh / organ", "meaning_component": "月/肉 (flesh / internal organ) + 旦 (dawn rising sun)", "sound_component": "旦 (dàn)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "The bodily internal organ 月 that generates resolute courage like the rising morning sun 旦.", "visual_mnemonic_story_en": "An internal organ (月) radiating courage and boldness like the dawn sun (旦) to form guts (胆).", "visual_mnemonic_story_es": "Una entraña vital (月) que irradia valentía al nacer el sol (旦), sede del coraje (胆).", "tone_mnemonic_anchor": "214", "cangjie": "BAM", "traditional": "膽"}, {"character": "小", "pinyin": "xiǎo", "meaning_en": "small; tiny; little; young", "meaning_es": "pequeño; diminuto; menor", "radical": "小", "radical_meaning_en": "small", "meaning_component": "a vertical object split in half into tiny flecks", "sound_component": "小 (xiǎo)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "A vertical mark divided into two tiny side specks; indicates smallness.", "visual_mnemonic_story_en": "Dividing a small stone into tiny flecks (小).", "visual_mnemonic_story_es": "Partir una pequeña piedra en diminutas esquirlas (小).", "tone_mnemonic_anchor": "214", "cangjie": "NC", "traditional": "小"}, {"character": "鬼", "pinyin": "guǐ", "meaning_en": "ghost; spirit; crafty person; fellow", "meaning_es": "fantasma; espectro; pillo; tipo", "radical": "鬼", "radical_meaning_en": "ghost", "meaning_component": "kneeling human figure with an oversized eerie mask/skull", "sound_component": "鬼 (guǐ)", "stroke_count": "9", "composition_type": "单一结构", "etymology_and_mnemonic": "A spirit or human wearing an uncanny skull-like head mask; used colloquially for a specific type of person.", "visual_mnemonic_story_en": "A figure with a mask scurrying in the shadows like an eerie apparition (鬼).", "visual_mnemonic_story_es": "Una silueta enmascarada que se escurre en la penumbra espectral (鬼).", "tone_mnemonic_anchor": "214", "cangjie": "HUI", "traditional": "鬼"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在古代两军对垒中，如何激怒敌将是一门攻心战术。秦军在阵前高声讽刺赵括是“只配躲在营垒里喝稀饭的胆小鬼”。自幼心高气傲的赵括哪堪忍受这般当众羞辱，为了证明自己不是胆小鬼，他不顾一切地下令全军出击，最终惨败。", "pinyin": "Zài gǔdài liǎng jūn duìlěi zhōng, rúhé jìnù díjiàng shì yī mén gōngxīn zhànshù. Qínjūn zài zhènqián gāoshēng fěngcì Zhào Kuò shì 'zhǐ pèi duǒ zài yínglěi lǐ hē xīfàn de dǎnxiǎoguǐ'. Zìyòu xīngāo-qì'ào de Zhào Kuò nǎ kān rěnshòu zhè bān dāngzhòng xiūrǔ, wèile zhèngmíng zìjǐ bùshì dǎnxiǎoguǐ, tā bùgù-yīqiè de xiàlìng quán jūn chūjī, zuìzhōng cǎibài.", "en": "Provoking opposing generals was psychological warfare. Qin soldiers shouted that Zhao Kuo was a coward fit only to sip porridge in camp. Vain Zhao Kuo could not endure the humiliation; to prove he was no coward, he attacked and lost all.", "es": "En la guerra antigua, exasperar al general rival era un arte sutil. Qin gritaba que Zhao Kuo era un cobarde apto solo para tomar gachas en su tienda. El soberbio Zhao Kuo no soportó la afrenta; para demostrar su valor atacó y pereció."}, {"id": "#2", "hanzi": "面对生活中的挫折与困难，承认害怕并不等于就是懦弱的胆小鬼。真正的勇敢不是毫无畏惧，而是在内心感到恐惧时，依然选择直面风浪、坚定地迈开脚步向前探索。克服恐惧的过程，正是心灵由弱小走向强大的必经之路。", "pinyin": "Miànduì shēnghuó zhōng de cuòzhé yǔ kùnnan, chéngrèn hàipà bìng bù děngyú jiùshì nuòruò de dǎnxiǎoguǐ. Zhēnzhèng de yǒnggǎn bùshì háowú wèijù, ér shì zài nèixīn gǎndào kǒngjù shí, yīrán xuǎnzé zhímiàn fēnglàng, jiāndìng de màikāi jiǎobù xiàngqián tànsuǒ. Kèfú kǒngjù de guòchéng, zhèngshì xīnlíng yóu ruòxiǎo zǒuxiàng qiángdà de bìjīng zhī lù.", "en": "Admitting fear before life's setbacks does not make one a coward. True bravery is not the absence of fear, but pressing forward into the storm despite fear. Conquering terror is how the soul matures from frailty into strength.", "es": "Reconocer el temor ante la adversidad no nos convierte en cobardes. El auténtico coraje no estriba en no sentir miedo, sino en marchar hacia la tempestad a pesar del pánico; vencer el recelo transforma la flaqueza en entereza."}]}, {"meanings_summary": {"en": "to win victory; triumph; victory; successfully", "es": "vencer; triunfar; victoria; triunfo; con éxito"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Vanquishing an adversary through strength (胜) and reaping the fruitful spoils (利) defines victory (胜利).", "composite_memory_hook_es": "Superar al adversario en la contienda (胜) y recoger los frutos laureados (利) constituye la victoria (胜利).", "cultural_and_cognitive_roots": "Blends martial triumph over rivals with the auspicious harvest of benefits and peace.", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'shèng lì' (51-51). Pronounce both syllables with energetic, triumphant downward inflection."}, "semantic_boundary_contrasts": {"core_nuance": "胜利 indicates triumphant conquest of an opponent, challenge, or military campaign.", "contrasts": [{"id": "1", "compared_word": "胜利 vs. 失败", "pinyin": "shībài", "analysis": "失败 is the direct antonym meaning defeat, failure, or collapse."}, {"id": "2", "compared_word": "胜利 vs. 成功", "pinyin": "chénggōng", "analysis": "成功 is broader and applies to fulfilling personal plans or tasks, while 胜利 strongly implies defeating a rival in a contest or battle."}, {"id": "3", "compared_word": "胜利 vs. 平局", "pinyin": "píngjú", "analysis": "平局 means a tie or draw, where neither side secures 胜利."}]}, "traps_and_cognates": {"look_alikes": [{"character": "脸", "pinyin": "liǎn", "meaning_en": "face", "distinction_note": "Lian 佥 on right of 月 instead of 𢎘"}, {"character": "服", "pinyin": "fú", "meaning_en": "clothes; obey", "distinction_note": "Fu 𠬝 on right of 月 instead of 𢎘"}, {"character": "科", "pinyin": "kē", "meaning_en": "science", "distinction_note": "Dipper 斗 on right of 禾 instead of 刂"}, {"character": "和", "pinyin": "hé", "meaning_en": "harmony; with", "distinction_note": "Mouth 口 on right of 禾 instead of 刂"}], "etymological_cognates": [{"character": "胜利者", "pinyin": "shènglìzhě", "gloss_en": "victor; winner"}, {"character": "获胜", "pinyin": "huòshèng", "gloss_en": "win victory; triumph"}, {"character": "利益", "pinyin": "lìyì", "gloss_en": "benefit; interest"}, {"character": "利用", "pinyin": "lìyòng", "gloss_en": "utilize; exploit"}]}, "id": "21", "hanzi": "胜利", "pinyin": "shèng lì", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to vanquish an opponent, win a contest or battle, or achieve success in an undertaking", "definition_es": "derrotar al adversario, coronar con éxito una batalla o alcanzar el triunfo en un empeño", "example_phrase": "取得辉煌胜利 (achieve a glorious victory)"}], "example_sentences": [{"id": "#1", "hanzi": "秦军凭借高超的诱敌战术与严密的包围圈，在惨烈的长平之战中取得了决定性的战略胜利。", "pinyin": "Qínjūn píngjiè gāochāo de yòudí zhànshù yǔ yánmì de bāowéiquān, zài cǎnliè de Chángpíng zhī zhàn zhōng qǔdé le juédìngxìng de zhànlüè shènglì.", "en": "Relying on tactics of luring the enemy and tight encirclement, Qin secured a decisive strategic victory at the Battle of Changping.", "es": "Valiéndose de astutas celadas y un cerco impenetrable, el ejército de Qin obtuvo una decisiva victoria estratégica en Changping."}, {"id": "#2", "hanzi": "经过长达数年的艰苦攻关，该科研项目终于胜利完成了全部核心技术指标的验证工作。", "pinyin": "Jīngguò cháng dá shù nián de jiānkǔ gōngguān, gāi kēyán xiàngmù zhōngyú shènglì wánchéng le quánbù héxīn jìshù zhǐbiāo de yànzhèng gōngzuò.", "en": "After years of arduous research breakthroughs, the scientific project finally concluded the verification of all core technical benchmarks with success.", "es": "Tras años de abnegada investigación, el proyecto culminó con éxito la verificación de todos sus parámetros técnicos primordiales."}], "collocations": [{"hanzi": "取得胜利", "en": "achieve / win victory"}, {"hanzi": "胜利闭幕", "en": "successfully conclude (a congress/meeting)"}, {"hanzi": "胜利成果", "en": "fruits of victory"}, {"hanzi": "走向胜利", "en": "march toward triumph"}, {"hanzi": "重大胜利", "en": "major / momentous victory"}, {"hanzi": "胜利在望", "en": "victory in sight"}], "idioms": [{"hanzi": "旗开得胜", "pinyin": "qí kāi dé shèng", "meaning_en": "win victory at the first unfurling of the flag"}, {"hanzi": "克敌制胜", "pinyin": "kè dí zhì shèng", "meaning_en": "vanquish the foe and secure victory"}, {"hanzi": "战无不胜", "pinyin": "zhàn wú bù shèng", "meaning_en": "invincible in every battle; triumph in all campaigns"}, {"hanzi": "反败为胜", "pinyin": "fǎn bài wéi shèng", "meaning_en": "turn defeat into victory at the critical juncture"}], "character_decomposition": [{"character": "胜", "pinyin": "shèng", "meaning_en": "win; victory; surpass; bear; superb", "meaning_es": "vencer; triunfar; superar; magnífico", "radical": "月", "radical_meaning_en": "flesh / organ", "meaning_component": "月/肉 (flesh / inner sinew strength) + 𢎘/生 (bursting upward growth)", "sound_component": "𢎘 (shèng)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Robust muscular endurance 月 overcoming obstacles to rise above all rivals 生; to vanquish.", "visual_mnemonic_story_en": "Muscular vitality (月) surging forth with explosive power to conquer challenges (胜).", "visual_mnemonic_story_es": "La pujanza física (月) emergiendo con vigor invicto para superar al oponente (胜).", "tone_mnemonic_anchor": "51", "cangjie": "BFQ", "traditional": "勝"}, {"character": "利", "pinyin": "lì", "meaning_en": "sharp; benefit; profit; favorable", "meaning_es": "afilado; beneficio; provecho; favorable", "radical": "刂", "radical_meaning_en": "knife / blade", "meaning_component": "禾 (ripe grain crop) + 刂 (reaping sickle blade)", "sound_component": "利 (lì)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "A sharp sickle 刂 harvesting golden ripe grain stalks 禾 with swift ease; signifies reaping benefits and success.", "visual_mnemonic_story_en": "A sharp blade (刂) smoothly cutting golden grain stalks (禾) to reap a bountiful harvest (利).", "visual_mnemonic_story_es": "Una hoz afilada (刂) segando espigas doradas (禾) para recoger una cosecha provechosa (利).", "tone_mnemonic_anchor": "51", "cangjie": "HDN", "traditional": "利"}], "extended_reading_passages": [{"id": "#1", "hanzi": "长平之战的胜利，使秦国彻底摧毁了东方六国中军事实力最强的赵国主力。秦军主帅白起以高超的诱敌与穿插包围战术载入史册。这场巨大的军事胜利，为后来秦始皇吞并六国、一统华夏奠定了坚实的战略基础。", "pinyin": "Chángpíng zhī zhàn de shènglì, shǐ Qínguó chèdǐ cuīhuǐ le dōngfāng liùguó zhōng jūnshì shílì zuì qiáng de Zhàoguó zhǔlì. Qínjūn zhǔshuài Bái Qǐ yǐ gāochāo de yòudí yǔ chuānchā-bāowéi zhànshù zǎirù shǐcè. Zhè chǎng jùdà de jūnshì shènglì, wèi hòulái Qín Shǐhuáng tūnbìng liùguó, yītǒng Huáxià diàndìng le jiānshí de zhànlüè jīchǔ.", "en": "Victory at Changping allowed Qin to crush the elite army of Zhao, the strongest among the six states. General Bai Qi's brilliant tactics entered history. This monumental victory laid the strategic foundation for Qin Shihuang's unification of China.", "es": "La victoria en Changping permitió a Qin aniquilar al ejército de Zhao, el rival más formidable de los reinos orientales. Las maniobras de Bai Qi pasaron a la historia, sentando las bases estratégicas para la unificación de China."}, {"id": "#2", "hanzi": "在漫长曲折的人生征程中，真正的胜利从来不是唾手可得的偶然幸运，而是无数个日夜默默耕耘、百折不挠的必然奖赏。在挫折面前永不放弃、在逆境中越战越勇的人，最终必将迎来属于自己的辉煌胜利。", "pinyin": "Zài màncháng-qūzhé de rénshēng zhēngchéng zhōng, zhēnzhèng de shènglì cónglái bùshì tuòshǒu-kědé de ǒurán xìngyùn, ér shì wúshù gè rìyè mòmò gēngyún, bǎizhé-bùnáo de bìrán jiǎngshǎng. Zài cuòzhé miànqián yǒng bù fàngqì, zài nìjìng zhōng yuè zhàn yuè yǒng de rén, zuìzhōng bìjiāng yínglái shǔyú zìjǐ de huīhuáng shènglì.", "en": "On life's winding journey, authentic victory is never a windfall of luck, but the inevitable reward for quiet dedication and unyielding resilience. Those who refuse to surrender before adversity will embrace their glorious triumph in the end.", "es": "En la travesía de la vida, el triunfo auténtico no es fruto del azar, sino el premio al tesón callado y a la entereza indomable. Quien no ceja ante los reveses y se crece en el infortunio alcanza tarde o temprano su propia victoria."}]}, {"meanings_summary": {"en": "to mobilize; transfer; reassign; maneuver; arouse", "es": "movilizar; trasladar; reasignar; maniobrar; incentivar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Issuing verbal directives (调) to set resources and troops into motion (动) means to mobilize and redeploy (调动).", "composite_memory_hook_es": "Impartir mandatos administrativos (调) para poner recursos en movimiento (动) define la movilización y traslado (调动).", "cultural_and_cognitive_roots": "Derived from imperial tally systems (虎符) where generals redeployed garrisons with royal bronze seals.", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'diào dòng' (51-51). Pronounce both syllables with brisk, administrative firmness."}, "semantic_boundary_contrasts": {"core_nuance": "调动 highlights deliberate reallocation of personnel, troops, or psychological motivation.", "contrasts": [{"id": "1", "compared_word": "调动 vs. 移动", "pinyin": "yídòng", "analysis": "移动 refers to physical shifting in spatial location (move chairs/furniture), while 调动 is administrative reassignment or strategic maneuvering."}, {"id": "2", "compared_word": "调动 vs. 派遣", "pinyin": "pàiqiǎn", "analysis": "派遣 means sending someone out on an assignment, while 调动 implies shifting or reassigning posts."}, {"id": "3", "compared_word": "调动 vs. 固定", "pinyin": "gùdìng", "analysis": "固定 is the direct antonym meaning firmly fixed and unchanging."}]}, "traps_and_cognates": {"look_alikes": [{"character": "词", "pinyin": "cí", "meaning_en": "word; lyrics", "distinction_note": "Department 司 on right of 讠 instead of 周"}, {"character": "诵", "pinyin": "sòng", "meaning_en": "recite; chant", "distinction_note": "Yong 甬 on right of 讠 instead of 周"}, {"character": "功", "pinyin": "gōng", "meaning_en": "merit; skill", "distinction_note": "Work 工 on left of 力 instead of 云"}, {"character": "劫", "pinyin": "jié", "meaning_en": "plunder", "distinction_note": "Go 去 on left of 力 instead of 云"}], "etymological_cognates": [{"character": "调度", "pinyin": "diàodù", "gloss_en": "dispatch; control traffic"}, {"character": "调换", "pinyin": "diàohuàn", "gloss_en": "exchange; swap"}, {"character": "动向", "pinyin": "dòngxiàng", "gloss_en": "trend; movement"}, {"character": "发动", "pinyin": "fādòng", "gloss_en": "launch; mobilize"}]}, "id": "22", "hanzi": "调动", "pinyin": "diào dòng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to redeploy or transfer military forces, personnel, or material resources; to arouse enthusiasm", "definition_es": "trasladar o reasignar tropas, personal o recursos; activar la motivación o iniciativa", "example_phrase": "调动工作岗位 (transfer to a new job post)"}], "example_sentences": [{"id": "#1", "hanzi": "秦军统帅白起精通兵法，善于调动敌军，通过假装溃败巧妙诱使赵括脱离险要阵地。", "pinyin": "Qínjūn tǒngshuài Bái Qǐ jīngtōng bīngfǎ, shànyú diàodòng dírén, tōngguò jiǎzhuāng kuìbài qiǎomiào yòushǐ Zhào Kuò tuōlí xiǎnyào zhèndì.", "en": "Qin General Bai Qi mastered strategy and excelled at maneuvering enemy forces, faking a rout to lure Zhao Kuo out of his bastions.", "es": "El general Bai Qi dominaba el arte bélico y sabía mover al enemigo, simulando una desbandada para sacar a Zhao Kuo de sus posiciones."}, {"id": "#2", "hanzi": "优秀的领导者善于建立科学合理的激励机制，充分调动全体员工的工作积极性与创造潜能。", "pinyin": "Yōuxiù de lǐngdǎozhě shànyú jiànlì kēxué hélǐ de jīlì jīzhì, chōngfèn diàodòng quántǐ yuángōng de gōngzuò jījíxìng yǔ chuàngzào qiánnéng.", "en": "Outstanding leaders excel at instituting incentive systems to fully mobilize staff enthusiasm and creative potential.", "es": "Los líderes sobresalientes saben articular incentivos justos para movilizar la motivación y el potencial creador del personal."}], "collocations": [{"hanzi": "调动兵力", "en": "redeploy / maneuver troops"}, {"hanzi": "调动积极性", "en": "arouse / mobilize enthusiasm"}, {"hanzi": "工作调动", "en": "job transfer / reassignment"}, {"hanzi": "调动资源", "en": "mobilize resources"}, {"hanzi": "紧急调动", "en": "emergency redeployment"}, {"hanzi": "调动作战部队", "en": "maneuver combat units"}], "idioms": [{"hanzi": "兵贵神速", "pinyin": "bīng guì shén sù", "meaning_en": "speed is precious in warfare; lightning troop movements"}, {"hanzi": "调兵遣将", "pinyin": "diào bīng qiǎn jiàng", "meaning_en": "deploy troops and dispatch generals; marshal forces"}, {"hanzi": "指东打西", "pinyin": "zhǐ dōng dǎ xī", "meaning_en": "point to the east while attacking the west; feint maneuver"}, {"hanzi": "声东击西", "pinyin": "shēng dōng jī xī", "meaning_en": "make a sound in the east and strike in the west"}], "character_decomposition": [{"character": "调", "pinyin": "diào", "meaning_en": "transfer; shift; tune; tone; investigate", "meaning_es": "trasladar; cambiar; tono; melodía; investigar", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (spoken command) + 周 (complete cycle / universal circulation)", "sound_component": "周 (zhōu)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Spoken administrative directives 讠 circulating troops and personnel around 周 the realm; to transfer.", "visual_mnemonic_story_en": "Words of administrative command (讠) circulating personnel across districts in a smooth cycle (周) to reassign them (调).", "visual_mnemonic_story_es": "Órdenes oficiales orales (讠) que trasladan tropas a través de las comarcas en un circuito ordenado (周) para reasignarlas (调).", "tone_mnemonic_anchor": "51", "cangjie": "IVBGR", "traditional": "調"}, {"character": "动", "pinyin": "dòng", "meaning_en": "move; act; stir; motion", "meaning_es": "mover; actuar; movimiento; impulso", "radical": "力", "radical_meaning_en": "strength / power", "meaning_component": "云 (clouds swirling across sky) + 力 (physical strength)", "sound_component": "云 (yún)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Applying physical force 力 to induce dynamic motion like drifting clouds 云.", "visual_mnemonic_story_en": "Applying strength (力) to shift heavy objects like dynamic clouds (动).", "visual_mnemonic_story_es": "Aplicar la fuerza (力) para mover objetos pesados con soltura de nubes (动).", "tone_mnemonic_anchor": "51", "cangjie": "MIS", "traditional": "動"}], "extended_reading_passages": [{"id": "#1", "hanzi": "善于用兵的统帅，精髓在于“能调动敌人而不被敌人调动”。长平之战中，秦军统帅白起指挥若定，通过诈败后撤与穿插突袭，把四十万赵军一步步调动进预先设好的包围圈，将调动敌军的战术艺术演绎到了极致。", "pinyin": "Shànyú yòngbīng de tǒngshuài, jīngsuǐ zàiyú 'néng diàodòng dírén ér bù bèi dírén diàodòng'. Chángpíng zhī zhàn zhōng, Qínjūn tǒngshuài Bái Qǐ zhǐhuī-ruòdìng, tōngguò zhàbài hòuchè yǔ chuānchā tūxí, bǎ sìshí wàn Zhàojūn yībù-yībù diàodòng jìn yùxiān shè hǎo de bāowéiquān, jiāng diàodòng díjūn de zhànshù yìshù yǎnyì dào le jízhì.", "en": "The essence of generalship is moving the enemy without being moved. At Changping, General Bai Qi feigned retreat, maneuvering 400,000 Zhao troops step by step into a prearranged trap, demonstrating the supreme art of tactical redeployment.", "es": "La cumbre del arte militar reside en mover al enemigo sin dejarse mover por él. En Changping, Bai Qi fingió retiradas tácticas, atrayendo a 400.000 soldados de Zhao hacia la celada y elevando la maniobra militar a la maestría suprema."}, {"id": "#2", "hanzi": "在现代社会治理与危机应对中，高效调动各方资源是战胜突发灾害的重要保证。无论是调动精锐医疗专家奔赴抗疫一线，还是跨区域调动应急救灾物资，强大的综合调度与动员能力，生动展现了国家治理体系的高效运作。", "pinyin": "Zài xiàndài shèhuì zhìlǐ yǔ wēijī yìngduì zhōng, gāoxiào diàodòng gèfāng zīyuán shì zhànshèng tūfā zāihài de zhòngyào bǎozhèng. Wúlùn shì diàodòng jīngruì yīliáo zhuānjiā bēnfù kàngyì yīxiàn, háishì kuà qūyù diàodòng yìngjí jiùzāi wùzī, qiángdà de zōnghé diàodù yǔ dòngyuán nénglì, shēngdòng zhǎnxiàn le guójiā zhìlǐ tǐxì de gāoxiào yùnzuò.", "en": "In modern crisis management, efficiently mobilizing resources guarantees victory over disaster. Whether redeploying medical experts to the frontline or coordinating disaster relief across provinces, mobilization capacity reflects good governance.", "es": "En la gestión moderna de catástrofes, movilizar recursos con presteza es la garantía del éxito. Ya sea trasladando médicos a la vanguardia o canalizando suministros de auxilio, la capacidad logística refleja la solidez del Estado."}]}, {"meanings_summary": {"en": "to spread; disseminate; diffuse; scatter", "es": "difundir; esparcir; diseminar; propagar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Scattering outward in fragments (散) and spreading wide like a roll of cloth (布) means to disseminate (散布).", "composite_memory_hook_es": "Dispersar en fragmentos (散) y extender a lo ancho como un paño de tela (布) conforma la difusión (散布).", "cultural_and_cognitive_roots": "Associated with psychological warfare (反间计) in classical statecraft where false rumors were circulated into rival courts.", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'sàn bù' (51-51). Articulate both syllables with decisive downward force."}, "semantic_boundary_contrasts": {"core_nuance": "散布 carries a negative or covert connotation when applied to rumors, panic, or false stories.", "contrasts": [{"id": "1", "compared_word": "散布 vs. 传播", "pinyin": "chuánbō", "analysis": "传播 is a neutral or positive term for spreading knowledge or culture, while 散布 often targets rumors or toxic ideas."}, {"id": "2", "compared_word": "散布 vs. 辟谣", "pinyin": "pìyáo", "analysis": "辟谣 is the direct antonym meaning to debunk and refute false rumors."}, {"id": "3", "compared_word": "散布 vs. 搜集", "pinyin": "sōují", "analysis": "搜集 means gathering and collecting materials in one place, opposite to scattering outward 散布."}]}, "traps_and_cognates": {"look_alikes": [{"character": "敦", "pinyin": "dūn", "meaning_en": "honest; sincere", "distinction_note": "Xiang 享 on left instead of 𣏟"}, {"character": "敬", "pinyin": "jìng", "meaning_en": "respect", "distinction_note": "Gou 苟 on left of 攵 instead of 𣏟"}, {"character": "希", "pinyin": "xī", "meaning_en": "hope; rare", "distinction_note": "Contains 爻/乂-like strokes on top of 巾"}, {"character": "市", "pinyin": "shì", "meaning_en": "city; market", "distinction_note": "Dot and horizontal bar over 巾 instead of 𠂇"}], "etymological_cognates": [{"character": "散发", "pinyin": "sànfā", "gloss_en": "distribute; emit"}, {"character": "分散", "pinyin": "fēnsàn", "gloss_en": "disperse; scatter"}, {"character": "公布", "pinyin": "gōngbù", "gloss_en": "promulgate; announce"}, {"character": "分布", "pinyin": "fēnbù", "gloss_en": "distribute; spread over"}]}, "id": "23", "hanzi": "散布", "pinyin": "sàn bù", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to spread rumors, information, or opinions widely; to scatter objects across a surface", "definition_es": "propagar o difundir rumores, noticias o doctrinas en diversas direcciones; diseminar", "example_phrase": "散布谣言 (spread rumors)"}], "example_sentences": [{"id": "#1", "hanzi": "秦相范雎派间谍潜入邯郸，四处散布“秦军只怕赵奢之子赵括”的谣言，企图实施反间计。", "pinyin": "Qínxiàng Fàn Jū pài jiàndié qiánrù Hándān, sìchù sànbù 'Qínjūn zhǐ pà Zhào Shē zhī zǐ Zhào Kuò' de yáoyán, qǐtú shíshī fǎnjiànjì.", "en": "Qin's minister sent spies into Handan to spread rumors that 'Qin feared only Zhao Kuo,' aiming to carry out counter-espionage.", "es": "El canciller de Qin infiltró espías en Handan para propagar rumores de que Qin solo temía a Zhao Kuo, urdiendo un ardid de contraespionaje."}, {"id": "#2", "hanzi": "在现代互联网公共空间中，任何网民都应当自觉抵制并拒绝散布未经证实的虚假消息。", "pinyin": "Zài xiàndài hùliánwǎng gōnggòng kōngjiān zhōng, rènhé wǎngmín dōu yīngdāng zìjué dǐzhì bìng jùjué sànbù wèijīng zhèngshí de xūjiǎ xiāoxi.", "en": "In modern internet cyberspace, every netizen should consciously resist and refuse to disseminate unverified false information.", "es": "En el ciberespacio actual, los internautas deben abstenerse conscientemente de difundir informaciones falsas no corroboradas."}], "collocations": [{"hanzi": "散布谣言", "en": "spread rumors / hearsay"}, {"hanzi": "散布虚假信息", "en": "disseminate false information"}, {"hanzi": "四处散布", "en": "disseminate everywhere"}, {"hanzi": "散布言论", "en": "spread statements / opinions"}, {"hanzi": "散布种子", "en": "scatter seeds (literal)"}, {"hanzi": "散布恐惧", "en": "spread fear and panic"}], "idioms": [{"hanzi": "造谣生事", "pinyin": "zào yáo shēng shì", "meaning_en": "concoct rumors and stir up trouble"}, {"hanzi": "风言风语", "pinyin": "fēng yán fēng yǔ", "meaning_en": "groundless talk and malicious slander in the wind"}, {"hanzi": "满城风雨", "pinyin": "mǎn chéng fēng yǔ", "meaning_en": "the whole town is rife with gossip and rumors"}, {"hanzi": "防民之口，甚于防川", "pinyin": "fáng mín zhī kǒu, shèn yú fáng chuān", "meaning_en": "stopping people's mouths is more dangerous than stopping a river"}], "character_decomposition": [{"character": "散", "pinyin": "sàn", "meaning_en": "scatter; disperse; spread; break up", "meaning_es": "dispersar; esparcir; desbandar; difundir", "radical": "攵", "radical_meaning_en": "tap / strike", "meaning_component": "𢽳/𣏟 (hemp fibers beaten out) + 攵 (striking stick)", "sound_component": "散 (sàn)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Beating bundles of hemp with a stick 攵 so the fibers separate and scatter widely 散.", "visual_mnemonic_story_en": "Beating flax fibers with a rod (攵) so they disperse and scatter in all directions (散).", "visual_mnemonic_story_es": "Golpear gavillas con una vara (攵) para que las fibras se dispersen en todas direcciones (散).", "tone_mnemonic_anchor": "51", "cangjie": "TBOK", "traditional": "散"}, {"character": "布", "pinyin": "bù", "meaning_en": "cloth; spread; declare; deploy", "meaning_es": "tela; paño; difundir; desplegar; proclamar", "radical": "巾", "radical_meaning_en": "cloth / fabric", "meaning_component": "巾 (woven cloth) + 𠂇 (hand spreading it out)", "sound_component": "布 (bù)", "stroke_count": "5", "composition_type": "半包围结构", "etymology_and_mnemonic": "A hand spreading out a woven bolt of cloth 巾 across the counter; signifies diffusing and publishing.", "visual_mnemonic_story_en": "Unrolling and spreading a long bolt of cloth (巾) across a broad table (布).", "visual_mnemonic_story_es": "Desenrollar y extender un lienzo de tela (巾) con la mano sobre la mesa (布).", "tone_mnemonic_anchor": "51", "cangjie": "KLB", "traditional": "布"}], "extended_reading_passages": [{"id": "#1", "hanzi": "秦国名臣范雎深知正面强攻赵国壁垒难以奏效，便以千金巨资派细作潜入赵国都城邯郸，秘密散布流言，称“秦国独畏赵奢之子赵括为将，廉颇老矣不堪一击”。赵王听信了这番散布的谣言，果然中计换将。", "pinyin": "Qínguó míngchén Fàn Jū shēnzhī zhèngmiàn qiánggōng Zhàoguó bìlěi nányǐ zòuxiào, biàn yǐ qiānjīn jùzī pài xìzuò qiánrù Zhàoguó dūchéng Hándān, mìmì sànbù liúyán, chēng 'Qínguó dú wèi Zhào Shē zhī zǐ Zhào Kuò wéi jiàng, Lián Pō lǎo yǐ bùkān-yījī'. Zhàowáng tīngxìn le zhè fān sànbù de yáoyán, guǒrán zhòngjì huànjiàng.", "en": "Knowing storming Zhao's bastions would fail, Qin's minister Fan Ju sent spies into Handan with bribes to spread rumors: 'Qin fears only Zhao Kuo; Lian Po is old and weak.' Duped by the rumors, King Zhao replaced his general.", "es": "Sabiendo que asaltar las murallas de Zhao costaría caro, Fan Ju infiltró espías en Handan para difundir bulos: 'Qin solo teme a Zhao Kuo; Lian Po está viejo y acabado.' Engañado por los rumores, el rey de Zhao relevó al general."}, {"id": "#2", "hanzi": "在当今信息爆炸的网络时代，虚假信息与恶意谣言的散布速度之快、影响之广前所未有。广大公众应当提高自身的信息鉴别能力，不盲从、不偏信，做到“谣言止于智者”，共同维护清朗健康的网络舆论生态环境。", "pinyin": "Zài dāngjīn xìnxī-bàozhà de wǎngluò shídài, xūjiǎ xìnxī yǔ èyì yáoyán de sànbù sùdù zhī kuài, yǐngxiǎng zhī guǎng qiánsuǒwèiyǒu. Guǎngdà gōngzhòng yīngdāng tígāo zìshēn de xìnxī jiànbié nénglì, bù mángcóng, bù piānxìn, zuòdào 'yáoyán zhǐ yú zhìzhě', gòngtóng wéihù qīnglǎng jiànkāng de wǎngluò yúlùn shēngtài huánjìng.", "en": "In today's digital era, false information and malicious rumors spread at unprecedented speeds. The public must sharpen critical thinking to avoid gullibility; as the proverb goes, 'rumors stop with the wise,' safeguarding a healthy cyberspace.", "es": "En la era digital, la difusión de bulos y noticias falsas se propaga con rapidez insólita. La ciudadanía debe aguzar su juicio crítico para no caer en patrañas; como reza el refrán, 'el rumor cesa ante el sabio', protegiendo el entorno público."}]}, {"meanings_summary": {"en": "rumor; unfounded story; gossip; falsehood", "es": "rumor; bulo; patraña; falsedad infundada"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Fabricated street ballads (谣) uttered as spoken words (言) constitute unfounded rumors (谣言).", "composite_memory_hook_es": "Coplas anónimas de callejuela (谣) formuladas en lenguaje hablado (言) conforman el bulo o rumor (谣言).", "cultural_and_cognitive_roots": "Derived from classical street ballads (童谣) that carried political prophecies or weaponized counter-intelligence.", "tone_sandhi_and_pitch_modulation": "Double second tone: 'yáo yán' (35-35). Rise cleanly on both syllables with steady cadence."}, "semantic_boundary_contrasts": {"core_nuance": "谣言 specifically designates unfounded, fabricated, and maliciously circulated falsehoods.", "contrasts": [{"id": "1", "compared_word": "谣言 vs. 真相", "pinyin": "zhēnxiàng", "analysis": "真相 is the direct antonym meaning objective facts and verified truth."}, {"id": "2", "compared_word": "谣言 vs. 谎言", "pinyin": "huǎngyán", "analysis": "谎言 is a deliberate lie told by an individual, while 谣言 is an unverified story circulating across an entire community."}, {"id": "3", "compared_word": "谣言 vs. 传言", "pinyin": "chuányán", "analysis": "传言 is a neutral term for circulating hearsay, whereas 谣言 strongly implies malicious fabrication."}]}, "traps_and_cognates": {"look_alikes": [{"character": "摇", "pinyin": "yáo", "meaning_en": "shake; rock", "distinction_note": "Hand radical 扌 on left instead of 讠"}, {"character": "遥", "pinyin": "yáo", "meaning_en": "distant; remote", "distinction_note": "Movement 辶 around 䍃 instead of 讠"}, {"character": "信", "pinyin": "xìn", "meaning_en": "letter; believe", "distinction_note": "Person 亻 on left of 言"}, {"character": "誓", "pinyin": "shì", "meaning_en": "swear; vow", "distinction_note": "Fold 折 on top of 言"}], "etymological_cognates": [{"character": "歌谣", "pinyin": "gēyáo", "gloss_en": "ballad; folk song"}, {"character": "民谣", "pinyin": "mínyáo", "gloss_en": "folk ballad"}, {"character": "言语", "pinyin": "yányǔ", "gloss_en": "speech; spoken words"}, {"character": "言论", "pinyin": "yánlùn", "gloss_en": "discourse; speech"}]}, "id": "24", "hanzi": "谣言", "pinyin": "yáo yán", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a fabricated, unverified, or groundless statement or report circulating among people without factual basis", "definition_es": "noticia falsa, invención o testimonio carente de base real que se propaga entre el público", "example_phrase": "制造谣言 (fabricate rumors)"}], "example_sentences": [{"id": "#1", "hanzi": "赵王缺乏政治鉴别力，轻信了秦国散布的虚假谣言，错误地罢免了前线坚守的老将廉颇。", "pinyin": "Zhàowáng quēfá zhèngzhì jiànbiélì, qīngxìn le Qínguó sànbù de xūjiǎ yáoyán, cuòwù de bàmǐan le qiánxiàn jiānshǒu de lǎojiàng Lián Pō.", "en": "Lacking political discernment, King Zhao gullibly believed the false rumors spread by Qin, mistakenly dismissing General Lian Po from the front.", "es": "Carente de lucidez política, el rey de Zhao creyó los falsos bulos difundidos por Qin y destituyó erróneamente al veterano Lian Po del frente."}, {"id": "#2", "hanzi": "公安网监部门及时发布权威通报澄清事实，迅速平息了在社交网络上引发恐慌的网络谣言。", "pinyin": "Gōng'ān wǎngjiān bùmén jíshí fābù quánwēi tōngbào chéngqīng shìshí, xùnsù píngxī le zài shèjiāo wǎngluò shang yǐnfā kǒnghuāng de wǎngluò yáoyán.", "en": "Cyber police promptly issued an authoritative bulletin clarifying the facts, swiftly quelling online rumors that had triggered public panic.", "es": "La policía cibernética emitió una nota oficial aclarando los hechos y disipando el pánico causado por bulos en redes sociales."}], "collocations": [{"hanzi": "制造谣言", "en": "fabricate / concoct rumors"}, {"hanzi": "散布谣言", "en": "spread rumors"}, {"hanzi": "谣言止于智者", "en": "rumors stop with the wise"}, {"hanzi": "辟谣澄清", "en": "refute rumors and clarify"}, {"hanzi": "网络谣言", "en": "internet rumors / disinformation"}, {"hanzi": "恶毒谣言", "en": "malicious / venomous rumors"}], "idioms": [{"hanzi": "造谣生事", "pinyin": "zào yáo shēng shì", "meaning_en": "concoct rumors to stir up trouble"}, {"hanzi": "满城风雨", "pinyin": "mǎn chéng fēng yǔ", "meaning_en": "the whole town is rife with gossip and talk"}, {"hanzi": "三人成虎", "pinyin": "sān rén chéng hǔ", "meaning_en": "three people repeating a lie make a tiger; falsehood repeated sounds true"}, {"hanzi": "杯弓蛇影", "pinyin": "bēi gōng shé yǐng", "meaning_en": "mistake the reflection of a bow for a snake; illusory panic"}], "character_decomposition": [{"character": "谣", "pinyin": "yáo", "meaning_en": "ballad; folk rhyme; rumor; fabricate", "meaning_es": "balada; copla popular; rumor; bulo", "radical": "讠", "radical_meaning_en": "speech", "meaning_component": "讠 (spoken speech) + 䍃 (earthenware jar / floating ballad)", "sound_component": "䍃 (yáo)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Spoken street verses 讠 sung without instrumental accompaniment like jars 䍃; evolved into circulating hearsay.", "visual_mnemonic_story_en": "Words of speech (讠) drifting through streets like singing ballads, mutating into unverified hearsay (谣).", "visual_mnemonic_story_es": "Palabras orales (讠) que vuelan por las calles como coplas anónimas mutando en habladurías (谣).", "tone_mnemonic_anchor": "35", "cangjie": "IVBOU", "traditional": "謠"}, {"character": "言", "pinyin": "yán", "meaning_en": "words; speech; talk; say", "meaning_es": "palabra; lenguaje; hablar; discurso", "radical": "言", "radical_meaning_en": "speech", "meaning_component": "tongue emitting breath strokes 口 from mouth", "sound_component": "言 (yán)", "stroke_count": "7", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient pictograph of sound strokes radiating upward from an open human mouth 口; signifies speech.", "visual_mnemonic_story_en": "Articulate sound waves radiating upward from an open mouth (口) as spoken words (言).", "visual_mnemonic_story_es": "Ondas sonoras que brotan de la boca abierta (口) articulando palabras humanas (言).", "tone_mnemonic_anchor": "35", "cangjie": "YMR", "traditional": "言"}], "extended_reading_passages": [{"id": "#1", "hanzi": "“三人成虎，积羽沉舟。”春秋战国时期的谋士们最擅长利用谣言实施心理战。秦国仅用数千金在邯郸散布谣言，便让多疑的赵王自毁长城，换下身经百战的廉颇。这表明心智不坚者面对谣言极易丧失理智判断。", "pinyin": "'Sān rén chéng hǔ, jī yǔ chén zhōu.' Chūnqiū-Zhànguó shíqī de móushì men zuì shàncháng lìyòng yáoyán shíshī xīnlǐzhàn. Qínguó jǐn yòng shù qiān jīn zài Hándān sànbù yáoyán, biàn ràng duōyí de Zhàowáng zìhuǐ-chángchéng, huàn xià shēnjīng-bǎizhàn de Lián Pō. Zhè biǎomíng xīnji bù jiān zhě miànduì yáoyán jí yì sàngshī lǐzhì pànduàn.", "en": "'Three men make a tiger; piled feathers sink a ship.' Sages excelled at weaponizing rumors in psychological warfare. A few thousand pieces of gold spreading rumors in Handan tricked King Zhao into firing Lian Po, destroying his realm.", "es": "'Tres voces inventan un tigre; plumas amontonadas hunden un bajel.' Los estrategas antiguos dominaban la guerra psicológica con bulos. Con poco oro esparcido en Handan, Qin empujó al monarca de Zhao a relevar al curtido Lian Po."}, {"id": "#2", "hanzi": "古人云：“谣言止于智者。”在信息传播极为迅捷的今天，面对网络上真伪难辨的各种传言，保持清醒的理性头脑尤为珍贵。不信谣、不传谣，主动探寻权威证据，才是每一个具有独立思考能力的公民应当具备的素养。", "pinyin": "Gǔrén yún: 'Yáoyán zhǐ yú zhìzhě.' Zài xìnxī chuánbō jíwéi xùnjié de jīntiān, miànduì wǎngluò shang zhēnwěi-nánbiàn de gè zhǒng chuányán, bǎochí qīngxǐng de lǐxìng tóunǎo yóuwéi zhēnguì. Bù xìnyáo, bù chuányáo, zhǔdòng tànxún quánwēi zhèngjù, cái shì měi yī gè jùyǒu dúlì sīkǎo nénglì de gōngmín yīngdāng jùbèi de sùyǎng.", "en": "As ancients said: 'Rumors stop with the wise.' Today, facing hard-to-verify gossip on networks, maintaining a cool, rational mind is precious. Refusing to believe or spread rumors and seeking authority reflects critical citizenship.", "es": "Como sentenciaron los clásicos: 'El rumor cesa ante el sabio.' En la sociedad digital, preservar la cabeza fría ante noticias confusas es virtud suprema. Rechazar bulos y buscar fuentes fidedignas es el sello del ciudadano libre."}]}, {"meanings_summary": {"en": "to be fooled; be taken in; fall into a trap; be duped", "es": "dejarse engañar; caer en la trampa; ser estafado; ser burlado"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Walking into (上) the sharp valuation trap of a greedy pawnshop (当) gave rise to being fooled (上当).", "composite_memory_hook_es": "Entrar (上) en el engaño de tasación de una casa de empeño (当) dio origen al modismo caer en la trampa (上当).", "cultural_and_cognitive_roots": "Originates from late imperial Beijing pawnshops ('当铺') where appraisers systematically undervalued valuables, leaving patrons swindled ('上当').", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'shàng dàng' (51-51). Pronounce both syllables with firm, emphatic downward cadence."}, "semantic_boundary_contrasts": {"core_nuance": "上当 is an informal, widely used verb describing falling prey to someone else's deceptive scheme or trap.", "contrasts": [{"id": "1", "compared_word": "上当 vs. 识破", "pinyin": "shípò", "analysis": "识破 is the direct antonym meaning to see through a trick or unmask a deception."}, {"id": "2", "compared_word": "上当 vs. 认输", "pinyin": "rènshū", "analysis": "认输 means conceding defeat voluntarily, while 上当 means being tricked into loss."}, {"id": "3", "compared_word": "上当 vs. 迷失", "pinyin": "míshī", "analysis": "迷失 means losing one's way physically or morally, unlike being actively conned (上当)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "下", "pinyin": "xià", "meaning_en": "down; below", "distinction_note": "Indicator stroke points downward"}, {"character": "肖", "pinyin": "xiào", "meaning_en": "resemble; small", "distinction_note": "Flesh radical 月 at bottom instead of 彐"}, {"character": "党", "pinyin": "dǎng", "meaning_en": "party; faction", "distinction_note": "Legs radical 儿 at bottom instead of 彐"}, {"character": "常", "pinyin": "cháng", "meaning_en": "constant; normal", "distinction_note": "Towel radical 巾 at bottom instead of 彐"}], "etymological_cognates": [{"character": "当铺", "pinyin": "dàngpù", "gloss_en": "pawnshop"}, {"character": "受骗", "pinyin": "shòupiàn", "gloss_en": "be swindled / cheated"}, {"character": "中计", "pinyin": "zhòngjì", "gloss_en": "fall into a trap / stratagem"}, {"character": "不上当", "pinyin": "bù shàngdàng", "gloss_en": "not fall for it"}]}, "id": "25", "hanzi": "上当", "pinyin": "shàng dàng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to be deceived, tricked, or taken in by deceptive words, fraudulent schemes, or ambushes", "definition_es": "ser víctima de engaño, trampa o fraude; dejarse embaucar por argucias", "example_phrase": "上当受骗 (be fooled and swindled)"}], "example_sentences": [{"id": "#1", "hanzi": "赵王轻信了秦国间谍散布的谣言，果然中计上当，执意派缺乏实战经验的赵括前去替换廉颇。", "pinyin": "Zhàowáng qīngxìn le Qínguó jiàndié sànbù de yáoyán, guǒrán zhòngjì shàngdàng, zhíyì pài quēfá shízhàn jīngyàn de Zhào Kuò qiánqù tìhuàn Lián Pō.", "en": "King Zhao believed rumors spread by Qin spies and was taken in by the trap, sending inexperienced Zhao Kuo to replace Lian Po.", "es": "El rey de Zhao creyó los infundios de los espías de Qin y cayó en la trampa, relevando a Lian Po por el inexperto Zhao Kuo."}, {"id": "#2", "hanzi": "社区民警深入居民小区开展反诈宣传，提醒老年人提高警惕，切莫轻信高额回报而上当受骗。", "pinyin": "Shèqū mínjǐng shēnrù jūmín xiǎoqū kāizhǎn fǎnzà xuānchuán, tíxǐng lǎoniánrén tígāo jǐngtì, qiè mò qīngxìn gāo'é huíbào ér shàngdàng-shòupiàn.", "en": "Community police conducted anti-fraud campaigns in neighborhoods, reminding seniors to stay vigilant and avoid being duped by high-yield scams.", "es": "La policía de barrio impartió charlas antifraude, advirtiendo a los ancianos que no caigan en timos que prometen ganancias fáciles."}], "collocations": [{"hanzi": "上当受骗", "en": "be duped and swindled"}, {"hanzi": "容易上当", "en": "easily taken in / gullible"}, {"hanzi": "谨防上当", "en": "guard against being deceived"}, {"hanzi": "绝不上当", "en": "never be fooled"}, {"hanzi": "上了一次当", "en": "got fooled once"}, {"hanzi": "上当的滋味", "en": "the bitter taste of being tricked"}], "idioms": [{"hanzi": "受骗上当", "pinyin": "shòu piàn shàng dàng", "meaning_en": "be deceived and taken in by trickery"}, {"hanzi": "吃一堑，长一智", "pinyin": "chī yī qiàn, zhǎng yī zhì", "meaning_en": "a fall into the pit, a gain in your wit; learn from blunders"}, {"hanzi": "自投罗网", "pinyin": "zì tóu luó wǎng", "meaning_en": "hurl oneself into the net; walk blindly into traps"}, {"hanzi": "引颈受戮", "pinyin": "yǐn jǐng shòu lù", "meaning_en": "stick out one's neck to receive the axe; submit passively to slaughter"}], "character_decomposition": [{"character": "上", "pinyin": "shàng", "meaning_en": "ascend; go up; enter; on", "meaning_es": "subir; entrar; sobre; arriba", "radical": "一", "radical_meaning_en": "one / baseline", "meaning_component": "horizontal baseline 一 with an indicator stroke pointing above", "sound_component": "上 (shàng)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Indicator glyph showing an element standing above a baseline; here meaning stepping into a trap.", "visual_mnemonic_story_en": "Stepping upward (上) blindly into a snare.", "visual_mnemonic_story_es": "Dar un paso hacia arriba (上) cayendo inadvertidamente en el lazo.", "tone_mnemonic_anchor": "51", "cangjie": "YMY", "traditional": "上"}, {"character": "当", "pinyin": "dàng", "meaning_en": "pawnshop; pawn ticket; match; fitting", "meaning_es": "casa de empeño; boleta; encajar; adecuado", "radical": "⺌", "radical_meaning_en": "small", "meaning_component": "尚/⺌ (value / worth) + 彐/田 (pawn collateral ledger)", "sound_component": "尚 (shàng / dàng)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Entering a pawnshop 当 to pledge property; customers often fell victim to sharp valuation swindles (上当).", "visual_mnemonic_story_en": "Pawning heirlooms at a pawnshop (当) only to realize one has been shortchanged.", "visual_mnemonic_story_es": "Empeñar un objeto en el monte de piedad (当) dándose cuenta de la tasación engañosa.", "tone_mnemonic_anchor": "51", "cangjie": "FNS", "traditional": "當"}], "extended_reading_passages": [{"id": "#1", "hanzi": "战国历史上赵王因上当而导致长平惨败的教训极其深刻。秦国运用反间计散布谣言，赵王不仅未能明察秋毫，反而屡次上当，将百战老将廉颇撤换。这一致命决策使四十万将士身首异处，警示后人兼听则明、偏信则暗。", "pinyin": "Zhànguó lìshǐ shang Zhàowáng yīn shàngdàng ér dǎozhì Chángpíng cǎibài de jiàoxun jíqí shēnkè. Qínguó yùnyòng fǎnjiànjì sànbù yáoyán, Zhàowáng bùjǐn wèinéng míngchá-qiūháo, fǎn'ér lǚcì shàngdàng, jiāng bǎizhàn lǎojiàng Lián Pō chèhuàn. Zhè yī zhìmìng juécè shǐ sìshí wàn jiàngshì shēnshǒu-yìchù, jǐngshì hòurén jiāntīng-zémíng, piānxìn-zè'àn.", "en": "King Zhao's gullibility leading to Changping disaster is a grave historical lesson. Duped by Qin's counter-espionage rumors, he fell into the trap, replacing Lian Po. Forty thousand soldiers died, warning that credulity breeds ruin.", "es": "La caída en la trampa del rey de Zhao en Changping fue una tragedia histórica. Embaucado por bulos de Qin, cesó a Lian Po; 400.000 soldados perecieron, alertando a la posteridad de que la credulidad ciega engendra catástrofes."}, {"id": "#2", "hanzi": "“天下没有免费的午餐。”在日常经济生活与投资理财中，形形色色的诈骗陷阱层出不穷。面对各种天花乱坠的暴利诱惑，我们必须保持高度清醒的理性防线，不贪小便宜，多方核实真伪，才能避免落入骗局上当受骗。", "pinyin": "'Tiānxià méiyǒu miǎnfèi de wǔcān.' Zài rìcháng jīngjì shēnghuó yǔ tóuzī lǐcái zhōng, xíngxíng-sèsè de zhàpiàn xiànjǐng céngchū-bùqióng. Miànduì gè zhǒng tiānhuā-luànzhuì de bàolì yòuhuò, wǒmen bìxū bǎochí gāodù qīngxǐng de lǐxìng fángxiàn, bù tān xiǎo piányi, duōfāng héshí zhēnwěi, cái néng bìmiǎn luòrù piànjú shàngdàng-shòupiàn.", "en": "'There is no free lunch in this world.' In modern financial investments, scams abound. Facing temptations of overnight riches, maintaining a cool, rational defense and refusing petty greed protects us from being taken in by fraudsters.", "es": "'Nadie da duros a cuatro pesetas.' En las finanzas diarias menudean timos y engaños. Ante promesas de ganancias desmedidas, mantener la guardia racional y desconfiar de gangas fáciles evita caer en la trampa de los estafadores."}]}, {"meanings_summary": {"en": "repeatedly; again and again; over and over", "es": "repetidamente; una y otra vez; reiteradamente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Doing something once again (再) and repeating it for three times (三) means repeatedly (再三).", "composite_memory_hook_es": "Hacer algo de nuevo (再) y multiplicarlo hasta tres veces (三) sintetiza la insistencia reiterada (再三).", "cultural_and_cognitive_roots": "In Chinese numerology, 'three' represents completeness and multiplicity; '再三' denotes exhaustive repetitive effort.", "tone_sandhi_and_pitch_modulation": "Fourth tone to first tone: 'zài sān' (51-55). Drop firmly on 'zài', transitioning into a sustained high pitch on 'sān'."}, "semantic_boundary_contrasts": {"core_nuance": "再三 modifies deliberate actions (thinking, pleading, checking) performed multiple times with deep earnestness.", "contrasts": [{"id": "1", "compared_word": "再三 vs. 屡次", "pinyin": "lǚcì", "analysis": "屡次 emphasizes objective high frequency of occurrences (e.g. repeated warnings/failures), while 再三 stresses subjective earnest insistence."}, {"id": "2", "compared_word": "再三 vs. 偶尔", "pinyin": "ǒu'ěr", "analysis": "偶尔 is the direct antonym meaning occasionally or once in a blue moon."}, {"id": "3", "compared_word": "再三 vs. 频繁", "pinyin": "pínfán", "analysis": "频繁 indicates short intervals between rapid repetitions, while 再三 emphasizes earnest gravity."}]}, "traps_and_cognates": {"look_alikes": [{"character": "在", "pinyin": "zài", "meaning_en": "at; in; exist", "distinction_note": "Soil 土 on bottom instead of 冂 and horizontal bar"}, {"character": "冉", "pinyin": "rǎn", "meaning_en": "tender; gradual", "distinction_note": "Lacks the top horizontal cap stroke 一"}, {"character": "二", "pinyin": "èr", "meaning_en": "two", "distinction_note": "Two horizontal strokes instead of three"}, {"character": "丰", "pinyin": "fēng", "meaning_en": "abundant", "distinction_note": "Vertical stroke piercing three horizontal lines"}], "etymological_cognates": [{"character": "再次", "pinyin": "zàicì", "gloss_en": "once again; a second time"}, {"character": "再见", "pinyin": "zàijiàn", "gloss_en": "goodbye; see you again"}, {"character": "屡次", "pinyin": "lǚcì", "gloss_en": "repeatedly; time and again"}, {"character": "频繁", "pinyin": "pínfán", "gloss_en": "frequent; constantly"}]}, "id": "26", "hanzi": "再三", "pinyin": "zài sān", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "doing something repeatedly, more than once or twice; over and over again with insistence", "definition_es": "hacer algo de forma reiterada, más de una o dos veces; insistente y repetidamente", "example_phrase": "再三考虑 (consider over and over again)"}], "example_sentences": [{"id": "#1", "hanzi": "名相蔺相如拖着重病之躯进宫，再三劝阻赵王切不可派纸上谈兵的赵括统领大军，但赵王执迷不悟。", "pinyin": "Míngxiàng Lìn Xiàngrú tuō zhe zhòngbìng zhī qū jìn gōng, zàisān quànzǔ Zhàowáng qiè bùkě pài zhǐshàng-tánbīng de Zhào Kuò tǒnglǐng dàjūn, dàn Zhàowáng zhímí-bùwù.", "en": "Prime Minister Lin Xiangru, despite heavy illness, entered court and repeatedly pleaded with King Zhao not to dispatch Zhao Kuo, but the king refused to listen.", "es": "El canciller Lin Xiangru, aun postrado por la enfermedad, acudió a palacio a disuadir una y otra vez al rey de nombrar a Zhao Kuo, mas fue en vano."}, {"id": "#2", "hanzi": "在正式签署国际贸易合同之前，法务顾问对各项免责条款再三推敲，确保公司权益万无一失。", "pinyin": "Zài zhèngshì qiānshǔ guójì màoyì hétong zhīqián, fǎwù gùwèn duì gè xiàng miǎnzé tiáokuǎn zàisān tuīqiāo, quèbǎo gōngsī quányì wànwúyīshī.", "en": "Before formally signing the international trade contract, legal counsel weighed every disclaimer clause over and over to ensure the company's rights.", "es": "Antes de suscribir el contrato mercantil, los asesores jurídicos sopesaron reiteradamente cada cláusula de exención para salvaguardar la empresa."}], "collocations": [{"hanzi": "再三考虑", "en": "consider over and over again"}, {"hanzi": "再三叮嘱", "en": "exhort / urge repeatedly"}, {"hanzi": "再三推辞", "en": "decline repeatedly"}, {"hanzi": "再三强调", "en": "stress / emphasize again and again"}, {"hanzi": "再三挽留", "en": "urge to stay over and over"}, {"hanzi": "再三申明", "en": "reiterate repeatedly"}], "idioms": [{"hanzi": "三思而后行", "pinyin": "sān sī ér hòu xíng", "meaning_en": "think thrice before taking action; prudent deliberation"}, {"hanzi": "再三再四", "pinyin": "zài sān zài sì", "meaning_en": "repeatedly time and time again; over and over"}, {"hanzi": "语重心长", "pinyin": "yǔ zhòng xīn cháng", "meaning_en": "sincere words and earnest wishes; well-meaning exhortation"}, {"hanzi": "千叮万嘱", "pinyin": "qiān dīng wàn zhǔ", "meaning_en": "give repeated instructions and earnest exhortations"}], "character_decomposition": [{"character": "再", "pinyin": "zài", "meaning_en": "again; once more; re-; repeatedly", "meaning_es": "otra vez; de nuevo; reiterar; además", "radical": "冂", "radical_meaning_en": "down box / upside down", "meaning_component": "one horizontal bar 一 crossed by another 冉; signifies doing again", "sound_component": "再 (zài)", "stroke_count": "6", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient ideograph showing a balance scale weighing once and then balancing a second time; signifies repetition.", "visual_mnemonic_story_en": "Placing a second weight upon the balance scale to weigh once again (再).", "visual_mnemonic_story_es": "Añadir una segunda pesa sobre el platillo para contrastar la tara otra vez (再).", "tone_mnemonic_anchor": "51", "cangjie": "GMB", "traditional": "再"}, {"character": "三", "pinyin": "sān", "meaning_en": "three; several; repeated", "meaning_es": "tres; múltiple; reiterado", "radical": "一", "radical_meaning_en": "one", "meaning_component": "three parallel horizontal tally strokes", "sound_component": "三 (sān)", "stroke_count": "3", "composition_type": "单一结构", "etymology_and_mnemonic": "Three horizontal strokes representing heaven, earth, and mankind, frequently used idiomatically for multiple times.", "visual_mnemonic_story_en": "Three horizontal tally bars (三) signifying repeated, multiple instances.", "visual_mnemonic_story_es": "Tres líneas horizontales paralelas (三) que simbolizan la reiteración múltiple.", "tone_mnemonic_anchor": "55", "cangjie": "MMM", "traditional": "三"}], "extended_reading_passages": [{"id": "#1", "hanzi": "长平之战换将关头，赵国重臣蔺相如在病榻上得知消息，心急如焚。他挣扎着入宫面圣，对赵王再三进言：“赵括徒能读其父书传，不知合变也。大王因其名而用之，危亡必矣！”可惜昏庸的赵王再三拒绝忠言，终成大祸。", "pinyin": "Chángpíng zhī zhàn huànjiàng guāntóu, Zhàoguó zhòngchén Lìn Xiàngrú zài bìngtā shang dézhī xiāoxi, xīnjí-rúfén. Tā zhēngzhá zhe rù gōng miàn shèng, duì Zhàowáng zàisān jìnyán: 'Zhào Kuò tú néng dú qí fù shūzhuàn, bùzhī hébiàn yě. Dàwáng yīn qí míng ér yòng zhī, wēiwáng bì yǐ!' Kěxī hūnyōng de Zhàowáng zàisān jùjué zhōngyán, zhōng chéng dàhuò.", "en": "At the threshold of Changping, Lin Xiangru learned of the replacement on his sickbed. Staggering to court, he repeatedly warned King Zhao: 'Zhao Kuo merely recites his father's books without knowing how to adapt. Disaster is certain!' The king rejected him.", "es": "Al tramarse el relevo en Changping, Lin Xiangru supo la nueva en su lecho de dolor. Acudió al trono suplicando una y otra vez: '¡Zhao Kuo solo repite libros sin saber adaptarse; nombrarlo es la ruina!' El rey desoyó sus advertencias."}, {"id": "#2", "hanzi": "古人讲求“三思而后行”。在做出关乎人生转折或企业前途的重大抉择时，多花时间深入调研、再三权衡利弊得失，决不是优柔寡断，而是对未来高度负责的深谋远虑。慎始敬终、再三斟酌，才能行稳致远。", "pinyin": "Gǔrén jiǎngqiú 'sān sī ér hòu xíng'. Zài zuòchū guānhū rénshēng zhuǎnzhé huò qǐyè qiántú de zhòngdà juézé shí, duō huā shíjiān shēnrù diàoyán, zàisān quánhéng lìbì-déshī, jué bùshì yōuróu-guǎduàn, ér shì duì wèilái gāodù fùzé de shēnmóu-yuǎnlǜ. Shènshǐ-jìngzhōng, zàisān zhēnzhuó, cái néng xíngwěn-zhìyuǎn.", "en": "The ancients taught to 'think thrice before acting.' When making life-turning decisions, weighing pros and cons repeatedly is not indecisiveness, but responsible prudence for the future. Deliberating over and over ensures safe passage.", "es": "Los antiguos aconsejaron pensar tres veces antes de obrar. Ante encrucijadas vitales, sopesar los pros y contras una y otra vez no es indecisión, sino madura cautela; meditar con calma conduce al acierto."}]}, {"meanings_summary": {"en": "to prevent; stop; block; hinder; obstruct", "es": "impedir; frenar; detener; obstaculizar; atajar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Placing a steep barrier obstacle (阻) that forces forward footsteps to halt (止) means to prevent or stop (阻止).", "composite_memory_hook_es": "Alzar una barrera escarpada (阻) que clava los pies al suelo (止) conforma el acto de impedir (阻止).", "cultural_and_cognitive_roots": "Derived from ancient tactical gate defense where spiked barricades were erected across mountain passes to halt enemy cavalry.", "tone_sandhi_and_pitch_modulation": "Third tone sandhi chain: 'zǔ zhǐ' -> pronounced 'zú zhǐ' (35-214). The first syllable shifts smoothly to second tone."}, "semantic_boundary_contrasts": {"core_nuance": "阻止 emphasizes proactive intervention to abort an ongoing or impending harmful action.", "contrasts": [{"id": "1", "compared_word": "阻止 vs. 促进", "pinyin": "cùjìn", "analysis": "促进 is the direct antonym meaning to advance, promote, and accelerate forward."}, {"id": "2", "compared_word": "阻止 vs. 阻碍", "pinyin": "zǔ'ài", "analysis": "阻碍 means creating friction or slow progress, while 阻止 means halting the event altogether."}, {"id": "3", "compared_word": "阻止 vs. 纵容", "pinyin": "zòngróng", "analysis": "纵容 is the antonym meaning to indulge or turn a blind eye to harmful misdeeds."}]}, "traps_and_cognates": {"look_alikes": [{"character": "组", "pinyin": "zǔ", "meaning_en": "group; organize", "distinction_note": "Silk radical 纟 on left instead of 阝"}, {"character": "租", "pinyin": "zū", "meaning_en": "rent; lease", "distinction_note": "Grain radical 禾 on left instead of 阝"}, {"character": "正", "pinyin": "zhèng", "meaning_en": "straight; correct", "distinction_note": "Has a top horizontal stroke 一 over 止"}, {"character": "步", "pinyin": "bù", "meaning_en": "step; stride", "distinction_note": "Contains lower foot 少 below 止"}], "etymological_cognates": [{"character": "阻拦", "pinyin": "zǔlán", "gloss_en": "block; hold back"}, {"character": "障碍", "pinyin": "zhàng'ài", "gloss_en": "obstacle; hindrance"}, {"character": "制止", "pinyin": "zhìzhǐ", "gloss_en": "curb; put an end to"}, {"character": "停止", "pinyin": "tíngzhǐ", "gloss_en": "cease; come to a halt"}]}, "id": "27", "hanzi": "阻止", "pinyin": "zǔ zhǐ", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to stop, obstruct, or prevent an action, person, or development from proceeding forward", "definition_es": "detener, obstaculizar o impedir que progrese una acción, persona o acontecimiento perjudicial", "example_phrase": "及时阻止事故发生 (prevent accidents promptly)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括的母亲深知儿子底细，亲自面见赵王，极力阻止赵王任命毫无实战韬略的赵括为大将。", "pinyin": "Zhào Kuò de mǔqīn shēnzhī érzi dǐxì, qīnzì miànjiàn Zhàowáng, jílì zǔzhǐ Zhàowáng rènmìng háowú shízhàn tāolüè de Zhào Kuò wéi dàjiàng.", "en": "Zhao Kuo's mother knew her son's shallow depth and personally saw the king, striving mightily to prevent him from appointing Zhao Kuo as general.", "es": "La madre de Zhao Kuo, conocedora de la incapacidad de su hijo, acudió ante el rey para impedir con vehemencia que lo nombrara general."}, {"id": "#2", "hanzi": "巡警在夜间巡逻时敏锐发现了两名可疑分子，果断采取措施，成功阻止了一起严重入室盗窃案。", "pinyin": "Xúnjǐng zài yèjiān xúnluó shí mǐnruì fāxiàn le liǎng míng kěyí fènzǐ, guǒduàn cǎiqǔ cuòshī, chénggōng zǔzhǐ le yī qǐ yánzhòng rùshì dàoqiè'àn.", "en": "During night patrol, police spotted two suspicious individuals and took decisive measures, successfully preventing a serious burglary.", "es": "Durante la ronda nocturna, los agentes detectaron a dos sospechosos y actuaron con rapidez, impidiendo un grave robo con allanamiento."}], "collocations": [{"hanzi": "极力阻止", "en": "strive mightily to prevent"}, {"hanzi": "无法阻止", "en": "impossible to stop / prevent"}, {"hanzi": "阻止事态恶化", "en": "prevent the situation from worsening"}, {"hanzi": "及时阻止", "en": "prevent in a timely manner"}, {"hanzi": "设法阻止", "en": "find ways to stop"}, {"hanzi": "阻止悲剧发生", "en": "prevent tragedy from happening"}], "idioms": [{"hanzi": "防患未然", "pinyin": "fáng huàn wèi rán", "meaning_en": "prevent troubles before they happen"}, {"hanzi": "力挽狂澜", "pinyin": "lì wǎn kuáng lán", "meaning_en": "pull back raging billows; save a desperate situation"}, {"hanzi": "截长补短", "pinyin": "jié cháng bǔ duǎn", "meaning_en": "trim excess to make up for deficiency"}, {"hanzi": "势不可挡", "pinyin": "shì bù kě dǎng", "meaning_en": "overwhelming momentum that cannot be stopped"}], "character_decomposition": [{"character": "阻", "pinyin": "zǔ", "meaning_en": "block; impede; hinder; obstacle", "meaning_es": "bloquear; impedir; obstáculo; traba", "radical": "阝", "radical_meaning_en": "mound / hill", "meaning_component": "阝 (steep earthen cliff) + 且 (standing ancestral stone marker)", "sound_component": "且 (qiě / zǔ)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "A steep earthen cliff 阝 blocking the road ahead like an immovable stone slab 且; signifies obstruction.", "visual_mnemonic_story_en": "A towering rocky precipice (阝) barring travelers' passage like an immovable stone wall (阻).", "visual_mnemonic_story_es": "Un risco escarpado (阝) que corta el camino al viajero como un muro de piedra infranqueable (阻).", "tone_mnemonic_anchor": "214", "cangjie": "NLBM", "traditional": "阻"}, {"character": "止", "pinyin": "zhǐ", "meaning_en": "stop; halt; cease; only", "meaning_es": "parar; detener; cesar; límite; solo", "radical": "止", "radical_meaning_en": "stop / foot", "meaning_component": "pictograph of human footprint planted firmly on earth", "sound_component": "止 (zhǐ)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Ancient oracle bone pictograph of a human foot resting stationary upon the ground; to stop moving.", "visual_mnemonic_story_en": "Planting a firm foot (止) on the ground to halt forward motion.", "visual_mnemonic_story_es": "Plantar el pie con firmeza en el suelo (止) para detener la marcha en seco.", "tone_mnemonic_anchor": "214", "cangjie": "YLM", "traditional": "止"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在赵国面临换将危机的关头，不仅蔺相如拼死苦谏，赵括的母亲更是亲自上书赵王，直言儿子与丈夫截然不同，极力阻止这一致命任命。然而赵王利令智昏，完全听不进任何劝谏，最终导致四十万赵军魂断长平。", "pinyin": "Zài Zhàoguó miànlín huànjiàng wēijī de guāntóu, bùjǐn Lìn Xiàngrú pīnsǐ kǔjiàn, Zhào Kuò de mǔqīn gèng shì qīnzì shàngshū Zhàowáng, zhíyán érzi yǔ zhàngfu jiérán-bùtóng, jílì zǔzhǐ zhè yī zhìmìng rènmìng. Rán'ér Zhàowáng lìlìngzhìhūn, wánquán tīng bù jìn rènhé quànjiàn, zuìzhōng dǎozhì sìshí wàn Zhàojūn hún duàn Chángpíng.", "en": "At the crisis of command, not only did Lin Xiangru plead, but Zhao Kuo's mother petitioned the king, stating her son was nothing like her late husband and striving to stop the appointment. Blinded, the king refused, sealing the tragedy.", "es": "Ante el relevo en el mando, Lin Xiangru y la madre de Zhao Kuo rogaron al monarca, señalando que el hijo no se parecía en nada al padre e intentando atajar el nombramiento. El soberbio rey desoyó el ruego, consumando la hecatombe."}, {"id": "#2", "hanzi": "在现代法治社会中，任何违法犯罪行为都必须受到法律的严正阻止与制裁。公安干警与各界群众紧密协作，不仅要依法惩处已经发生的犯罪，更要通过精密监控与社区调解，防微杜渐，将各类潜在危害隐患及时阻止在萌芽状态。", "pinyin": "Zài xiàndài fǎzhì shèhuì zhōng, rènhé wéifǎ-fànzuì xíngwéi dōu bìxū shòudào fǎlǜ de yánzhèng zǔzhǐ yǔ zhìcái. Gōng'ān gànjǐng yǔ gèjiè qúnzhòng jǐnmì xiézuò, bùjǐn yào yīfǎ chéngchǔ yǐjīng fāshēng de fànzuì, gèng yào tōngguò jīngmì jiānkòng yǔ shèqū tiáojiě, fángwēi-dùjiàn, jiāng gèlèi qiánzài wēihài yǐnhuàn jíshí zǔzhǐ zài méngyá zhuàngtài.", "en": "In modern societies under the rule of law, crimes must be sternly halted by law. Through surveillance and community mediation, police and citizens work together to stop latent hazards in their nascent stages before harm occurs.", "es": "En un Estado de derecho, la delincuencia debe ser frenada y sancionada con rigor. La policía y la ciudadanía cooperan para disuadir delitos y atajar peligros en su raíz antes de que causen daños irreparables."}]}, {"meanings_summary": {"en": "to appoint; nominate; commission; designation", "es": "nombrar; designar; conferir cargo; nombramiento"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Bestowing a public duty burden (任) through an official sovereign mandate (命) is to appoint (任命).", "composite_memory_hook_es": "Encomendar una responsabilidad pública (任) mediante mandato oficial (命) constituye el nombramiento (任命).", "cultural_and_cognitive_roots": "Derived from ancient investiture ceremonies where emperors conferred bronze seals and tallies to magistrates upon appointment.", "tone_sandhi_and_pitch_modulation": "Double fourth tone: 'rèn mìng' (51-51). Articulate both syllables with decisive authoritative weight."}, "semantic_boundary_contrasts": {"core_nuance": "任命 specifically denotes the top-down official conferral of leadership authority or public office.", "contrasts": [{"id": "1", "compared_word": "任命 vs. 免职", "pinyin": "miǎnzhí", "analysis": "免职 is the direct antonym meaning to relieve someone of their official duties or remove them from office."}, {"id": "2", "compared_word": "任命 vs. 选举", "pinyin": "xuǎnjǔ", "analysis": "选举 is bottom-up democratic voting by a constituency, whereas 任命 is top-down designation by superiors."}, {"id": "3", "compared_word": "任命 vs. 聘请", "pinyin": "pìnqǐng", "analysis": "聘请 implies hiring professional consultants or professors on contractual terms, while 任命 carries administrative sovereign power."}]}, "traps_and_cognates": {"look_alikes": [{"character": "住", "pinyin": "zhù", "meaning_en": "live; reside", "distinction_note": "Master 主 on right of 亻 instead of 壬"}, {"character": "仕", "pinyin": "shì", "meaning_en": "official; serve", "distinction_note": "Scholar 士 on right of 亻 instead of 壬"}, {"character": "伞", "pinyin": "sǎn", "meaning_en": "umbrella", "distinction_note": "Has multiple horizontal lines under 人"}, {"character": "令", "pinyin": "lìng", "meaning_en": "order; season", "distinction_note": "Lacks the mouth 口 component at the bottom"}], "etymological_cognates": [{"character": "责任", "pinyin": "zérèn", "gloss_en": "responsibility; duty"}, {"character": "任期", "pinyin": "rènqī", "gloss_en": "term of office"}, {"character": "使命", "pinyin": "shǐmìng", "gloss_en": "mission; calling"}, {"character": "聘任", "pinyin": "pìnrèn", "gloss_en": "hire; appoint by contract"}]}, "id": "28", "hanzi": "任命", "pinyin": "rèn mìng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to officially assign someone to a position of leadership, government post, or military command", "definition_es": "designar o conferir formalmente a una persona un cargo oficial de gobierno, mando militar o jefatura", "example_phrase": "正式任命为院长 (formally appointed as dean)"}], "example_sentences": [{"id": "#1", "hanzi": "昏庸自大的赵王不顾重臣与赵母的极力反对，执意正式任命毫无实战经验的赵括统领长平大军。", "pinyin": "Hūnyōng-zìdà de Zhàowáng bùgù zhòngchén yǔ Zhàomǔ de jílì fǎnduì, zhíyì zhèngshì rènmìng háowú shízhàn jīngyàn de Zhào Kuò tǒnglǐng Chángpíng dàjūn.", "en": "The arrogant King Zhao disregarded ministers' and Zhao Kuo's mother's fierce objections, insisting on appointing inexperienced Zhao Kuo to command.", "es": "El soberbio rey de Zhao, desoyendo al consejo y a la propia madre de Zhao Kuo, nombró formalmente a este al frente del ejército en Changping."}, {"id": "#2", "hanzi": "经联合国教科文组织理事会审议表决，张教授被正式任命为新一届国际文化遗产保护委员会主席。", "pinyin": "Jīng Liánhéguó Jiàokēwén Zǔzhī lǐshìhuì shěnyì biàojué, Zhāng jiàoshòu bèi zhèngshì rènmìng wéi xīn yī jiè guójì wénhuà yíchǎn bǎohù wěiyuánhuì zhǔxí.", "en": "Following deliberation by the UNESCO council, Professor Zhang was formally appointed as president of the World Heritage Protection Committee.", "es": "Tras la votación del consejo de la UNESCO, el profesor Zhang fue nombrado presidente del Comité de Protección del Patrimonio Mundial."}], "collocations": [{"hanzi": "正式任命", "en": "formally appoint / nominate"}, {"hanzi": "任命为代表", "en": "appointed as representative"}, {"hanzi": "接受任命", "en": "accept the appointment"}, {"hanzi": "任命书", "en": "letter / certificate of appointment"}, {"hanzi": "撤销任命", "en": "rescind / revoke an appointment"}, {"hanzi": "行政任命", "en": "administrative appointment"}], "idioms": [{"hanzi": "任人唯贤", "pinyin": "rèn rén wéi xián", "meaning_en": "appoint people according to their political integrity and competence"}, {"hanzi": "任人唯亲", "pinyin": "rèn rén wéi qīn", "meaning_en": "appoint people by favoritism and nepotism (antonym)"}, {"hanzi": "知人善任", "pinyin": "zhī rén shàn rèn", "meaning_en": "know people well and assign them to posts suited to abilities"}, {"hanzi": "委以重任", "pinyin": "wěi yǐ zhòng rèn", "meaning_en": "entrust someone with heavy responsibilities"}], "character_decomposition": [{"character": "任", "pinyin": "rèn", "meaning_en": "appoint; task; duty; office; assume", "meaning_es": "nombrar; cargo; deber; encomendar; asumir", "radical": "亻", "radical_meaning_en": "person", "meaning_component": "亻 (person standing) + 壬 (loom carrier holding heavy warp threads)", "sound_component": "壬 (rén)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "A person 亻 shouldering a heavy burden on a carrying pole 壬; signifies bearing official responsibility.", "visual_mnemonic_story_en": "A capable person (亻) shouldering a heavy burden on a balance pole (壬) with steady duty (任).", "visual_mnemonic_story_es": "Una persona íntegra (亻) cargando sobre los hombros una balanza de peso (壬) con entereza (任).", "tone_mnemonic_anchor": "51", "cangjie": "OHG", "traditional": "任"}, {"character": "命", "pinyin": "mìng", "meaning_en": "command; decree; mandate; life", "meaning_es": "orden; mandato; decreto; vida", "radical": "口", "radical_meaning_en": "mouth", "meaning_component": "口 (authoritative mouth decree) + 令 (binding command)", "sound_component": "令 (lìng)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "A mouth 口 delivering a binding state command 令 to commission an officer.", "visual_mnemonic_story_en": "A sovereign's mouth (口) pronouncing a royal mandate (令) conferring public rank (命).", "visual_mnemonic_story_es": "La boca del monarca (口) proclamando el mandato regio (令) que confiere dignidad (命).", "tone_mnemonic_anchor": "51", "cangjie": "ROMB", "traditional": "命"}], "extended_reading_passages": [{"id": "#1", "hanzi": "中国古代选贤任能讲究“知人善任”。长平之战前夕，赵王未能辨明虚实，在关乎国家生死存亡的决战时刻，错误地任命只擅长空谈兵法的赵括取代廉颇。这一轻率的任命打破了战略平衡，最终成为导致赵国亡国的转折点。", "pinyin": "Zhōngguó gǔdài xuǎnxián-rènnéng jiǎngjiu 'zhīrén-shànrèn'. Chángpíng zhī zhàn qiánxī, Zhàowáng wèinéng biànmíng xūshí, zài guānhū guójiā shēngsǐ-cúnwáng de juézhàn shíkè, cuòwù de rènmìng zhǐ shàncháng kōngtán bīngfǎ de Zhào Kuò qǔdài Lián Pō. Zhè yī qīngshuài de rènmìng dǎpò le zhànlüè pínghéng, zuìzhōng chéngwéi dǎozhì Zhàoguó wángguó de zhuǎnzhédiǎn.", "en": "Ancient statecraft emphasized appointing people suited to their talents. Before Changping, King Zhao failed to discern true capability, appointing Zhao Kuo to replace Lian Po. This reckless appointment tipped the balance, marking the collapse of Zhao.", "es": "La gobernanza clásica valoraba el nombramiento de los hombres según su talento. Antes de Changping, el rey de Zhao erró nombrando al bisoño Zhao Kuo en vez de a Lian Po. Aquel nombramiento temerario rompió el equilibrio y precipitó la ruina del reino."}, {"id": "#2", "hanzi": "在现代企业治理与组织管理中，核心管理层的任命直接关乎整个机构的战略航向与运营成效。唯有坚持“任人唯贤、德才兼备”的考核标准，把真正具备实战经验与卓越领导力的骨干任命到关键岗位，组织才能在激烈的市场竞争中乘风破浪。", "pinyin": "Zài xiàndài qǐyè zhìlǐ yǔ zǔzhī guǎnlǐ zhōng, héxīn guǎnlǐcéng de rènmìng zhíjiē guānhū zhěnggè jīgòu de zhànlüè hángxiàng yǔ yùnyíng chéngxiào. Wéiyǒu jiānchí 'rènrén-wéixián, décái-jiānbèi' de kǎohé biāozhǔn, bǎ zhēnzhèng jùbèi shízhàn jīngyàn yǔ zhuóyuè lǐngdǎolì de gǔgàn rènmìng dào guānjiàn gǎngwèi, zǔzhī cái néng zài jīliè de shìchǎng jìngzhēng zhōng chéngfēng-pòlàng.", "en": "In corporate governance, appointing executive leadership directly decides strategic direction and efficiency. Only by adhering to meritocratic standards—appointing talents of proven integrity and tested capability—can an enterprise conquer market tides.", "es": "En la gestión corporativa moderna, nombrar a los directivos decide el rumbo estratégico. Guiándose por el mérito y la solvencia ética para designar a los cuadros más aptos, las empresas logran triunfar en mercados competitivos."}]}, {"meanings_summary": {"en": "independent; stand alone; self-reliant; sovereignty", "es": "independiente; autónomo; erguirse en solitario; soberanía"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Standing alone in solitude (独) firmly upright on one's own feet (立) means to be independent (独立).", "composite_memory_hook_es": "Hallarse solo (独) erguido sobre los propios pies con entereza (立) conforma la independencia (独立).", "cultural_and_cognitive_roots": "From classical ethics ('独立而不改') celebrating the noble scholar who preserves moral autonomy against peer pressure.", "tone_sandhi_and_pitch_modulation": "Second tone to fourth tone: 'dú lì' (35-51). Rise smoothly on 'dú', then drop firmly on 'lì'."}, "semantic_boundary_contrasts": {"core_nuance": "独立 denotes self-reliant autonomy free from external control, subordination, or dependence.", "contrasts": [{"id": "1", "compared_word": "独立 vs. 依赖", "pinyin": "yīlài", "analysis": "依赖 is the direct antonym meaning to lean on, depend on, or cling to others."}, {"id": "2", "compared_word": "独立 vs. 孤立", "pinyin": "gūlì", "analysis": "孤立 carries a negative sense of being cut off from support, while 独立 represents positive sovereign self-reliance."}, {"id": "3", "compared_word": "独立 vs. 附属", "pinyin": "fùshǔ", "analysis": "附属 means subordinate or attached as an auxiliary annex, opposite to autonomous 独立."}]}, "traps_and_cognates": {"look_alikes": [{"character": "触", "pinyin": "chù", "meaning_en": "touch", "distinction_note": "Horn 角 on left instead of 犭"}, {"character": "浊", "pinyin": "zhuó", "meaning_en": "turbid; muddy", "distinction_note": "Water 氵 on left instead of 犭"}, {"character": "位", "pinyin": "wèi", "meaning_en": "position; seat", "distinction_note": "Person 亻 on left of 立"}, {"character": "拉", "pinyin": "lā", "meaning_en": "pull", "distinction_note": "Hand 扌 on left of 立"}], "etymological_cognates": [{"character": "独自", "pinyin": "dúzì", "gloss_en": "alone; by oneself"}, {"character": "自立", "pinyin": "zìlì", "gloss_en": "self-reliant; stand on own"}, {"character": "成立", "pinyin": "chénglì", "gloss_en": "establish; found"}, {"character": "孤立", "pinyin": "gūlì", "gloss_en": "isolated; helpless"}]}, "id": "29", "hanzi": "独立", "pinyin": "dú lì", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "free from outside control or reliance; able to act, think, or stand alone without depending on others", "definition_es": "libre de dependencia o tutela ajena; capaz de obrar, pensar o sostenerse por sí mismo", "example_phrase": "独立思考 (think independently)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括自幼缺乏独立带兵作战的经验，一旦真正面临数十万大军的生死决战，便显得束手无策。", "pinyin": "Zhào Kuò zìyòu quēfá dúlì dài bīng zuòzhàn de jīngyàn, yīdàn zhēnzhèng miànlín shùshí wàn dàjūn de shēngsǐ juézhàn, biàn xiǎnde shùshǒu-wúcè.", "en": "Zhao Kuo had lacked independent experience in leading troops; when suddenly faced with a life-and-death campaign of thousands, he proved helpless.", "es": "Zhao Kuo carecía de experiencia de mando autónomo; al encarar una batalla de cientos de miles de hombres, se halló atado de pies y manos."}, {"id": "#2", "hanzi": "青年人在成长过程中不仅要在经济上逐步自立，更应当在学术和思想上培养独立思考的能力。", "pinyin": "Qīngniánrén zài chéngzhǎng guòchéng zhōng bùjǐn yào zài jīngjì shang zhúbù zìlì, gèng yīngdāng zài xuéshù hé sīxiǎng shang péiyǎng dúlì sīkǎo de nénglì.", "en": "In growing up, youth must not only achieve economic self-reliance, but also cultivate the capability for independent thought in academics and ideas.", "es": "En su maduración, los jóvenes no solo deben alcanzar la solvencia material, sino cultivar el juicio crítico y el pensamiento autónomo."}], "collocations": [{"hanzi": "独立思考", "en": "think independently"}, {"hanzi": "国家独立", "en": "national independence"}, {"hanzi": "独立自主", "en": "independent and self-reliant"}, {"hanzi": "独立作战", "en": "fight independently"}, {"hanzi": "经济独立", "en": "financial independence"}, {"hanzi": "独立人格", "en": "independent personality / integrity"}], "idioms": [{"hanzi": "特立独行", "pinyin": "tè lì dú xíng", "meaning_en": "act independently and stay true to principles despite crowds"}, {"hanzi": "自立更生", "pinyin": "zì lì gēng shēng", "meaning_en": "regenerate through one's own efforts; self-reliance"}, {"hanzi": "自食其力", "pinyin": "zì shí qí lì", "meaning_en": "support oneself by one's own labor"}, {"hanzi": "卓尔不群", "pinyin": "zhuó ěr bù qún", "meaning_en": "stand out prominently from the crowd in excellence"}], "character_decomposition": [{"character": "独", "pinyin": "dú", "meaning_en": "alone; single; solitary; only", "meaning_es": "solo; único; solitario; exclusivo", "radical": "犭", "radical_meaning_en": "dog / beast", "meaning_component": "犭 (solitary wild beast) + 虫 (crawling insect standing alone)", "sound_component": "蜀 (shǔ / dú)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "A wild predatory animal 犭 that hunts in solitude rather than in a herd; signifies standing alone.", "visual_mnemonic_story_en": "A proud solitary wolf (犭) roaming the snowfields alone without relying on the pack (独).", "visual_mnemonic_story_es": "Un lobo solitario (犭) que campea por el páramo con dignidad sin depender de la manada (独).", "tone_mnemonic_anchor": "35", "cangjie": "KHLI", "traditional": "獨"}, {"character": "立", "pinyin": "lì", "meaning_en": "stand; erect; establish; set up", "meaning_es": "erguirse; estar de pie; fundar; erigir", "radical": "立", "radical_meaning_en": "stand", "meaning_component": "pictograph of a person standing upright firmly on the ground 一", "sound_component": "立 (lì)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "A human figure standing firmly upright with feet planted upon the solid earth 一.", "visual_mnemonic_story_en": "A human standing tall and erect on the ground with unshakable balance (立).", "visual_mnemonic_story_es": "Una silueta humana que se yergue con aplomo sobre el suelo firme (立).", "tone_mnemonic_anchor": "51", "cangjie": "YT", "traditional": "立"}], "extended_reading_passages": [{"id": "#1", "hanzi": "真正的军事指挥才能绝不能仅凭书本背诵获得，而必须在尸山血海的实战中磨炼出独立判断的胆略。赵括平生从未独立指挥过哪怕一次真正的大战，在长平前线一旦遭遇白起的诡谲奇袭，其缺乏独立统帅经验的弊端便暴露无遗。", "pinyin": "Zhēnzhèng de jūnshì zhǐhuī cáinéng juébùnéng jǐn píng shūběn bèisòng huòdé, ér bìxū zài shīshān-xuèhǎi de shízhàn zhōng móliàn chū dúlì pànduàn de dǎnlüè. Zhào Kuò píngshēng cóngwèi dúlì zhǐhuī guò nǎpà yī cì zhēnzhèng de dàzhàn, zài Chángpíng qiánxiàn yīdàn zāoyù Bái Qǐ de guǐjué qíxí, qí quēfá dúlì tǒngshuài jīngyàn de bìduān biàn bàolù-wúyí.", "en": "True military command can never be memorized from books; it must be forged in combat to temper independent judgment. Zhao Kuo had never independently led an army in a real campaign; facing Bai Qi's ambush, his lack of command experience doomed him.", "es": "La maestría bélica no se adquiere memorizando tratados; se forja en el fuego para templar el juicio autónomo. Zhao Kuo jamás había comandado en solitario una gran campaña; ante las celadas de Bai Qi, su inexperiencia quedó al desnudo."}, {"id": "#2", "hanzi": "“独立之精神，自由之思想。”在学术探索与人生追求的漫长道路上，保持独立思考的能力是抵御盲从与偏见的最强盾牌。敢于坚持真理、不人云亦云，唯有具备独立人格的人，才能在时代的洪流中站稳脚跟，书写有意义的壮丽篇章。", "pinyin": "'Dúlì zhī jīngshén, zìyóu zhī sīxiǎng.' Zài xuéshù tànsuǒ yǔ rénshēng zhuīqiú de màncháng dàolù shang, bǎochí dúlì sīkǎo de nénglì shì dǐyù mángcóng yǔ piānjiàn de zuì qiáng dùnpái. Gǎnyú jiānchí zhēnlǐ, bù rényún-yìyún, wéiyǒu jùbèi dúlì réngé de rén, cái néng zài shídài de hóngliú zhōng zhànwěn jiǎogēn, shūxiě yǒuyìyì de zhuànglì piānzhāng.", "en": "'Independence of spirit, freedom of thought.' In academic pursuits, independent thinking is the shield against dogma. Daring to uphold truth without parroting crowds, those with independent character plant firm feet to write meaningful life chapters.", "es": "'Espíritu independiente, pensamiento libre.' En la ciencia y en la vida, el criterio autónomo es el baluarte contra el dogmatismo. Sostener la verdad sin repetir consignas ajenas permite labrarse un destino noble en la historia."}]}, {"meanings_summary": {"en": "qualifications; competence; credentials; seniority", "es": "cualificación; titulación; competencia; credencial; méritos"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Accumulated resource capital (资) matching the official standard grid (格) grants formal qualifications (资格).", "composite_memory_hook_es": "El caudal de mérito acumulado (资) que encaja en la norma reglamentaria (格) confiere la cualificación (资格).", "cultural_and_cognitive_roots": "Originates from imperial civil examinations where candidates' family pedigree (资) and test standards (格) were scrutinized.", "tone_sandhi_and_pitch_modulation": "First tone to second tone: 'zī gé' (55-35). High level pitch on 'zī', lifting smoothly on 'gé'."}, "semantic_boundary_contrasts": {"core_nuance": "资格 refers to satisfying requisite formal, professional, or legal criteria to undertake duties or enjoy rights.", "contrasts": [{"id": "1", "compared_word": "资格 vs. 条件", "pinyin": "tiáojiàn", "analysis": "条件 refers to broad objective factors or prerequisites, while 资格 specifically denotes legal/professional status and eligibility."}, {"id": "2", "compared_word": "资格 vs. 能力", "pinyin": "nénglì", "analysis": "能力 is actual competence in execution, whereas 资格 can merely be a formal certificate or title."}, {"id": "3", "compared_word": "资格 vs. 资历", "pinyin": "zīlì", "analysis": "资历 measures accumulated chronological tenure/seniority, while 资格 focuses on meeting qualifying standards."}]}, "traps_and_cognates": {"look_alikes": [{"character": "姿", "pinyin": "zī", "meaning_en": "posture; gesture", "distinction_note": "Woman 女 under 次 instead of 贝"}, {"character": "咨", "pinyin": "zī", "meaning_en": "consult; inquire", "distinction_note": "Mouth 口 under 次 instead of 贝"}, {"character": "洛", "pinyin": "luò", "meaning_en": "Luo River", "distinction_note": "Water 氵 on left of 各 instead of 木"}, {"character": "阁", "pinyin": "gé", "meaning_en": "pavilion; chamber", "distinction_note": "Door 门 around 各 instead of 木"}], "etymological_cognates": [{"character": "资历", "pinyin": "zīlì", "gloss_en": "qualifications and record"}, {"character": "资本", "pinyin": "zīběn", "gloss_en": "capital; assets"}, {"character": "合格", "pinyin": "hégé", "gloss_en": "qualified; up to standard"}, {"character": "品格", "pinyin": "pǐngé", "gloss_en": "moral character; caliber"}]}, "id": "30", "hanzi": "资格", "pinyin": "zī gé", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "requisite conditions, credentials, experience, or status enabling one to assume a post or enjoy rights", "definition_es": "requisitos, méritos, títulos o condición indispensable para ejercer un cargo o disfrutar de un derecho", "example_phrase": "具备任职资格 (possess the qualifications to hold office)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括虽然能熟练背诵各家兵书，但在瞬息万变的实战战场上，他根本不具备统帅数十万大军的资格。", "pinyin": "Zhào Kuò suīrán néng shúliàn bèisòng gè jiā bīngshū, dàn zài shùnxī-wànbiàn de shízhàn zhànchǎng shang, tā gēnběn bù jùbèi tǒnglǐng shùshí wàn dàjūn de zīgé.", "en": "Although Zhao Kuo could recite military books, on the fast-changing battlefield he lacked the qualifications to command hundreds of thousands of troops.", "es": "Aunque Zhao Kuo recitaba tratados de memoria, en la crudeza del combate real carecía por entero de las cualificaciones para mandar a un ejército."}, {"id": "#2", "hanzi": "通过了全国统一的高级翻译专业资格考试，她顺利获得了联合国同声传译员的执业资格。", "pinyin": "Tōngguò le quánguó tǒngyī de gāojí fānyì zhuānyè zīgé kǎoshì, tā shùnlì huòdé le Liánhéguó tóngshēng chuányìyuán de zhíyè zīgé.", "en": "Passing the national advanced translation qualification exam, she obtained the professional credential to practice as a UN interpreter.", "es": "Tras aprobar el examen nacional de traducción superior, obtuvo la titulación profesional para ejercer como intérprete simultánea en la ONU."}], "collocations": [{"hanzi": "具备资格", "en": "possess qualifications / credentials"}, {"hanzi": "取消资格", "en": "disqualify / revoke qualifications"}, {"hanzi": "审查资格", "en": "examine / verify qualifications"}, {"hanzi": "获得资格", "en": "obtain qualification"}, {"hanzi": "老资格", "en": "veteran / senior standing"}, {"hanzi": "从业资格", "en": "professional certification / practice license"}], "idioms": [{"hanzi": "名正言顺", "pinyin": "míng zhèng yán shùn", "meaning_en": "in accordance with proper title and reasons; fully justified"}, {"hanzi": "德才兼备", "pinyin": "dé cái jiān bèi", "meaning_en": "possessing both integrity and talent; highly qualified"}, {"hanzi": "论资排辈", "pinyin": "lùn zī pái bèi", "meaning_en": "assign ranks strictly according to seniority and tenure"}, {"hanzi": "实至名归", "pinyin": "shí zhì míng guī", "meaning_en": "reputation deserved by actual merit"}], "character_decomposition": [{"character": "资", "pinyin": "zī", "meaning_en": "money; wealth; resources; capital; qualification", "meaning_es": "dinero; bienes; recursos; capital; solvencia", "radical": "贝", "radical_meaning_en": "cowrie shell / money", "meaning_component": "次 (order / sequence) + 贝 (cowrie shell / wealth backing)", "sound_component": "次 (cì)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Accumulating sequential reserves of wealth 贝 or merit 次 over time; signifies backing capital and qualifications.", "visual_mnemonic_story_en": "Accumulating valuable shell currency (贝) in orderly ranks (次) to earn status (资).", "visual_mnemonic_story_es": "Atesorar caudales valiosos (贝) en riguroso orden (次) para respaldar la solvencia y mérito (资).", "tone_mnemonic_anchor": "55", "cangjie": "MOBO", "traditional": "資"}, {"character": "格", "pinyin": "gé", "meaning_en": "grid; standard; pattern; style; examine", "meaning_es": "cuadrícula; norma; patrón; estilo; examinar", "radical": "木", "radical_meaning_en": "wood", "meaning_component": "木 (wooden branch / measuring frame) + 各 (distinct individual items)", "sound_component": "各 (gè)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "A wooden lattice frame 木 used to measure and sort individual items 各 according to standards; marks standards.", "visual_mnemonic_story_en": "Using a wooden lattice frame (木) to classify items into proper categories (格).", "visual_mnemonic_story_es": "Una regla de madera (木) que clasifica cada objeto en su casilla correspondiente (格).", "tone_mnemonic_anchor": "35", "cangjie": "DHER", "traditional": "格"}], "extended_reading_passages": [{"id": "#1", "hanzi": "兵家常云：“为将者，未料胜，先料败。”统领数十万军民生死存亡的大将，必须具备过人的智谋、沉稳的心态与丰富的实战资历。赵括徒有一腔纸上谈兵的空论，缺乏带兵治军的真才实学，从根本上就不具备统领长平大军的资格。", "pinyin": "Bīngjiā cháng yún: 'Wéi jiàng zhě, wèi liào shèng, xiān liào bài.' Tǒnglǐng shùshí wàn jūnmín shēngsǐ-cúnwáng de dàjiàng, bìxū jùbèi guòrén de zhìmóu, chénwěn de xīntài yǔ fēngfù de shízhàn zīlì. Zhào Kuò tú yǒu yī qiāng zhǐshàng-tánbīng de kōnglùn, quēfá dài bīng zhì jūn de zhēncái-shíxué, cóng gēnběn shang jiù bù jùbèi tǒnglǐng Chángpíng dàjūn de zīgé.", "en": "Strategists say: 'A general calculates defeat before victory.' Commanding troops demands wisdom, composure, and combat credentials. Zhao Kuo held only empty book talk without real substance; he lacked the qualifications to lead.", "es": "Los maestros castrenses decían: 'El general antes de prever la victoria calcula la derrota.' Comandar miles de vidas exige temple y fogueo real. Zhao Kuo solo poseía vanas teorías; carecía de cualificación para semejante mando."}, {"id": "#2", "hanzi": "在现代社会中，任何专业岗位的准入都建立在严格的资质审核基础之上。从医生的执业医师资格、律师的法律从业资格，到工程师的高级技术职称，只有通过严谨规范的专业考核获取相应资格，才能切实对公众安全负责。", "pinyin": "Zài xiàndài shèhuì zhōng, rènhé zhuānyè gǎngwèi de zhǔnrù dōu jiànlì zài yángé de zīzhì shěnhé jīchǔ zhīshàng. Cóng yīshēng de zhíyè yīshī zīgé, lǜshī de fǎlǜ cóngyè zīgé, dào gōngchéngshī de gāojí jìshù zhíchēng, zhǐyǒu tōngguò yánjǐn guīfàn de zhuānyè kǎohé huòqǔ xiāngyìng zīgé, cái néng qièshí duì gōngzhòng ānquán fùzé.", "en": "In modern society, entry into professions rests on strict qualification vetting. From medical licenses and bar exams to engineering certificates, only passing rigorous professional evaluations to earn qualifications ensures public safety.", "es": "En la sociedad moderna, el acceso a las profesiones descansa en la acreditación de títulos. Desde la colegiación médica hasta los títulos de ingeniería, acreditar la cualificación mediante exámenes rigurosos garantiza la seguridad pública."}]}, {"meanings_summary": {"en": "confused; muddle-headed; foolish; blurred", "es": "confundido; confuso; despistado; aturdido"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Sticky rice paste (糊) smeared around (涂) blinds one's sight, leaving thoughts muddled (糊涂).", "composite_memory_hook_es": "Engrudo de arroz (糊) embadurnado (涂) que nubla la vista y confunde el juicio (糊涂).", "cultural_and_cognitive_roots": "Derived from culinary pasting and smearing mud, metaphorically applied to mental opacity and indistinct thought.", "tone_sandhi_and_pitch_modulation": "Second tone to neutral tone: 'hú tu' (35-neutral). Gentle drop into a short unstressed syllable."}, "semantic_boundary_contrasts": {"core_nuance": "糊涂 emphasizes subjective mental haze, poor comprehension, or temporary loss of rational judgment.", "contrasts": [{"id": "1", "compared_word": "糊涂 vs. 愚蠢", "pinyin": "yúchǔn", "analysis": "愚蠢 denotes inherent intellectual deficit or folly, whereas 糊涂 describes temporary mental confusion or muddled reasoning."}, {"id": "2", "compared_word": "糊涂 vs. 迷茫", "pinyin": "mímáng", "analysis": "迷茫 refers to feeling lost regarding future orientation, while 糊涂 denotes clouded logical thinking."}, {"id": "3", "compared_word": "糊涂 vs. 混乱", "pinyin": "hùnluàn", "analysis": "混乱 describes external structural disorder or chaos, while 糊涂 characterizes an internal psychological state."}]}, "traps_and_cognates": {"look_alikes": [{"character": "湖", "pinyin": "hú", "meaning_en": "lake", "distinction_note": "Water 氵 on left instead of rice 米"}, {"character": "胡", "pinyin": "hú", "meaning_en": "reckless; beard", "distinction_note": "No rice 米 component"}, {"character": "徐", "pinyin": "xú", "meaning_en": "slow; gentle", "distinction_note": "Step 彳 on left instead of water 氵"}, {"character": "途", "pinyin": "tú", "meaning_en": "road; journey", "distinction_note": "Walk 辶 radical instead of water 氵"}], "etymological_cognates": [{"character": "糊口", "pinyin": "húkǒu", "gloss_en": "scrape together a meager livelihood"}, {"character": "含糊", "pinyin": "hánhu", "gloss_en": "vague; ambiguous"}, {"character": "涂鸦", "pinyin": "túyā", "gloss_en": "scrawl; graffiti"}, {"character": "抹涂", "pinyin": "mǎtú", "gloss_en": "daub; smear over"}]}, "id": "31", "hanzi": "糊涂", "pinyin": "hú tu", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "muddle-headed; lacking clear thinking or judgment; confused", "definition_es": "confundido; falto de juicio lúcido; con la mente embotada", "example_phrase": "头脑糊涂 (muddle-headed mind)"}], "example_sentences": [{"id": "#1", "hanzi": "长平阵前战局万分危急，主帅如果头脑糊涂、盲目听信虚假情报，势必会导致全军覆没的惨剧。", "pinyin": "Chángpíng zhènqián zhànjú wànfēn wēijí, zhǔshuài rúguǒ tóunǎo hútu, mángmù tīngxìn xūjiǎ qíngbào, shìbì huì dǎozhì quánjūn fùmò de cǎnjù.", "en": "At the frontlines of Changping the situation was critical; if the commander was muddle-headed and blindly trusted false intelligence, total army disaster was inevitable.", "es": "En el frente de Changping la situación era crítica; si el general estaba confundido y creía ciegamente informes falsos, la destrucción del ejército era ineludible."}, {"id": "#2", "hanzi": "在这个关乎企业未来生死的重大投资决策上，董事会绝对不能犯糊涂，必须进行周密调研。", "pinyin": "Zài zhè ge guānhū qǐyè wèilái shēngsǐ de zhòngdà tóuzī juécè shang, dǒngshìhuì juéduì bù néng fàn hútu, bìxū jìnxíng zhōumì diàoyán.", "en": "On this major investment decision concerning the company's survival, the board must never be foolishly muddled; rigorous research is imperative.", "es": "En esta crucial decisión de inversión para el porvenir corporativo, la junta directiva no debe cometer torpezas; es indispensable investigar a fondo."}], "collocations": [{"hanzi": "犯糊涂", "en": "make a foolish blunder / act muddle-headed"}, {"hanzi": "脑子糊涂", "en": "confused in thought / muddled mind"}, {"hanzi": "一时糊涂", "en": "momentary lapse of reason"}, {"hanzi": "装糊涂", "en": "feign ignorance / play dumb"}, {"hanzi": "稀里糊涂", "en": "careless and confused / in a muddle"}, {"hanzi": "糊涂账", "en": "chaotic accounts / messy situation"}], "idioms": [{"hanzi": "难得糊涂", "pinyin": "nán dé hú tu", "meaning_en": "where ignorance is bliss; blessed carelessness in small matters"}, {"hanzi": "一塌糊涂", "pinyin": "yī tà hú tu", "meaning_en": "in an awful mess; in complete shambles"}, {"hanzi": "糊里糊涂", "pinyin": "hú li hú tu", "meaning_en": "dazed and muddled; completely confused"}, {"hanzi": "不省人事", "pinyin": "bù xǐng rén shì", "meaning_en": "fall unconscious; insensible to surroundings"}], "character_decomposition": [{"character": "糊", "pinyin": "hú", "meaning_en": "paste; porridge; stick together; blur", "meaning_es": "pasta; engrudo; pegar; nublar", "radical": "米", "radical_meaning_en": "rice", "meaning_component": "米 (rice porridge / sticky cereal paste)", "sound_component": "胡 (hú)", "stroke_count": "15", "composition_type": "左右结构", "etymology_and_mnemonic": "Boiling down rice 米 into sticky opaque porridge 胡 that clouds transparency; signifies blurred opacity.", "visual_mnemonic_story_en": "Sticky rice paste (米) spread thick (胡), blurring all clarity (糊).", "visual_mnemonic_story_es": "Una pasta espesa de arroz (米) que al untarse (胡) nubla la visión de todo (糊).", "tone_mnemonic_anchor": "35", "cangjie": "FDJRB", "traditional": "糊"}, {"character": "涂", "pinyin": "tu", "meaning_en": "smear; daub; mud; erase; route", "meaning_es": "untar; embadurnar; lodo; borrar", "radical": "氵", "radical_meaning_en": "water", "meaning_component": "氵 (water / muddy sludge) + 余 (surplus)", "sound_component": "余 (yú)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Water 氵 mixed with wet muddy silt smeared across writing to blot it out; signifies coating or confusion.", "visual_mnemonic_story_en": "Wet sludge (氵) smeared over clean characters (余) until they become indistinguishable (涂).", "visual_mnemonic_story_es": "Lodo acuoso (氵) embadurnado sobre letras limpias (余) hasta borrarlas por completo (涂).", "tone_mnemonic_anchor": "neutral", "cangjie": "EOMD", "traditional": "塗"}], "extended_reading_passages": [{"id": "#1", "hanzi": "古来用兵最忌主帅头脑糊涂。赵括自幼熟读兵法，却缺乏实战临机应变的智慧。在长平阵前，面对白起佯装退却的诱敌战术，他头脑糊涂、轻率追击，将四十万精锐送入重围，千古遗恨。", "pinyin": "Gǔlái yòngbīng zuì jì zhǔshuài tóunǎo hútu. Zhào Kuò zìyòu shúdú bīngfǎ, què quēfá shízhàn línjī-yìngbiàn de zhìhuì. Zài Chángpíng zhènqián, miànduì Bái Qǐ yángzhuāng tuìquè de yòudí zhànshù, tā tóunǎo hútu, qīngshuài zhuījī, jiāng sìshí wàn jīngruì sòngrù zhòngwéi, qiāngǔ yíhèn.", "en": "In military history, nothing was more fatal than a commander being muddle-headed. Zhao Kuo had memorized tactics from childhood but lacked adaptive wisdom. Lured by Bai Qi's feigned retreat, his muddled thinking led 400,000 elite troops into total encirclement.", "es": "En la historia bélica nada fue más nefasto que un general confuso. Zhao Kuo dominaba la teoría pero carecía de agilidad práctica. Ante la falsa retirada de Bai Qi, su juicio nublado lanzó a 400.000 soldados a un cerco mortal."}, {"id": "#2", "hanzi": "清代书画家郑板桥题写的“难得糊涂”，向来被奉为人际交往的达观境界。然而为人处世的“糊涂”，是指在非关根本原则的微小私利上不予锱铢必较，在面临国家大义与是非抉择时，心智则须如明镜般洞察秋毫。", "pinyin": "Qīngdài shūhuàjiā Zhèng Bǎnqiáo tíxiě de 'nándé hútu', xiànglái bèi fèng wéi rénjì jiāowǎng de dáguān jìngjiè. Rán'ér wéirén chǔshì de 'hútu', shì zhǐ zài fēiguān gēnběn yuánzé de wēixiǎo sīlì shang bù yǔ zīzhū-bìjiào, zài miànlín guójiā dàyì yǔ shìfēi juézé shí, xīnjì zé xū rú míngjìng bān dòngchá-qiūháo.", "en": "The famous motto 'where ignorance is bliss' by Zheng Banqiao has long been praised as philosophical detachment. Yet this conscious tolerance applies only to petty personal gains; in confronting major principles and virtue, one's mind must remain crystal clear.", "es": "El lema 'dichosa confusión' de Zheng Banqiao siempre ha sido admirado como sabiduría vital. Sin embargo, esa benevolencia solo atañe a pequeñas minucias personales; ante los principios éticos y el bien común, la mente debe conservar una lucidez impecable."}]}, {"meanings_summary": {"en": "the Christian Era; Common Era; A.D.", "es": "era cristiana; era común; d.C."}, "mnemonics_and_roots": {"composite_memory_hook_en": "The public (公) universally agreed upon a common starting epoch (元) for international calendar counting (公元).", "composite_memory_hook_es": "La comunidad pública mundial (公) fijó un origen común de partida (元) para fechar los siglos (公元).", "cultural_and_cognitive_roots": "Adopted universally to align international chronological frameworks from the birth of Christ across scientific records.", "tone_sandhi_and_pitch_modulation": "First tone to second tone: 'gōng yuán' (55-35). High level start rising smoothly in pitch."}, "semantic_boundary_contrasts": {"core_nuance": "公元 strictly refers to the international Common Era calendar standard used for numbering historical years.", "contrasts": [{"id": "1", "compared_word": "公元 vs. 纪元", "pinyin": "jìyuán", "analysis": "纪元 refers broadly to an epoch or transformative historical period, whereas 公元 specifically denotes the Common Era calendar."}, {"id": "2", "compared_word": "公元 vs. 公历", "pinyin": "gōnglì", "analysis": "公历 refers to the solar Gregorian calendar mechanism itself, while 公元 specifies year counting along that timeline."}, {"id": "3", "compared_word": "公元 vs. 年代", "pinyin": "niándài", "analysis": "年代 refers to decades or historic epochs (e.g., the 80s), whereas 公元 is the base coordinate benchmark."}]}, "traps_and_cognates": {"look_alikes": [{"character": "无", "pinyin": "wú", "meaning_en": "none; without", "distinction_note": "Extra stroke and bottom curvature"}, {"character": "天", "pinyin": "tiān", "meaning_en": "sky; day", "distinction_note": "Central line pierces through differently"}, {"character": "公", "pinyin": "gōng", "meaning_en": "public; fair", "distinction_note": "Radical 八 on top with 厶 below"}, {"character": "分", "pinyin": "fēn", "meaning_en": "divide; minute", "distinction_note": "Radical 八 on top with knife 刀 below"}], "etymological_cognates": [{"character": "纪元", "pinyin": "jìyuán", "gloss_en": "epoch; era"}, {"character": "元年", "pinyin": "yuánnián", "gloss_en": "first year of a reign or era"}, {"character": "元首", "pinyin": "yuánshǒu", "gloss_en": "head of state; sovereign"}, {"character": "公历", "pinyin": "gōnglì", "gloss_en": "solar / Gregorian calendar"}]}, "id": "32", "hanzi": "公元", "pinyin": "gōng yuán", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the international calendar system counting years from the traditionally estimated birth of Jesus Christ (CE / AD)", "definition_es": "cómputo cronológico internacional que cuenta los años a partir del nacimiento estimado de Jesucristo", "example_phrase": "公元前260年 (in 260 BC)"}], "example_sentences": [{"id": "#1", "hanzi": "著名的长平之战发生于公元前260年，它是中国战国时期规模最为庞大的决定性战役。", "pinyin": "Zhùmíng de Chángpíng zhī zhàn fāshēng yú gōngyuánqián 260 nián, tā shì Zhōngguó Zhànguó shíqī guīmó zuìwéi pángdà de juédìngxìng zhànyì.", "en": "The renowned Battle of Changping took place in 260 BC; it was the largest and most decisive campaign of China's Warring States era.", "es": "La célebre batalla de Changping ocurrió en el año 260 a.C.; fue la contienda decisiva de mayor envergadura del período de los Reinos Combatientes."}, {"id": "#2", "hanzi": "出土的青铜铭文经碳十四测定，证实该古城遗址始建于公元前十一世纪的西周初期。", "pinyin": "Chūtǔ de qīngtóng míngwén jīng tàn-shísì cèdìng, zhèngshí gāi gǔchéng yízhǐ shǐjiàn yú gōngyuánqián shíyī shìjì de Xī Zhōu chūqī.", "en": "Carbon-14 testing of the excavated bronze inscriptions confirmed the ancient city ruins date back to the early Western Zhou in the 11th century BC.", "es": "La datación por carbono 14 de las inscripciones de bronce desenterradas confirmó que la antigua ciudad data de principios de la dinastía Zhou Occidental en el siglo XI a.C."}], "collocations": [{"hanzi": "公元前", "en": "Before Christ (BC / BCE)"}, {"hanzi": "公元纪年", "en": "Christian Era dating system"}, {"hanzi": "进入公元", "en": "enter the Common Era"}, {"hanzi": "公元元年", "en": "the year 1 AD"}, {"hanzi": "公元初期", "en": "early Common Era"}, {"hanzi": "公元纪元", "en": "Common Era calendar"}], "idioms": [{"hanzi": "千秋万代", "pinyin": "qiān qiū wàn dài", "meaning_en": "throughout thousands of autumns and myriad generations; for endless generations"}, {"hanzi": "历久弥新", "pinyin": "lì jiǔ mí xīn", "meaning_en": "remain fresh and vibrant with the passage of time"}, {"hanzi": "年深日久", "pinyin": "nián shēn rì jiǔ", "meaning_en": "over prolonged years and days; over a very long span of time"}, {"hanzi": "旷古绝伦", "pinyin": "kuàng gǔ jué lún", "meaning_en": "unmatched through all antiquity; unsurpassed in history"}], "character_decomposition": [{"character": "公", "pinyin": "gōng", "meaning_en": "public; universal; fair; male", "meaning_es": "público; universal; imparcial; masculino", "radical": "八", "radical_meaning_en": "eight / divide", "meaning_component": "八 (divide outward / open share) + 厶 (private)", "sound_component": "公 (gōng)", "stroke_count": "4", "composition_type": "上下结构", "etymology_and_mnemonic": "Distributing private 厶 resources openly 八 among all people; signifies public, common, and universal.", "visual_mnemonic_story_en": "Dividing (八) private goods (厶) to share publicly with everyone (公).", "visual_mnemonic_story_es": "Repartir abiertamente (八) lo privado (厶) para beneficio público de todos (公).", "tone_mnemonic_anchor": "55", "cangjie": "CI", "traditional": "公"}, {"character": "元", "pinyin": "yuán", "meaning_en": "first; primary; origin; unit", "meaning_es": "primero; primario; origen; unidad", "radical": "儿", "radical_meaning_en": "human legs", "meaning_component": "一 (supreme origin) + 兀/儿 (human head standing upright)", "sound_component": "元 (yuán)", "stroke_count": "4", "composition_type": "上下结构", "etymology_and_mnemonic": "The head 兀 crowned above the human body; denotes primary beginning, the source, and epoch.", "visual_mnemonic_story_en": "The head crowned atop the human figure (儿), representing the original beginning of time (元).", "visual_mnemonic_story_es": "La cabeza sobre la figura humana (儿), símbolo del origen primero y fuente primordial (元).", "tone_mnemonic_anchor": "35", "cangjie": "MMU", "traditional": "元"}], "extended_reading_passages": [{"id": "#1", "hanzi": "公元前260年，秦赵两国在长平爆发了震动天下的战略决战。这场战役彻底摧毁了赵国的军事主力，为秦国最终实现天下一统奠定了决定性基础，成为公元前中国古代史上的重要分水岭。", "pinyin": "Gōngyuánqián 260 nián, Qín Zhào liǎng guó zài Chángpíng bàofā le zhèndòng tiānxià de zhànlüè juézhàn. Zhè chǎng zhànyì chèdǐ cuīhuǐ le Zhàoguó de jūnshì zhǔlì, wèi Qínguó zuìzhōng shíxiàn tiānxià yītǒng diàndìng le juédìngxìng jīchǔ, chéngwéi gōngyuánqián Zhōngguó gǔdài shǐ shang de zhòngyào fēnshuǐlǐng.", "en": "In 260 BC, Qin and Zhao waged an earth-shattering strategic showdown at Changping. This battle destroyed Zhao's main military forces, laying the foundation for Qin's eventual unification of China as a watershed in ancient history.", "es": "En el 260 a.C., los reinos de Qin y Zhao libraron un duelo decisivo en Changping. La batalla quebrantó el ejército de Zhao y cimentó la unificación imperial de Qin, marcando un hito en la historia china antes de nuestra era."}, {"id": "#2", "hanzi": "在古代漫长的历史长河中，世界各文明均沿用各自独立的朝代纪年法则。进入近现代后，以公元为基准的通用纪年体系逐渐普及全球，极大便利了不同国家开展跨国商贸、学术交流与历史文献对照。", "pinyin": "Zài gǔdài màncháng de lìshǐ chánghé zhōng, shìjiè gè wénmíng jūn yányòng gèzì dúlì de cháodài jìnián fǎzé. Jìnrù jìnxiàndài hòu, yǐ gōngyuán wéi jīzhǔn de tōngyòng jìnián tǐxì zhújiàn pǔjí quánqiú, jídà biànlì le bùtóng guójiā kāizhǎn kuàguó shāngmào, xuéshù jiāoliú yǔ lìshǐ wénxiàn duìzhào.", "en": "Throughout ancient times, world civilizations kept independent dynastic calendars. In modern times, the Common Era chronological framework spread globally, facilitating cross-border trade, scholarship, and historical comparison.", "es": "Durante siglos las distintas civilizaciones emplearon cómputos dinásticos independientes. En la era moderna, el cómputo de la era común se consolidó universalmente, favoreciendo el comercio exterior, la ciencia y el cotejo histórico."}]}, {"meanings_summary": {"en": "blind; blindly; lacking foresight or objective analysis", "es": "ciego; ciegamente; sin criterio objetivo; precipitado"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When the eyes (目) lose sight (盲), one acts blindly (盲目) without seeing reality.", "composite_memory_hook_es": "Cuando los ojos (目) pierden la visión (盲), se actúa a ciegas (盲目) sin comprender la realidad.", "cultural_and_cognitive_roots": "Extends the physical inability to see to figurative intellectual and strategic blindness.", "tone_sandhi_and_pitch_modulation": "Second tone to fourth tone: 'máng mù' (35-51). Rising tone followed by decisive falling tone."}, "semantic_boundary_contrasts": {"core_nuance": "盲目 highlights acting without rational foresight, factual evidence, or objective analysis.", "contrasts": [{"id": "1", "compared_word": "盲目 vs. 冲动", "pinyin": "chōngdòng", "analysis": "冲动 indicates emotional turbulence causing impulsive actions, while 盲目 denotes lack of cognitive basis or clear direction."}, {"id": "2", "compared_word": "盲目 vs. 草率", "pinyin": "cǎoshuài", "analysis": "草率 stresses careless and rushed execution, whereas 盲目 stresses fundamental ignorance of circumstances."}, {"id": "3", "compared_word": "盲目 vs. 随便", "pinyin": "suíbiàn", "analysis": "随便 conveys informality or casual unconcern, while 盲目 carries severe consequences."}]}, "traps_and_cognates": {"look_alikes": [{"character": "育", "pinyin": "yù", "meaning_en": "educate; nurture", "distinction_note": "Radical 月 at bottom instead of 目"}, {"character": "忘", "pinyin": "wàng", "meaning_en": "forget", "distinction_note": "Heart 心 at bottom instead of 目"}, {"character": "日", "pinyin": "rì", "meaning_en": "sun; day", "distinction_note": "One horizontal bar inside instead of two"}, {"character": "自", "pinyin": "zì", "meaning_en": "self", "distinction_note": "Extra tick stroke on top"}], "etymological_cognates": [{"character": "盲区", "pinyin": "mángqū", "gloss_en": "blind spot"}, {"character": "色盲", "pinyin": "sèmáng", "gloss_en": "color blindness"}, {"character": "文盲", "pinyin": "wénmáng", "gloss_en": "illiterate"}, {"character": "注目", "pinyin": "zhùmù", "gloss_en": "gaze upon; fix attention"}]}, "id": "33", "hanzi": "盲目", "pinyin": "máng mù", "level": "HSK 5", "part_of_speech": "Adjective/Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "acting without clear perception, proper understanding, or rational planning", "definition_es": "que carece de discernimiento claro, base racional o criterio objetivo", "example_phrase": "盲目出击 (launch a blind assault)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括接任主帅后盲目自信，既不侦察敌情也不熟悉战地形势，便仓促下令全线出击。", "pinyin": "Zhào Kuò jiērèn zhǔshuài hòu mángmù zìxìn, jì bù zhēnchá díqíng yě bù shúxī zhàndì xíngshì, biàn cāngcù xiàlìng quánxiàn chūjī.", "en": "After taking command, Zhao Kuo was blindly confident; without scouting enemy dispositions or understanding terrain, he rashly launched an all-out attack.", "es": "Al asumir el mando, Zhao Kuo confió ciegamente; sin explorar las líneas enemigas ni el terreno, ordenó un asalto frontal a la carrera."}, {"id": "#2", "hanzi": "投资理财应当立足于严密的数据分析与风险评估，盲目跟风炒作往往会带来惨痛亏损。", "pinyin": "Tóuzī lǐcái yīngdāng lìzú yú yánmì de shùjù fēnxī yǔ fēngxiǎn pínggū, mángmù gēnfēng chǎozuò wǎngwǎng huì dàilái cǎntòng kuīsǔn.", "en": "Investing must be grounded in rigorous data analysis and risk appraisal; blindly jumping on speculative bandwagons often brings grievous losses.", "es": "Las inversiones deben fundamentarse en análisis de datos y cálculo de riesgos; seguir las modas a ciegas suele acarrear pérdidas devastadoras."}], "collocations": [{"hanzi": "盲目跟风", "en": "blindly follow the crowd / bandwagon"}, {"hanzi": "盲目自信", "en": "blind overconfidence"}, {"hanzi": "盲目乐观", "en": "blindly optimistic"}, {"hanzi": "盲目冲动", "en": "blind impulse"}, {"hanzi": "盲目行动", "en": "act blindly"}, {"hanzi": "盲目崇拜", "en": "blind worship / idolatry"}], "idioms": [{"hanzi": "盲人摸象", "pinyin": "máng rén mō xiàng", "meaning_en": "blind people feeling an elephant; mistake the part for the whole"}, {"hanzi": "盲人瞎马", "pinyin": "máng rén xiā mǎ", "meaning_en": "a blind person on a blind horse; rushing blindly into imminent catastrophe"}, {"hanzi": "有目共睹", "pinyin": "yǒu mù gòng dǔ", "meaning_en": "obvious to all with eyes; undeniable fact witnessed by everyone"}, {"hanzi": "掩耳盗铃", "pinyin": "yǎn ěr dào líng", "meaning_en": "cover one's ears while stealing a bell; self-deceit"}], "character_decomposition": [{"character": "盲", "pinyin": "máng", "meaning_en": "blind; visually impaired; unseeing", "meaning_es": "ciego; invidente; sin visión", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "目 (eye / vision) + 亡 (perish / lose)", "sound_component": "亡 (wáng)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Eyes 目 destroyed or extinguished 亡; signifies loss of sight or blindness.", "visual_mnemonic_story_en": "Loss (亡) of sight in the eye (目) renders one blind (盲).", "visual_mnemonic_story_es": "La pérdida (亡) de visión en el ojo (目) deja a la persona ciega (盲).", "tone_mnemonic_anchor": "35", "cangjie": "YVBU", "traditional": "盲"}, {"character": "目", "pinyin": "mù", "meaning_en": "eye; gaze; look; item; category", "meaning_es": "ojo; mirada; ver; renglón; partida", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "Pictograph of an eye with iris and pupils", "sound_component": "目 (mù)", "stroke_count": "5", "composition_type": "单一结构", "etymology_and_mnemonic": "A realistic pictograph of an open human eye showing the eyeball and pupil.", "visual_mnemonic_story_en": "An open eye (目) looking attentively at everything.", "visual_mnemonic_story_es": "Un ojo abierto (目) observando con fijeza el entorno.", "tone_mnemonic_anchor": "51", "cangjie": "BU", "traditional": "目"}], "extended_reading_passages": [{"id": "#1", "hanzi": "孙子兵法云：“不知彼而知己，一胜一负；不知彼不知己，每战必殆。”赵括轻视对手、盲目出兵，既未探清秦军主力虚实，也未明察山川险隘，结果正中白起埋伏，使赵国陷入万劫不复的深渊。", "pinyin": "Sūnzǐ bīngfǎ yún: 'Bù zhī bǐ ér zhī jǐ, yí shèng yí fù; bù zhī bǐ bù zhī jǐ, měi zhàn bì dài.' Zhào Kuò qīngshì duìshǒu, mángmù chūbīng, jì wèi tànqīng Qín jūn zhǔlì xūshí, yě wèi míngchá shānchuān xiǎn'ài, jiéguǒ zhèngzhòng Bái Qǐ máifu, shǐ Zhàoguó xiànrù wànjiébùfù de shēnyuān.", "en": "The Art of War states: 'Ignorant of the enemy but knowing yourself, victory is equal to defeat; ignorant of both, peril follows every clash.' Zhao Kuo marched out blindly, falling right into Bai Qi's ambush and ruining the state of Zhao.", "es": "El Arte de la Guerra dicta: 'Quien ignora al enemigo y a sí mismo sucumbe en cada lance.' Zhao Kuo avanzó a ciegas, cayendo en la celada de Bai Qi y arrojando a su reino al abismo de la aniquilación."}, {"id": "#2", "hanzi": "在当今海量信息交织的数字化时代，盲目跟风已成为大众心理的普遍隐患。无论是舆论场上的断章取义，还是资本市场的狂热泡沫，唯有保持独立严谨的批判精神，方能在喧嚣迷雾中守住理性底线。", "pinyin": "Zài dāngjīn hǎiliàng xìnxī jiāozhī de shùzìhuà shídài, mángmù gēnfēng yǐ chéngwéi dàzhòng xīnlǐ de pǔbiàn yǐnhuàn. Wúlùn shì yúlùnchǎng shang de duànzhāng-qǔyì, háishì zībǐn shìchǎng de kuángrè pàomò, wéiyǒu bǎochí dúlì yánjǐn de pīpàn jīngshén, fāng néng zài xuānxiāo míwù zhōng shǒuzhù lǐxìng dǐxiàn.", "en": "In today's digital era flooded with information, blind conformism is a widespread psychological trap. Whether in polarizing public discourse or asset bubbles, maintaining independent critical thinking is vital to preserving rationality.", "es": "En la era digital saturada de información, seguir la corriente a ciegas es un riesgo frecuente. Ya sea ante bulos o burbujas financieras, preservar el pensamiento crítico permite mantener la sensatez en medio del ruido."}]}, {"meanings_summary": {"en": "to look down upon; underestimate; belittle; slight", "es": "menospreciar; subestimar; desestimar; desdeñar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Viewing (视) someone as weighing nothing (轻) means underestimating or belittling them (轻视).", "composite_memory_hook_es": "Mirar (视) a alguien como si no tuviera peso alguno (轻) equivale a menospreciarlo (轻视).", "cultural_and_cognitive_roots": "Derives from contrasting weight (heavy vs. light), where 'heavy' equals respect and 'light' equals contempt.", "tone_sandhi_and_pitch_modulation": "First tone to fourth tone: 'qīng shì' (55-51). High level pitch dropping sharply on 'shì'."}, "semantic_boundary_contrasts": {"core_nuance": "轻视 refers to undervaluing, taking lightly, or condescending toward an opponent, duty, or risk.", "contrasts": [{"id": "1", "compared_word": "轻视 vs. 蔑视", "pinyin": "mièshì", "analysis": "蔑视 carries visceral moral disdain or scorn, whereas 轻视 primarily means underestimating strength or importance."}, {"id": "2", "compared_word": "轻视 vs. 忽视", "pinyin": "hūshì", "analysis": "忽视 means overlooking unintentionally due to negligence, while 轻视 involves conscious underestimation."}, {"id": "3", "compared_word": "轻视 vs. 歧视", "pinyin": "qíshì", "analysis": "歧视 denotes unfair prejudice against a demographic group, whereas 轻视 applies to specific opponents or tasks."}]}, "traps_and_cognates": {"look_alikes": [{"character": "经", "pinyin": "jīng", "meaning_en": "pass through; scripture", "distinction_note": "Radical 纟 on left instead of cart 车"}, {"character": "轮", "pinyin": "lún", "meaning_en": "wheel", "distinction_note": "Right side 仑 instead of 𢀖"}, {"character": "规", "pinyin": "guī", "meaning_en": "rule; regulate", "distinction_note": "Left side 夫 instead of 礻"}, {"character": "现", "pinyin": "xiàn", "meaning_en": "appear; present", "distinction_note": "Jade 王 on left instead of 礻"}], "etymological_cognates": [{"character": "轻蔑", "pinyin": "qīngmiè", "gloss_en": "scornful; contemptuous"}, {"character": "轻浮", "pinyin": "qīngfú", "gloss_en": "frivolous; flippant"}, {"character": "藐视", "pinyin": "miǎoshì", "gloss_en": "disdain; look down upon"}, {"character": "重视", "pinyin": "zhòngshì", "gloss_en": "attach importance to; value"}]}, "id": "34", "hanzi": "轻视", "pinyin": "qīng shì", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to treat someone or something with condescension, insufficient seriousness, or disdain", "definition_es": "tratar a alguien o algo con desdén, falta de seriedad o subestimación", "example_phrase": "轻视对手 (underestimate the opponent)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括自夸天下用兵莫能当，公然轻视身经百战的廉颇老将，结果在长平决战中酿成滔天大祸。", "pinyin": "Zhào Kuò zìkuā tiānxià yòngbīng mò néng dāng, gōngrán qīngshì shēnjīng-bǎizhàn de Lián Pō lǎojiàng, jiéguǒ zài Chángpíng juézhàn zhōng niàngchéng tāotiān dàhuò.", "en": "Zhao Kuo boasted none could match his military skills and openly belittled the veteran general Lian Po, causing a monumental catastrophe at Changping.", "es": "Zhao Kuo presumía de ser inigualable en la guerra y menospreció al veterano Lian Po, desatando una catástrofe sin igual en Changping."}, {"id": "#2", "hanzi": "在激烈的市场竞争中，任何成熟企业都绝不能轻视初创小微企业的创新活力与颠覆潜力。", "pinyin": "Zài jīliè de shìchǎng jìngzhēng zhōng, rènhé chéngshú qǐyè dōu jué bù néng qīngshì chūchuàng xiǎowēi qǐyè de chuàngxīn huólì yǔ diānfù qiánlì.", "en": "In fierce market rivalry, no established firm must ever underestimate the innovative vigor and disruptive potential of emerging startups.", "es": "En la encarnizada competencia mercantil, ninguna gran empresa debe desestimar el dinamismo innovador de las empresas emergentes."}], "collocations": [{"hanzi": "轻视对手", "en": "underestimate an opponent"}, {"hanzi": "轻视困难", "en": "make light of difficulties"}, {"hanzi": "受到轻视", "en": "be slighted / looked down upon"}, {"hanzi": "不容轻视", "en": "cannot be taken lightly"}, {"hanzi": "轻视经验", "en": "belittle practical experience"}, {"hanzi": "轻视细节", "en": "overlook minor details"}], "idioms": [{"hanzi": "骄兵必败", "pinyin": "jiāo bīng bì bài", "meaning_en": "an arrogant army is bound to suffer defeat"}, {"hanzi": "不可小觑", "pinyin": "bù kě xiǎo qù", "meaning_en": "not to be underestimated or taken lightly"}, {"hanzi": "等闲视之", "pinyin": "děng xián shì zhī", "meaning_en": "treat as ordinary and of no significance; dismiss lightly"}, {"hanzi": "自视甚高", "pinyin": "zì shì shèn gāo", "meaning_en": "think very highly of oneself; pretentious"}], "character_decomposition": [{"character": "轻", "pinyin": "qīng", "meaning_en": "light; slight; gentle; frivolous", "meaning_es": "ligero; leve; suave; frívolo", "radical": "车", "radical_meaning_en": "cart / chariot", "meaning_component": "车 (war chariot / weight) + 𢀖 (weaving shuttle flying swiftly)", "sound_component": "𢀖 (qīng)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "A light vehicle 车 darting effortlessly like a weaver's shuttle 𢀖; signifies light weight and lack of seriousness.", "visual_mnemonic_story_en": "A light wagon (车) gliding along swiftly without heavy burden (轻).", "visual_mnemonic_story_es": "Un carromato ligero (车) que avanza con soltura sin peso excesivo (轻).", "tone_mnemonic_anchor": "55", "cangjie": "KQNOM", "traditional": "輕"}, {"character": "视", "pinyin": "shì", "meaning_en": "look; gaze; inspect; regard", "meaning_es": "mirar; observar; inspeccionar; considerar", "radical": "礻", "radical_meaning_en": "spirit / display", "meaning_component": "礻/示 (reveal / examine) + 见 (see / behold)", "sound_component": "示 (shì)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "To fix one's eyes 见 upon an altar 礻 to observe closely; denotes inspecting, seeing, and regarding.", "visual_mnemonic_story_en": "Observing (见) signs shown before the altar (礻) to judge their importance (视).", "visual_mnemonic_story_es": "Mirar con atención (见) las señales sagradas (礻) para valorar su alcance (视).", "tone_mnemonic_anchor": "51", "cangjie": "IFHU", "traditional": "視"}], "extended_reading_passages": [{"id": "#1", "hanzi": "古兵法有言：“轻敌者必受制于人。”赵括熟读兵法典籍，自以为通晓天下战阵，因而极度轻视廉颇的固守策略与秦军将领的智谋。正是这种对强敌的轻视与狂傲，最终让他付出了全军覆没的惨烈代价。", "pinyin": "Gǔ bīngfǎ yǒu yán: 'Qīngdí zhě bì shòuzhì yú rén.' Zhào Kuò shúdú bīngfǎ diǎnjí, zìyǐwéi tōngxiǎo tiānxià zhànzhèn, yīn'ér jídù qīngshì Lián Pō de gùshǒu cèlüè yǔ Qín jūn jiànglǐng de zhìmóu. Zhèng shì zhè zhǒng duì qiángdí de qīngshì yǔ kuáng'ào, zuìzhōng ràng tā fùchū le quánjūn fùmò de cǎnliè dàijià.", "en": "Ancient military wisdom says: 'He who slights the enemy will be subdued by him.' Zhao Kuo believed he knew all warfare, belittling Lian Po's defense and Qin's cunning. This arrogance and underestimation of his foe cost him the annihilation of his army.", "es": "La doctrina militar antigua dictaba: 'Quien subestima al rival termina sometido.' Zhao Kuo creía saberlo todo y desdeñó la prudente defensa de Lian Po y el ingenio de Qin. Esa arrogancia le costó la total destrucción de sus tropas."}, {"id": "#2", "hanzi": "无论个人修养还是事业发展，都切忌轻视微小的积累与潜在的危险。千里之堤溃于蚁穴，很多看似无足轻重的隐患，往往因为受到人们的长期轻视而演变为难以挽回的灾难。保持谦逊谨慎，方为成事之道。", "pinyin": "Wúlùn gèrén xiūyǎng háishì shìyè fāzhǎn, dōu qièjì qīngshì wēixiǎo de jīlěi yǔ qiánzài de wēixiǎn. Qiānlǐ zhī dī kuì yú yǐxué, hěnduō kànsì wúzúqīngzhòng de yǐnhuàn, wǎngwǎng yīnwèi shòudào rénmen de chángqī qīngshì ér yǎnbiàn wéi nányǐ wǎnhuí de zāinàn. Bǎochí qiānxùn jǐnshèn, fāng wéi chéngshì zhī dào.", "en": "Whether in self-cultivation or career, never underestimate tiny habits or hidden hazards. A dike collapses from an ant hole; small risks become irreversible disasters when slighted. Humility and vigilance remain the keys to success.", "es": "En la superación personal y los negocios, jamás se deben menospreciar los pequeños detalles ni los peligros latentes. Grietas ignoradas destruyen diques; la humildad constante es el verdadero camino hacia el logro."}]}, {"meanings_summary": {"en": "scheme; plan; program; proposal", "es": "plan; proyecto; esquema; propuesta de solución"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A structured method (方) drafted on the wooden desk (案) forms an operational proposal (方案).", "composite_memory_hook_es": "El método riguroso (方) redactado sobre el pupitre (案) da origen al plan de acción (方案).", "cultural_and_cognitive_roots": "Originates from ancient statecraft dockets and strategies drafted on ministerial desks.", "tone_sandhi_and_pitch_modulation": "First tone to fourth tone: 'fāng àn' (55-51). High level pitch followed by falling pitch with clear apostrophe syllable break."}, "semantic_boundary_contrasts": {"core_nuance": "方案 denotes a comprehensive, systematic, and concrete blueprint tailored to solve an explicit problem.", "contrasts": [{"id": "1", "compared_word": "方案 vs. 计划", "pinyin": "jìhuà", "analysis": "计划 is broader, emphasizing timeline and agenda, whereas 方案 emphasizes actionable methodology and concrete design."}, {"id": "2", "compared_word": "方案 vs. 策略", "pinyin": "cèlüè", "analysis": "策略 emphasizes high-level tactical maneuvers, whereas 方案 is the complete operational document."}, {"id": "3", "compared_word": "方案 vs. 政策", "pinyin": "zhèngcè", "analysis": "政策 indicates overarching government or corporate guidelines, while 方案 is execution-level design."}]}, "traps_and_cognates": {"look_alikes": [{"character": "按", "pinyin": "àn", "meaning_en": "press; according to", "distinction_note": "Hand 扌 on left of 安 instead of 木 below"}, {"character": "安", "pinyin": "ān", "meaning_en": "peaceful; safe", "distinction_note": "No wood 木 radical below"}, {"character": "芳", "pinyin": "fāng", "meaning_en": "fragrant", "distinction_note": "Grass 艹 radical on top of 方"}, {"character": "仿", "pinyin": "fǎng", "meaning_en": "imitate", "distinction_note": "Person 亻 on left of 方"}], "etymological_cognates": [{"character": "档案", "pinyin": "dàng'àn", "gloss_en": "archives; official files"}, {"character": "草案", "pinyin": "cǎo'àn", "gloss_en": "draft proposal"}, {"character": "破案", "pinyin": "pò'àn", "gloss_en": "solve or crack a criminal case"}, {"character": "方法", "pinyin": "fāngfǎ", "gloss_en": "method; manner"}]}, "id": "35", "hanzi": "方案", "pinyin": "fāng àn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a systematically formulated program, method, or proposal designed to accomplish a specific objective", "definition_es": "programa, método o propuesta sistemática diseñada para resolver un problema o alcanzar un objetivo", "example_phrase": "制定作战方案 (formulate an operational battle plan)"}], "example_sentences": [{"id": "#1", "hanzi": "秦军将领白起在战前周密勘察长平地形，精心制定了诱敌深入与分割包围的作战方案。", "pinyin": "Qín jūn jiànglǐng Bái Qǐ zài zhànqián zhōumì kānchá Chángpíng dìxíng, jīngxīn zhìdìng le yòudí shēnrù yǔ fēn’gē bāowéi de zuòzhàn fāng'àn.", "en": "Before the clash, Qin general Bai Qi meticulously scouted the terrain of Changping and formulated an operational plan to lure the enemy deep and encircle them.", "es": "Antes de la batalla, el general Bai Qi de Qin reconoció minuciosamente el terreno y diseñó un plan de operaciones para atraer al enemigo y cercarlo."}, {"id": "#2", "hanzi": "工程师团队夜以继日地攻克技术难关，最终拿出了一套兼顾施工安全与成本控制的改造方案。", "pinyin": "Gōngchéngshī tuánduì yèyǐjìrì de gōngkè jìshù nánguān, zuìzhōng náchū le yí tào jiāngù shīgōng ānquán yǔ chéngběn kòngzhì de gǎizào fāng'àn.", "en": "The engineering team worked around the clock on technical hurdles and delivered a renovation proposal balancing safety and budget.", "es": "El equipo de ingenieros resolvió día y noche las dificultades técnicas y presentó una propuesta de remodelación que equilibra seguridad y costes."}], "collocations": [{"hanzi": "制定方案", "en": "formulate a plan / proposal"}, {"hanzi": "实施方案", "en": "implement a plan"}, {"hanzi": "替代方案", "en": "alternative proposal / plan B"}, {"hanzi": "优化方案", "en": "optimize a proposal"}, {"hanzi": "解决方案", "en": "solution scheme"}, {"hanzi": "设计方案", "en": "design proposal"}], "idioms": [{"hanzi": "谋定后动", "pinyin": "móu dìng hòu dòng", "meaning_en": "plan thoroughly before taking action"}, {"hanzi": "运筹帷幄", "pinyin": "yùn chóu wéi wò", "meaning_en": "devise strategies in the command tent; masterminding operations"}, {"hanzi": "足智多谋", "pinyin": "zú zhì duō móu", "meaning_en": "wise and full of stratagems; resourceful"}, {"hanzi": "深思熟虑", "pinyin": "shēn sī shú lǜ", "meaning_en": "mature and deep consideration; carefully weighed"}], "character_decomposition": [{"character": "方", "pinyin": "fāng", "meaning_en": "square; direction; side; method; prescription", "meaning_es": "cuadrado; dirección; lado; método; fórmula", "radical": "方", "radical_meaning_en": "square / direction", "meaning_component": "Pictograph of two boats lashed together moving forward or a carpenter's square", "sound_component": "方 (fāng)", "stroke_count": "4", "composition_type": "单一结构", "etymology_and_mnemonic": "Denotes standard rectangular orientation, orderly directions, and systematic formulas or recipes.", "visual_mnemonic_story_en": "A carpenter's square measuring directions and prescribing orderly formulas (方).", "visual_mnemonic_story_es": "Una escuadra de carpintero que mide rumbos y pauta fórmulas exactas (方).", "tone_mnemonic_anchor": "55", "cangjie": "YHS", "traditional": "方"}, {"character": "案", "pinyin": "àn", "meaning_en": "desk; table; record; legal case; proposal", "meaning_es": "mesa; pupitre; expediente; caso; propuesta", "radical": "木", "radical_meaning_en": "wood", "meaning_component": "木 (wooden desk / table) + 安 (peaceful / rest)", "sound_component": "安 (ān)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "A wooden table 木 upon which documents rest peacefully 安 for judicial review or formal planning.", "visual_mnemonic_story_en": "Official documents laid securely (安) on the magistrate's wooden desk (木) for scrutiny (案).", "visual_mnemonic_story_es": "Documentos oficiales descansando en calma (安) sobre el escritorio de madera (木) para su estudio (案).", "tone_mnemonic_anchor": "51", "cangjie": "JVD", "traditional": "案"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在古代重大战事中，作战方案的优劣直接决定三军将士的生死存亡。秦国名将白起针对赵括急躁冒进的性格弱点，精心设计了诱敌入伏的作战方案，最终成功斩断赵军后路，一举取得了长平之战的彻底胜利。", "pinyin": "Zài gǔdài zhòngdà zhànshì zhōng, zuòzhàn fāng'àn de yōuliè zhíjiē juédìng sānjūn jiàngshì de shēngsǐ-cúnwáng. Qínguó míngjiàng Bái Qǐ zhēnduì Zhào Kuò jízào-màojìn de xìnggé ruòdiǎn, jīngxīn shèjì le yòudí-rùfú de zuòzhàn fāng'àn, zuìzhōng chénggōng zhǎnduàn Zhào jūn hòulù, yìjǔ qǔdé le Chángpíng zhī zhàn de chèdǐ shènglì.", "en": "In ancient warfare, the quality of operational plans determined survival. Qin general Bai Qi exploited Zhao Kuo's rashness, formulating a trap plan that cut Zhao's retreat and delivered total victory at Changping.", "es": "En la guerra antigua, la calidad de los planes decidía la vida o la muerte. Bai Qi se aprovechó de la temeridad de Zhao Kuo y diseñó un plan de emboscada que cortó la retirada enemiga, alcanzando la victoria total en Changping."}, {"id": "#2", "hanzi": "现代企业在启动任何重大项目之前，都必须经历多轮严密的可行性方案论证。一套优秀的方案不仅要有开阔前瞻的战略构想，更要具备严谨细致的操作步骤和风险应急预案，从而确保各项业务平稳有序落地。", "pinyin": "Xiàndài qǐyè zài qǐdòng rènhé zhòngdà xiàngmù zhīqián, dōu bìxū jīnglì duō lún yánmì de kěxíngxìng fāng'àn lùnzhèng. Yí tào yōuxiù de fāng'àn bùjǐn yào yǒu kāikuò qiánzhān de zhànlüè gòuxiǎng, gèng yào jùbèi yánjǐn xìzhì de cāozuò bùzhòu yǔ fēngxiǎn yīngjí yù'àn, cóng'ér quèbǎo gè xiàng yèwù píngwěn yǒuxù luòdì.", "en": "Before launching projects, modern enterprises must vet feasibility schemes through rigorous evaluations. An outstanding proposal combines strategic foresight with concrete operational steps and risk contingencies.", "es": "Antes de iniciar proyectos, las empresas modernas someten sus propuestas a rigurosos estudios de viabilidad. Un buen plan aúna visión estratégica con pasos minuciosos y contingencias de riesgo para garantizar su éxito."}]}, {"meanings_summary": {"en": "to attack; assault; go on the offensive", "es": "atacar; asaltar; pasar a la ofensiva; embestir"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Advancing forward (进) and striking with weapons (攻) forms a decisive offensive assault (进攻).", "composite_memory_hook_es": "Avanzar con presteza (进) y asestar golpes (攻) conforma una ofensiva decidida (进攻).", "cultural_and_cognitive_roots": "Represents the dynamic movement and assault maneuvers in classical Chinese military treatises.", "tone_sandhi_and_pitch_modulation": "Fourth tone to first tone: 'jìn gōng' (51-55). Sharp falling drop into sustained high tone."}, "semantic_boundary_contrasts": {"core_nuance": "进攻 specifically denotes dynamic tactical advancement and armed push toward an opponent or fortress.", "contrasts": [{"id": "1", "compared_word": "进攻 vs. 攻击", "pinyin": "gōngjī", "analysis": "攻击 can refer to physical attacks as well as verbal or cyber attacks, while 进攻 focuses on strategic military offensive pushes."}, {"id": "2", "compared_word": "进攻 vs. 侵略", "pinyin": "qīnlüè", "analysis": "侵略 carries the explicit illicit sense of violating sovereign borders, unlike general military 进攻."}, {"id": "3", "compared_word": "进攻 vs. 突击", "pinyin": "tūjī", "analysis": "突击 denotes a sudden, concentrated short-range raid, whereas 进攻 encompasses wide sustained campaigns."}]}, "traps_and_cognates": {"look_alikes": [{"character": "功", "pinyin": "gōng", "meaning_en": "merit; achievement", "distinction_note": "Radical 力 on right instead of strike 攵"}, {"character": "巧", "pinyin": "qiǎo", "meaning_en": "skillful; clever", "distinction_note": "Radical 工 on left with 丂 on right"}, {"character": "近", "pinyin": "jìn", "meaning_en": "near; close", "distinction_note": "Inside component is axe 斤 instead of 井"}, {"character": "退", "pinyin": "tuì", "meaning_en": "retreat; withdraw", "distinction_note": "Antonym; 艮 inside radical 辶"}], "etymological_cognates": [{"character": "攻击", "pinyin": "gōngjī", "gloss_en": "assault; attack verbally"}, {"character": "攻克", "pinyin": "gōngkè", "gloss_en": "capture; overcome"}, {"character": "主攻", "pinyin": "zhǔgōng", "gloss_en": "main offensive direction"}, {"character": "进攻方", "pinyin": "jìngōngfāng", "gloss_en": "offensive side"}]}, "id": "36", "hanzi": "进攻", "pinyin": "jìn gōng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to take offensive armed action or tactical advance against an enemy, opposing line, or objective", "definition_es": "iniciar acciones de ataque o avance ofensivo contra el enemigo, su frente o una posición", "example_phrase": "发起猛烈进攻 (launch a ferocious offensive)"}], "example_sentences": [{"id": "#1", "hanzi": "赵括轻率改变廉颇坚守阵地的既定战略，贸然下令数十万赵军向秦军阵地发动全面进攻。", "pinyin": "Zhào Kuò qīngshuài gǎibiàn Lián Pō jiānshǒu zhèndì de jìdìng zhànlüè, màorán xiàlìng shùshí wàn Zhào jūn xiàng Qín jūn zhèndì fādòng quánmiàn jìngōng.", "en": "Zhao Kuo rashly altered Lian Po's established defensive strategy and commanded hundreds of thousands of Zhao troops to launch a total offensive against Qin positions.", "es": "Zhao Kuo alteró temerariamente la estrategia defensiva de Lian Po y ordenó a miles de soldados de Zhao lanzar una ofensiva frontal contra Qin."}, {"id": "#2", "hanzi": "在决赛最后阶段，处于劣势的球队全力组织进攻，终于在伤停补时阶段打进了扳平比分的关键一球。", "pinyin": "Zài juésài zuìhòu jiēduàn, chǔyú lièshì de qiúduì quánlì zǔzhī jìngōng, zhōngyú zài shāngtíng-bǔshí jiēduàn dǎjìn le bānpíng bǐfēn de guānjiàn yì qiú.", "en": "In the final stage of the match, the trailing squad mobilized all-out attacks and scored a crucial equalizer during stoppage time.", "es": "En el tramo final del partido, el equipo en desventaja organizó un ataque total y marcó el gol del empate en el tiempo añadido."}], "collocations": [{"hanzi": "发起进攻", "en": "launch an attack / offensive"}, {"hanzi": "全面进攻", "en": "general / all-out offensive"}, {"hanzi": "猛烈进攻", "en": "fierce assault"}, {"hanzi": "组织进攻", "en": "organize an offensive"}, {"hanzi": "抵御进攻", "en": "repel an offensive"}, {"hanzi": "转入进攻", "en": "shift into offensive"}], "idioms": [{"hanzi": "攻守兼备", "pinyin": "gōng shǒu jiān bèi", "meaning_en": "equally adept at both offense and defense"}, {"hanzi": "攻其不备", "pinyin": "gōng qí bù bèi", "meaning_en": "attack where the enemy is least prepared; take by surprise"}, {"hanzi": "反戈一击", "pinyin": "fǎn gē yī jī", "meaning_en": "turn one's weapon around to strike back; counterattack"}, {"hanzi": "无懈可击", "pinyin": "wú xiè kě jī", "meaning_en": "leaving no flaw or loophole for attack; invulnerable"}], "character_decomposition": [{"character": "进", "pinyin": "jìn", "meaning_en": "advance; enter; move forward; progress", "meaning_es": "avanzar; entrar; progresar; marchar hacia adelante", "radical": "辶", "radical_meaning_en": "walk / movement", "meaning_component": "辶 (walk / movement forward) + 井 (neat well boundary)", "sound_component": "井 (jǐng)", "stroke_count": "7", "composition_type": "半包围结构", "etymology_and_mnemonic": "Moving forward 辶 with steady marching pace; signifies advancing into position.", "visual_mnemonic_story_en": "Marching forward steadily along the pathway (辶) to make progress (进).", "visual_mnemonic_story_es": "Marchar con firmeza a lo largo del camino (辶) para abrir paso hacia adelante (进).", "tone_mnemonic_anchor": "51", "cangjie": "YTT", "traditional": "進"}, {"character": "攻", "pinyin": "gōng", "meaning_en": "attack; assault; strike; study diligently", "meaning_es": "atacar; asaltar; golpear; dedicarse a fondo", "radical": "攵", "radical_meaning_en": "strike / tap", "meaning_component": "工 (carpenter's tool / labor) + 攵/攴 (hand holding a striking weapon)", "sound_component": "工 (gōng)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Holding a tool or weapon 攵 to pound and break enemy barriers 工; signifies attack and assault.", "visual_mnemonic_story_en": "Wielding a striking weapon (攵) with focused force (工) to breach enemy walls (攻).", "visual_mnemonic_story_es": "Empuñar un arma (攵) con ímpetu laborioso (工) para derribar las murallas rivales (攻).", "tone_mnemonic_anchor": "55", "cangjie": "MOK", "traditional": "攻"}], "extended_reading_passages": [{"id": "#1", "hanzi": "长平之战中，赵括自恃勇力，不听老将劝阻，盲目率军向秦军发动全线进攻。秦将白起故意伪装战败退却，引诱赵军长驱直入，随后派遣奇兵包抄后方，将进攻的赵军牢牢围困在崇山峻岭之间。", "pinyin": "Chángpíng zhī zhàn zhōng, Zhào Kuò zìshì-yǒnglì, bù tīng lǎojiàng quànzǔ, mángmù shuài jūn xiàng Qín jūn fādòng quánxiàn jìngōng. Qín jiàng Bái Qǐ gùyì wěizhuāng zhànbài tuìquè, yǐnyòu Zhào jūn chángqū-zhírù, suíhòu pàiqiǎn qíbīng bāochāo hòufāng, jiāng jìngōng de Zhào jūn láoláo wéikùn zài chóngshān-jùnlǐng zhījiān.", "en": "At Changping, relying on rash bravado, Zhao Kuo launched an all-out offensive against Qin. Bai Qi feigned retreat to lure Zhao deep, then dispatched cavalry to circle behind, encircling the attacking Zhao army in rugged mountains.", "es": "En Changping, cegado por la temeridad, Zhao Kuo atacó frontalmente a Qin. Bai Qi fingió retirarse para atraer al rival; luego envió tropas que envolvieron la retaguardia, cercando al ejército atacante en las montañas."}, {"id": "#2", "hanzi": "体育竞技与军事战略有着异曲同工之妙。高水平的球队从不盲目发动无序进攻，而是通过严密的防守稳住阵脚，在耐心传导中寻觅对手防线的破绽，在关键时刻发起致命进攻，从而一举锁定胜局。", "pinyin": "Tǐyù jìngjì yǔ jūnshì zhànlüè yǒu zhe yìqǔ-tónggōng zhī miào. Gāo shuǐpíng de qiúduì cóng bù mángmù fādòng wúxù jìngōng, ér shì tōngguò yánmì de fángshǒu wěnzhù zhènjiǎo, zài nàixīn chuándǎo zhōng xúnmì duìshǒu fángxiàn de pòzhàn, zài guānjiàn shíkè fāqǐ zhìmìng jìngōng, cóng'ér yìjǔ suǒdìng shèngjú.", "en": "Sports competition shares deep parallels with military strategy. Elite teams never launch chaotic attacks; they stabilize defense, patiently seek openings in the opponent's lines, and strike decisively to seal victory.", "es": "El deporte y la táctica militar comparten principios comunes. Los equipos de élite nunca atacan sin orden; consolidan su defensa, esperan fisuras en el rival y asestan ataques letales que aseguran la victoria final."}]}, {"meanings_summary": {"en": "precious; valuable; treasured", "es": "precioso; valioso; de gran valor; estimable"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Treasures housed under the roof (宝) backed by costly wealth (贵) are exceedingly precious (宝贵).", "composite_memory_hook_es": "Las gemas del tesoro (宝) respaldadas por caudales valiosos (贵) son sumamente preciadas (宝贵).", "cultural_and_cognitive_roots": "Combines domestic treasury jade with cowrie money, expanding to spiritual, intellectual, and temporal value.", "tone_sandhi_and_pitch_modulation": "Third tone to fourth tone: 'bǎo guì' (214-51). Half-third dip rising before sharp drop on 'guì'."}, "semantic_boundary_contrasts": {"core_nuance": "宝贵 highlights immense intrinsic or non-material utility, wisdom, lessons, or time.", "contrasts": [{"id": "1", "compared_word": "宝贵 vs. 珍贵", "pinyin": "zhēnguì", "analysis": "珍贵 leans toward emotional affection and rare physical articles, while 宝贵 emphasizes intrinsic functional and intellectual value."}, {"id": "2", "compared_word": "宝贵 vs. 昂贵", "pinyin": "ángguì", "analysis": "昂贵 refers strictly to high monetary price, whereas 宝贵 usually describes cherished non-material values."}, {"id": "3", "compared_word": "宝贵 vs. 名贵", "pinyin": "míngguì", "analysis": "名贵 describes famous luxury specimens (e.g. rare herbs or stones), whereas 宝贵 has broad spiritual application."}]}, "traps_and_cognates": {"look_alikes": [{"character": "实", "pinyin": "shí", "meaning_en": "solid; real; fruit", "distinction_note": "Head has 头 instead of jade 玉"}, {"character": "定", "pinyin": "dìng", "meaning_en": "settle; fix", "distinction_note": "Radical 宀 with 正/疋 below"}, {"character": "遗", "pinyin": "yí", "meaning_en": "lose; bequeath", "distinction_note": "Surrounded by walk radical 辶"}, {"character": "资", "pinyin": "zī", "meaning_en": "resources; capital", "distinction_note": "Top component is 次 instead of 𠀎"}], "etymological_cognates": [{"character": "珍贵", "pinyin": "zhēnguì", "gloss_en": "precious; invaluable"}, {"character": "宝贝", "pinyin": "bǎobèi", "gloss_en": "cherished treasure; baby"}, {"character": "宝藏", "pinyin": "bǎozàng", "gloss_en": "treasure trove"}, {"character": "贵重", "pinyin": "guìzhòng", "gloss_en": "valuable; costly"}]}, "id": "37", "hanzi": "宝贵", "pinyin": "bǎo guì", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "having great value, worth, or significance; extremely precious", "definition_es": "que tiene un gran valor, estima o utilidad trascendente; sumamente preciado", "example_phrase": "宝贵的经验 (precious experience)"}], "example_sentences": [{"id": "#1", "hanzi": "老将廉颇在数十载沙场征战中积累了极其宝贵的实战经验，这些远非书本空谈所能比拟。", "pinyin": "Lǎojiàng Lián Pō zài shùshí zǎi shāchǎng zhēngzhàn zhōng jīlěi le jíqí bǎoguì de shízhàn jīngyàn, zhèxiē yuǎnfēi shūběn kōngtán suǒ néng bǐnǐ.", "en": "Veteran general Lian Po accumulated exceedingly precious combat experience over decades of campaigns, which empty book theories could never rival.", "es": "El veterano general Lian Po atesoró una valiosísima experiencia en décadas de combate, inalcanzable para la vana teoría de los libros."}, {"id": "#2", "hanzi": "在快节奏的现代生活中，能够专心陪伴家人共享天伦之乐，是人生中最宝贵的幸福时刻。", "pinyin": "Zài kuài jiézòu de xiàndài shēnghuó zhōng, nénggòu zhuānxīn péibàn jiārén gòngxiǎng tiānlún zhī lè, shì rénshēng zhōng zuì bǎoguì de xìngfú shíkè.", "en": "In the fast pace of modern life, being able to focus on accompanying family and enjoying harmony is life's most precious happiness.", "es": "En la ajetreada vida moderna, poder dedicar tiempo a la familia y gozar de su afecto constituye el momento más valioso de la existencia."}], "collocations": [{"hanzi": "宝贵经验", "en": "valuable / precious experience"}, {"hanzi": "宝贵财富", "en": "precious wealth / asset"}, {"hanzi": "宝贵时间", "en": "valuable time"}, {"hanzi": "宝贵生命", "en": "precious life"}, {"hanzi": "宝贵意见", "en": "valuable feedback / advice"}, {"hanzi": "极为宝贵", "en": "extremely precious"}], "idioms": [{"hanzi": "分秒必争", "pinyin": "fēn miǎo bì zhēng", "meaning_en": "seize every minute and second; race against time"}, {"hanzi": "千金难买", "pinyin": "qiān jīn nán mǎi", "meaning_en": "priceless; cannot be bought even with a thousand gold coins"}, {"hanzi": "寸阴可惜", "pinyin": "cùn yīn kě xī", "meaning_en": "every inch of time is precious and should not be squandered"}, {"hanzi": "价值连城", "pinyin": "jià zhí lián chéng", "meaning_en": "worth several cities; invaluable treasure"}], "character_decomposition": [{"character": "宝", "pinyin": "bǎo", "meaning_en": "treasure; precious; jewel; precious object", "meaning_es": "tesoro; precioso; joya; objeto valioso", "radical": "宀", "radical_meaning_en": "roof / house", "meaning_component": "宀 (house / treasury) + 玉 (radiant jade gem)", "sound_component": "缶 (archaic sound in traditional 寶)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Precious jade stones 玉 treasured and safeguarded under the roof 宀 of the treasury; signifies jewel and treasure.", "visual_mnemonic_story_en": "Precious polished jade (玉) safeguarded safely under the roof (宀) as a treasure (宝).", "visual_mnemonic_story_es": "Una gema de jade (玉) custodiada bajo el tejado (宀) como un tesoro sagrado (宝).", "tone_mnemonic_anchor": "214", "cangjie": "JMI", "traditional": "寶"}, {"character": "贵", "pinyin": "guì", "meaning_en": "expensive; precious; noble; honor", "meaning_es": "caro; precioso; noble; honorable", "radical": "贝", "radical_meaning_en": "cowrie shell / currency", "meaning_component": "贝 (ancient shell currency) + 中/𠀎 (costly merchandise)", "sound_component": "臾/𠀎 (guì)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Goods backed by precious cowrie shell money 贝; denotes high value, nobility, and precious worth.", "visual_mnemonic_story_en": "Piles of rare shell money (贝) marking goods of highest noble value (贵).", "visual_mnemonic_story_es": "Montones de valiosas caracolas moneda (贝) que acreditan un alto valor y nobleza (贵).", "tone_mnemonic_anchor": "51", "cangjie": "LMBO", "traditional": "貴"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在瞬息万变的生死战局中，老将廉颇凭借几十年浴血奋战摸索出的防御经验，是赵国赖以抵御强秦最宝贵的军事财富。赵王因谣言将其撤换，白白葬送了扭转乾坤的宝贵时机，铸成历史悲剧。", "pinyin": "Zài shùnxī-wànbiàn de shēngsǐ zhànjú zhōng, lǎojiàng Lián Pō píngjiè jǐshí nián yùxuè-fènzhàn mōsuǒ chū de fángyù jīngyàn, shì Zhàoguó làiyǐ dǐyù qiáng Qín zuì bǎoguì de jūnshì cáifù. Zhào wáng yīn yáoyán jiāng qí chèhuàn, báibái zàngsòng le niǔzhuǎn qiánkūn de bǎoguì shíjī, zhùchéng lìshǐ bēijù.", "en": "In life-and-death warfare, Lian Po's defensive experience forged over decades was Zhao's most precious asset against Qin. Swayed by rumors, King of Zhao replaced him, squandering a precious opportunity and causing historic tragedy.", "es": "En la guerra despiadada, la experiencia defensiva de Lian Po era el tesoro militar más preciado de Zhao frente al invasor. El rey de Zhao creyó los rumores y lo relevó, desperdiciando una valiosa ocasión y sellando la tragedia."}, {"id": "#2", "hanzi": "光阴荏苒，日月如梭，时间是世间唯一无法逆转的宝贵资产。金钱耗尽尚有再度创造之机，青春年华一旦虚掷便永不复返。唯有懂得珍惜每一分宝贵光阴，脚踏实地钻研进取，方能铸就无悔的精彩人生。", "pinyin": "Guāngyīn-rěnrǎn, rìyuè-rúsuō, shíjiān shì shìjiān wéiyī wúfǎ nìzhuǎn de bǎoguì zīchǎn. Jīnqián hàojìn shàng yǒu zàidù chuàngzào zhī jī, qīngchūn niánhuá yídàn xūzhì biàn yǒng bù fùfǎn. Wéiyǒu dǒngdé zhēnxī měi yì fēn bǎoguì guāngyīn, jiǎotàshídì zuānyán jìnqǔ, fāng néng zhùjiù wúhuǐ de jīngcǎi rénshēng.", "en": "Time passes like a shuttle; it is the only non-renewable precious asset on earth. Lost money can be regained, but squandered youth never returns. Cherishing precious moments and striving forward creates a life without regrets.", "es": "El tiempo vuela sin freno y es el activo más valioso e irrecuperable de este mundo. El dinero gastado se puede volver a ganar, pero la juventud perdida no regresa jamás. Atesorar cada instante permite forjar una vida plena."}]}, {"meanings_summary": {"en": "to satirize; mock; sarcasm; irony", "es": "satirizar; burlarse de; ironía; sarcasmo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Words delivered obliquely like wind (讽) designed to prick like sharp thorns (刺) deliver biting satire (讽刺).", "composite_memory_hook_es": "Palabras que soplan como viento (讽) y pinchan como afiladas espinas (刺) crean la sátira (讽刺).", "cultural_and_cognitive_roots": "Rooted in classical poetic traditions (Feng) of remonstrating with emperors through subtle allegories.", "tone_sandhi_and_pitch_modulation": "Third tone to fourth tone: 'fěng cì' (214-51). Half-third dip rising before falling sharply on 'cì'."}, "semantic_boundary_contrasts": {"core_nuance": "讽刺 uses witty, ironic, or metaphoric critique to pierce and expose hypocrisy, vice, or incompetence.", "contrasts": [{"id": "1", "compared_word": "讽刺 vs. 嘲笑", "pinyin": "cháoxiào", "analysis": "嘲笑 denotes direct teasing or derisive laughter, whereas 讽刺 relies on artistic or literary irony with moral critique."}, {"id": "2", "compared_word": "讽刺 vs. 批评", "pinyin": "pīpíng", "analysis": "批评 is straightforward evaluation pointing out shortcomings, whereas 讽刺 conveys disapproval through irony and sting."}, {"id": "3", "compared_word": "讽刺 vs. 挖苦", "pinyin": "wāku", "analysis": "挖苦 refers to colloquial, petty barbs aimed at hurting someone's feelings, whereas 讽刺 often carries broader social critique."}]}, "traps_and_cognates": {"look_alikes": [{"character": "风", "pinyin": "fēng", "meaning_en": "wind; custom", "distinction_note": "No speech 讠 radical on left"}, {"character": "订", "pinyin": "dìng", "meaning_en": "book; subscribe", "distinction_note": "Right side is 丁 instead of 风"}, {"character": "枣", "pinyin": "zǎo", "meaning_en": "jujube; date", "distinction_note": "Double 朿 without knife radical 刂"}, {"character": "策", "pinyin": "cè", "meaning_en": "policy; strategy", "distinction_note": "Bamboo ⺮ radical on top"}], "etymological_cognates": [{"character": "讥讽", "pinyin": "jīfěng", "gloss_en": "taunt; deride; mock"}, {"character": "讽喻", "pinyin": "fěngyù", "gloss_en": "parable; moral allegory"}, {"character": "刺耳", "pinyin": "cì'ěr", "gloss_en": "grating; harsh on the ears"}, {"character": "刺激", "pinyin": "cìjī", "gloss_en": "stimulate; excite; provoke"}]}, "id": "38", "hanzi": "讽刺", "pinyin": "fěng cì", "level": "HSK 5", "part_of_speech": "Verb/Noun", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to criticize, ridicule, or mock through witty irony or caustic metaphor", "definition_es": "criticar, ridiculizar o censurar mediante ironía ingeniosa o metáfora mordaz", "example_phrase": "辛辣讽刺 (pungent satire)"}], "example_sentences": [{"id": "#1", "hanzi": "后世史学家常以“纸上谈兵”这一典故，深刻讽刺那些空谈高深理论而缺乏实践检验的夸夸其谈之辈。", "pinyin": "Hòushì shǐxuéjiā cháng yǐ 'zhǐshàng-tánbīng' zhè yí diǎngù, shēnkè fěngcì nàxiē kōngtán gāoshēn lǐlùn ér quēfá shíjiàn jiǎnyàn de kuākuā-qítán zhī bèi.", "en": "Later historians frequently cited the idiom 'armchair strategy' to sharply satirize those braggarts who preach lofty theories without practical testing.", "es": "Los historiadores posteriores utilizaron el modismo 'estrategia en el papel' para satirizar a quienes predican elevadas teorías sin haberlas puesto a prueba en la realidad."}, {"id": "#2", "hanzi": "这部文学杰作运用了极其辛辣的幽默讽刺手法，无情揭示了当年封建官僚体制的虚伪与腐朽。", "pinyin": "Zhè bù wénxué jiézuò yùnyòng le jíqí xīnlà de yōumò fěngcì shǒufǎ, wúqíng jiēshì le dāngnián fēngjiàn guānliáo tǐzhì de xūwěi yǔ fǔxiǔ.", "en": "This literary masterpiece employed pungent humorous satire, ruthlessly exposing the hypocrisy and decay of the feudal bureaucratic system.", "es": "Esta obra maestra literaria empleó una sátira sumamente mordaz, desnudando sin piedad la hipocresía y corrupción de la burocracia feudal."}], "collocations": [{"hanzi": "辛辣讽刺", "en": "pungent / biting satire"}, {"hanzi": "充满讽刺", "en": "full of irony / satire"}, {"hanzi": "讽刺小说", "en": "satirical novel"}, {"hanzi": "讽刺意味", "en": "satirical undertone"}, {"hanzi": "加以讽刺", "en": "subject to ridicule / satirize"}, {"hanzi": "幽默讽刺", "en": "humorous irony"}], "idioms": [{"hanzi": "冷嘲热讽", "pinyin": "lěng cháo rè fěng", "meaning_en": "scoffing and jeering; cynical mockery and burning satire"}, {"hanzi": "指桑骂槐", "pinyin": "zhǐ sāng mà huái", "meaning_en": "point at the mulberry and scold the locust tree; criticize indirectly"}, {"hanzi": "拐弯抹角", "pinyin": "guǎi wān mò jiǎo", "meaning_en": "speak in circumlocutions; beat around the bush"}, {"hanzi": "尖酸刻薄", "pinyin": "jiān suān kè bó", "meaning_en": "sharp and biting; caustic and acerbic"}], "character_decomposition": [{"character": "讽", "pinyin": "fěng", "meaning_en": "satirize; mock; chant; recite", "meaning_es": "satirizar; burlarse de; recitar; censurar", "radical": "讠", "radical_meaning_en": "speech / words", "meaning_component": "讠 (speech / words) + 风 (wind / indirect influence)", "sound_component": "风 (fēng)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Spoken words 讠 delivered indirectly like gentle wind 风 to critique flaws; denotes indirect satire.", "visual_mnemonic_story_en": "Delivering spoken words (讠) like a sharp gust of wind (风) to criticize obliquely (讽).", "visual_mnemonic_story_es": "Pronunciar palabras (讠) como una ráfaga de viento (风) que censura indirectamente (讽).", "tone_mnemonic_anchor": "214", "cangjie": "IVHN", "traditional": "諷"}, {"character": "刺", "pinyin": "cì", "meaning_en": "thorn; prick; pierce; sting; assassinate", "meaning_es": "espina; pinchar; punzar; picar; asesinar", "radical": "刂", "radical_meaning_en": "knife / blade", "meaning_component": "朿 (brambles / thorns) + 刂 (sharp knife blade)", "sound_component": "朿 (cì)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "A thorny bramble 朿 combined with a sharp knife 刂; signifies pricking, stabbing, and stinging critique.", "visual_mnemonic_story_en": "A thorny plant (朿) with the sharpness of a knife (刂) that pricks and stings (刺).", "visual_mnemonic_story_es": "Una zarza espinosa (朿) tan punzante como una cuchilla (刂) que pincha y escuece (刺).", "tone_mnemonic_anchor": "51", "cangjie": "DBLN", "traditional": "刺"}], "extended_reading_passages": [{"id": "#1", "hanzi": "“纸上谈兵”作为流传两千余年的著名成语，不仅记录了长平之战的悲惨结局，更成为汉语中讽刺脱离实际、夸夸其谈的经典隐喻。这种鞭辟入里的历史讽刺，始终警醒着后人必须尊崇实践，切勿自欺欺人。", "pinyin": "'Zhǐshàng-tánbīng' zuòwéi liúchuán liǎng qiān yú nián de zhùmíng chéngyǔ, bùjǐn jìlù le Chángpíng zhī zhàn de bēicǎn jiéjú, gèng chéngwéi Hànyǔ zhōng fěngcì tuōlí shíjì, kuākuā-qítán de jīngdiǎn yǐnyù. Zhè zhǒng biānpì-rùlǐ de lìshǐ fěngcì, shǐzhōng jǐngxǐng zhe hòurén bìxū zūnchóng shíjiàn, qièwù zìqī-qīrén.", "en": "Passing down for two millennia, 'armchair strategy' not only chronicles Changping's tragedy but serves as Chinese's classic satire against impractical talkers. This piercing historical irony cautions us to honor practice and never deceive ourselves.", "es": "Con más de dos milenios de historia, 'estrategia en el papel' no solo narra la tragedia de Changping, sino que es la gran sátira china contra quienes teorizan sin base. Esta aguda ironía nos recuerda priorizar la práctica y evitar el autoengaño."}, {"id": "#2", "hanzi": "讽刺艺术向来被誉为社会改良的有力思想武器。无论古代寓言还是现代先锋戏剧，创作者借助精妙的隐喻与讽刺笔触，能够以幽默的形式直击时代弊病，唤醒沉睡的大众心灵，促使全社会反思并不断革故鼎新。", "pinyin": "Fěngcì yìshù xiànglái bèi yù wéi shèhuì gǎiliáng de yǒulì sīxiǎng wǔqì. Wúlùn gǔdài yùyán háishì xiàndài xiānfēng xìjù, chuàngzuòzhě jièzhù jīngmiào de yǐnyù yǔ fěngcì bǐchù, nénggòu yǐ yōumò de xíngshì zhíjī shídài bìbìng, huànxǐng chénshuì de dàzhòng xīnlíng, cùshǐ quán shèhuì fǎnsī bìng bùduàn gégù-dǐngxīn.", "en": "The art of satire has long been hailed as an intellectual weapon for social reform. In fables or avant-garde drama, through witty metaphor and satire, artists critique social ills and awaken public conscience to inspire reform.", "es": "El arte satírico ha sido considerado un instrumento de mejora social. Tanto en fábulas como en el teatro contemporáneo, mediante metáforas ingeniosas los autores exponen las dolencias de su época para impulsar una constante renovación cívica."}]}, {"meanings_summary": {"en": "flexible; agile; nimble; adaptable", "es": "flexible; ágil; adaptable; diestro; maniobrable"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A sharp spirit (灵) flowing dynamically like living water (活) gives supreme flexibility (灵活).", "composite_memory_hook_es": "Un ingenio despierto (灵) que fluye con dinamismo como agua viva (活) concede total flexibilidad (灵活).", "cultural_and_cognitive_roots": "Derives from Daoist and military metaphors likening adaptive wisdom to the ever-shifting flow of water.", "tone_sandhi_and_pitch_modulation": "Second tone to second tone: 'líng huó' (35-35). Two consecutive rising pitches smoothly chained."}, "semantic_boundary_contrasts": {"core_nuance": "灵活 emphasizes quick, responsive adaptation to changes in situations or physical agility.", "contrasts": [{"id": "1", "compared_word": "灵活 vs. 机智", "pinyin": "jīzhì", "analysis": "机智 emphasizes sharp wit and quick problem-solving during crises, while 灵活 denotes broader situational adaptability or physical agility."}, {"id": "2", "compared_word": "灵活 vs. 敏捷", "pinyin": "mǐnjié", "analysis": "敏捷 emphasizes high physical speed or rapid reflexes, while 灵活 emphasizes non-dogmatic adaptability."}, {"id": "3", "compared_word": "灵活 vs. 圆滑", "pinyin": "yuánhuá", "analysis": "圆滑 carries a distinctly negative connotation of being slick, unprincipled, and evasive in social dealings."}]}, "traps_and_cognates": {"look_alikes": [{"character": "寻", "pinyin": "xún", "meaning_en": "search; seek", "distinction_note": "Radical 寸 at bottom instead of 火"}, {"character": "录", "pinyin": "lù", "meaning_en": "record", "distinction_note": "Radical 氺 at bottom"}, {"character": "话", "pinyin": "huà", "meaning_en": "speech; language", "distinction_note": "Speech 讠 radical on left instead of water 氵"}, {"character": "适", "pinyin": "shì", "meaning_en": "suitable; fit", "distinction_note": "Walk 辶 radical enclosing 舌"}], "etymological_cognates": [{"character": "灵敏", "pinyin": "língmǐn", "gloss_en": "sensitive; keen; responsive"}, {"character": "活跃", "pinyin": "huóyuè", "gloss_en": "active; dynamic; brisk"}, {"character": "灵巧", "pinyin": "língqiǎo", "gloss_en": "dexterous; nimble; ingenious"}, {"character": "死板", "pinyin": "sǐbǎn", "gloss_en": "rigid; inflexible (antonym)"}]}, "id": "39", "hanzi": "灵活", "pinyin": "líng huó", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "agile and adaptable; not rigid or bound by dogma; adjusting readily to changing situations", "definition_es": "ágil y adaptable; no rígido ni atado al dogma; capaz de adecuarse con rapidez a situaciones cambiantes", "example_phrase": "灵活机动 (agile and flexible maneuver)"}], "example_sentences": [{"id": "#1", "hanzi": "真正善于带兵的将领深谙兵无常势之理，绝不死搬兵书阵法，而是根据敌地形势灵活机动地调整部署。", "pinyin": "Zhēnzhèng shànyú dài bīng de jiànglǐng shēn'ān bīng wú cháng shì zhī lǐ, jué bù sǐ bān bīngshū zhènfǎ, ér shì gēnjù dídì xíngshì línghuó jīdòng de tiáozhěng bùshǔ.", "en": "Generals skilled in command understand warfare has no constant posture; never rigidly copying diagrams, they flexibly adjust troop deployments according to conditions.", "es": "Los generales hábiles saben que la guerra no tiene esquemas fijos; lejos de copiar manuales, adecuan sus posiciones con suma agilidad según el enemigo."}, {"id": "#2", "hanzi": "在复杂的商务谈判中，既要坚定守护核心底线，也要根据对话氛围灵活变通具体的合作条款。", "pinyin": "Zài fùzá de shāngwù tánpàn zhōng, jì yào jiāndìng shǒuhù héxīn dǐxiàn, yě yào gēnjù duìhuà fēnwéi línghuó biàntōng jùtǐ de hézuò tiáokuǎn.", "en": "In complex commercial negotiations, one must firmly safeguard bottom lines while flexibly adapting specific collaboration clauses to the atmosphere.", "es": "En negociaciones comerciales complejas se debe defender la línea roja y, al mismo tiempo, adaptar las cláusulas contractuales con flexibilidad según el diálogo."}], "collocations": [{"hanzi": "灵活变通", "en": "adapt flexibly / accommodate changes"}, {"hanzi": "灵活运用", "en": "apply flexibly"}, {"hanzi": "头脑灵活", "en": "quick-witted / nimble mind"}, {"hanzi": "手脚灵活", "en": "nimble hands and feet / physically agile"}, {"hanzi": "机制灵活", "en": "flexible mechanism"}, {"hanzi": "灵活机动", "en": "agile and mobile"}], "idioms": [{"hanzi": "随机应变", "pinyin": "suí jī yìng biàn", "meaning_en": "adapt oneself to changing conditions; act according to circumstances"}, {"hanzi": "见机行事", "pinyin": "jiàn jī xíng shì", "meaning_en": "act as the occasion demands; act opportunely"}, {"hanzi": "通权达变", "pinyin": "tōng quán dá biàn", "meaning_en": "adapt to circumstances; be pragmatic and flexible"}, {"hanzi": "墨守成规", "pinyin": "mò shǒu chéng guī", "meaning_en": "stick stubbornly to outdated conventions; hidebound"}], "character_decomposition": [{"character": "灵", "pinyin": "líng", "meaning_en": "agile; clever; spirit; soul; effective", "meaning_es": "ágil; despierto; espíritu; alma; eficaz", "radical": "火", "radical_meaning_en": "fire", "meaning_component": "彐/雨 (celestial rain prayers) + 火 (sparkling fiery spirit)", "sound_component": "霝 (archaic phonetic in traditional 靈)", "stroke_count": "7", "composition_type": "上下结构", "etymology_and_mnemonic": "Spiritual quickness and briskness bursting forth like leaping flames 火; denotes agile wit and vitality.", "visual_mnemonic_story_en": "A quick spirit leaping agilely like sparkling flames (火) full of nimble wit (灵).", "visual_mnemonic_story_es": "Un espíritu despierto que salta como llamaradas ágiles (火) desbordando ingenio (灵).", "tone_mnemonic_anchor": "35", "cangjie": "SMF", "traditional": "靈"}, {"character": "活", "pinyin": "huó", "meaning_en": "live; alive; living; dynamic; lively", "meaning_es": "vivir; vivo; viviente; dinámico; suelto", "radical": "氵", "radical_meaning_en": "water", "meaning_component": "氵 (flowing water stream) + 舌 (active tongue)", "sound_component": "舌 (shé)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Water 氵 flowing with vital living momentum like an agile moving tongue 舌; signifies life and mobility.", "visual_mnemonic_story_en": "Fresh clear water (氵) babbling dynamically like a moving tongue (舌), full of vital life (活).", "visual_mnemonic_story_es": "Agua fresca (氵) que fluye sin cesar como una lengua ágil (舌), rebosante de vida dinámica (活).", "tone_mnemonic_anchor": "35", "cangjie": "EHR", "traditional": "活"}], "extended_reading_passages": [{"id": "#1", "hanzi": "孙子兵法精髓有云：“水因地而制流，兵因敌而制胜。”用兵的核心精义在于随机应变、灵活机动。秦将白起善于根据地形与敌情灵活调动兵力，而赵括死搬兵书阵法，最终导致赵军主力被全歼于崇山峻岭之中。", "pinyin": "Sūnzǐ bīngfǎ jīngsuǐ yǒu yún: 'Shuǐ yīn dì ér zhì liú, bīng yīn dí ér zhì shèng.' Yòngbīng de héxīn jīngyì zàiyú suíjī-yìngbiàn, línghuó jīdòng. Qín jiàng Bái Qǐ shànyú gēnjù dìxíng yǔ díqíng línghuó diàodòng bīnglì, ér Zhào Kuò sǐ bān bīngshū zhènfǎ, zuìzhōng dǎozhì Zhào jūn zhǔlì bèi quánjiān yú chóngshān-jùnlǐng zhīzhōng.", "en": "The Art of War states: 'Water shapes its course according to terrain; an army achieves victory by adapting to the enemy.' The soul of warfare lies in flexible mobility. Bai Qi adjusted deftly, while Zhao Kuo copied dogmatic plans, leading his army to total slaughter.", "es": "El Arte de la Guerra enseña: 'El agua amolda su cauce al terreno; el ejército forja la victoria adaptándose al adversario.' La clave radica en la agilidad táctica. Bai Qi adaptó sus tropas con maestría, mientras Zhao Kuo copió esquemas rígidos, condenando a su ejército."}, {"id": "#2", "hanzi": "当今时代科技日新月异，社会分工与竞争形态变幻莫测。无论是科技企业的商业模式创新，还是职场人士的技能迭代，墨守成规都难逃淘汰命运。唯有保持敏锐的洞察力与灵活变通的智慧，方能在滔滔浪潮中立于不败之地。", "pinyin": "Dāngjīn shídài kējì rìxīn-yuèyì, shèhuì fēngōng yǔ jìngzhēng xíngtài biànhuàn-mòcè. Wúlùn shì kējì qǐyè de shāngyè móshì chuàngxīn, háishì zhíchǎng rénshì de jìnéng diédài, mòshǒu-chéngguī dōu nántáo táotài mìngyùn. Wéiyǒu bǎochí mǐnruì de dòngchálì yǔ línghuó biàntōng de zhìhuì, fāng néng zài tāotāo làngcháo zhōng lìyú búbài zhī dì.", "en": "In today's era of rapid tech advancement, competition shifts unpredictably. Whether in corporate model innovations or personal skill building, clinging to obsolete formulas leads to obsolescence. Sharp insight and flexible adaptability ensure standing invincible amid the waves.", "es": "En un mundo de avances tecnológicos vertiginosos, la competencia evoluciona sin cesar. Tanto en modelos de negocio como en la superación laboral, aferrarse a lo viejo conduce al olvido. La agudeza y la flexibilidad constante son la clave para mantenerse invictos."}]}];
